window.__D("text/torat-shmuel/c025",{"p":[[2000500180,"אפי' רגע א' וכמו דגים שבים שמיד שמפורשין מן הים הם מתים, וברואי' שביבשה מיד שיורדי' לים א\"א להם לחיות אפי' זמן מועט והיינו מפני כי הדגים שבים ה\"ה ממהות המים ממש, ולכן לענין מקוה יש מי שסובר כל מי שהוא מבריאת המים ה\"ה כמים, והיינו שמהותם הוא ממהות המים ממש, ולכן דגים א\"צ שחיטה להיות כי גם לאחר שנבראו מן המים ה\"ה כמהות המים ממש, ועד\"ז יובן במלאכי' שנק' בשם נוני ימא וכן נשמות הגבוהות כמו רב המנונא סבא שנק' רב המנונא ל' נוני שהי' נשמתו דבוקה באלקות גם בהתלבשותה בגוף בבחי' דביקת נפלא בלי שום פירוד כלל, וכמו משה שא' על עצמו ונתתי מטר ארצכם שלכאו' איך יאמר הנברא ע\"ע כן אלא מפני שבמשה כתי' כי מן המים משיתיהו שהי' מעלמא דאתכסיא בחי' ים שהי' בטל בתכלית ונחנו מה בבחי' ביטול גמור כמו דגים שבים שא\"א להם ליפרד כלל, משא\"כ ברואי' שביבשה הגם כי מקבלים חיות מהארץ שהרי ארץ ממנה תצא לחם מ\"מ ה\"ה יכול לחיות כשט באויר או כשט במים, וגם בהיותו עומד עלה ארץ ה\"ה אינו מובלע כלל בארץ, כ\"א הוא באויר ובלתי אויר א\"י לחיות, ודגי הים עיקר חיותם מהמים לבד ולא מהאויר שהרי במים לא יש אויר וכנודע שפעולת המים הוא לדחות האויר כו' וא\"כ עיקר חיותם הוא מן המים לבד, ולפ\"ז נראה נגלה ההבדל שבין ים ליבשה, וענין הים הוא שמעלים על הנבראי' שבו לבלי יתגלו ליבשה כלל להיות עיקר חיותם תלוי בזה כו', ועד\"ז יובן באצי' העליון שבחי' ים הוא מה שכונס אורות האצי' בתוכו ואז יכול להיות מבחי' מל' דאצי' הנק' בשם ארץ להוות בי\"ע, אמנם בלתי כיסוי הים הרי הי' נגלה אור האצי' ומחמת גילוי אור האצי' לא הי' באפשרי כלל להתהוות בי\"ע, וענין קרי\"ס היינו שהפך ים ליבשה שגם ביבשה יתגלה גילוי אלקות כמו שהוא בעלמא דאתכסיא ולכן כאו\"א הראה באצבע וא' זה אלי,"],[2000500181,"דהנה כל הנביאי' נתנבאו בכה נוסף עליהם משה שנתנבא בזה והיינו כי משה כתי' בי' מן המים משיתיהו שהי' מעלמא דאתכסיא בחי' ים לכן הי' אצלו גילוי בבחי' זה כמו שורש נשמתו כמו שהיא בים כן היתה בהתלבשותו בגוף ולכן משה משה לא פסיק טעמא, אברהם אברהם פסיק טעמא והיינו כי באברהם אינו דומה אברהם שלמעלה לכמו שהי' מלובש בגוף, ובכל עולם מובדל בחי' אברהם שבעולם העליון לעולם שלמטה הימנו, אבל משה משה לא פסיק טעמא שמשה כמו שהוא בעולם העליון כן הי' בנשמתו המלובשת בגופו כו' והיינו מפני כי מן המים משיתיהו בחי' ים, ולכן נתנבא בזה כו', וא\"כ יובן מה שכאו\"א הראה באצבע זה אלי שזכו כולם לגילוי עלמא דאתכסיא. וביאור הענין הוא דהנה לא כל הנשמה מלובשת בגוף כי מה שמלובשת בגוף היא רק הארה ומקצת מן הנשמה לבד שהרי מלאך בשליש עולם עומד וכ\"ש נשמה שגבוה מן המלאך, אלא שמה שמאיר בגוף הוא רק הארה ומקצת מן הנשמה לבד ועיקר הנשמה היא למעלה וע\"ז ארז\"ל גבי חבירי דניאל על מ\"ש והאנשים אשר אתו לא ראו את המראה אבל חרדה גדולה נפלה עליהם ופריך מאחר דלא חזי למה נפל עליהם החרדה ומשני אע\"ג דאיהי לא חזי מזלי' חזי פי' מזלי' חזי שבבחי' שרש ומקור הנשמה בחי' מזל שם הוא חזי שמאיר בחי' ראי' באלקות, וא\"כ בקרי\"ס שראו עד שכאו\"א הראה באצבע זה אלי היינו מפני שהאיר בהם שרש ומקור הנשמה בחי' מזלי' שמזליי' חזי פי' שמאיר שם בחי' הראי' באלקות וע\"י שהאיר בחי' זו בגוף ראו כאו\"א עד שהראו באצבע פי' שהראו אחד לזולתו ראיית אלקות כו', וענין פי' עלמא דאתכסיא היינו שמכוסה ונעלם לגמרי מעלמא דאתגליא, ולכן בקרי\"ס כשהי' צריך להיות גילוי עלמא דאתכסיא נא' הפך ים ליבשה שנעשה היפך וסדר* השתלשלות לגמרי ונתגלה בחי' ומדריגה מה שלא יש כלל בעלמא דאתגליא, אמנם בר\"ה לא כן הוא כ\"א שישנו הכל רק שהם אחור באחור פי' כמו שני ב\"א שכ\"א הוא בציור פרצוף אדם רק שעומדים אחור באחור לא נמשך שום גילוי מא' לחבירו וכשמהפכים פניהם זל\"ז הרי נתגלה, ואין הענין שנתגלה מה שלא הי' תחלה כלל כ\"א שלא יהי' בבחי' חיצוני' לבד בחי' נה\"י שבו אלא שיומשך גם הפנימיות שבו ממה שישנו תחלה רק שהי' אב\"א יהי' בבחי' נסירה להיות פב\"פ הן במשפיע והן במקבל, וזהו שורש ענין הנסירה"],[2000500182,"להחזיר פב\"פ היינו פני המקבל אל פני המשפיע כו', והנה להחזיר פב\"פ ענינו פני המקבל אל פני המשפיע היינו אמרו לפני מלכיות פי' ע\"י אמירת הפסוקי' שבתורה שהיא פנימי' חכ' שבמ' דאצי' כידוע ונזכרו בהם ענין המלכו', בזה ממשיכי' פנימי' מדת מל' דאצי' לעשרה מאמרות ורוח פיו ית' עד\"מ כמו שרוממות המלך ב\"ו בעצמותו הוא רם ומתנשא מעל עבדיו עד התפשטו' גדולתו ואימתו עליהם הוא בבחי' אחוריי' וחיצוניות מן עצמיות רוממותו וכדי שישפיל עצמיות גדולתו ויהי' מלך עליהם בפקודותיו וכו' הוא ע\"י השבח שמשבחי' לפניו איכות התפשטו' המלוכה איך שעבדיו בטלים אליו כו' וע\"י השבח מעוררי' שיומשך מפנימי' גדולתו שיתפשט גדולתו עליהם בפקודותיו כו', כמ\"כ מובן למשכיל שע\"י הזכרות מלכו' שבפסוקי התורה דמתני' מלכתא שהם דברי חכ' המלך כמ\"ש במ\"א הם נמשכי' להאיר בעשרה מאמרות דהיינו שיהי' פנימי' חכמתו ורצונו בהתפשטו' המלוכה שהם הבלים ורוח פיו ית' מקור לבעלי גבול כידוע, ולהיות כי כנ\"י הוא פנימי' מ' דאצי' כידוע, לכן ע\"י התשובה בפנימי' הלב הם ממשיכי' ג\"כ הארת פנימי' מדת מלכותו ית' שיהי' מלך חפץ בחיים, ע\"כ זה הוא להחזיר פנימי' שבמקבל כדי להחיות רוח שפלים לבד כידוע, אבל החזרת פני המשפיע שלא יהי' השפעתו בבחי' נה\"י שבנה\"י שבו כנ\"ל כ\"א מבחי' פנימיותו ועצמיותו הוא ענין הזכרונות אתה זוכר מעשה עולם ופוקד כל יצורי קדם, פי' מעשה עולם הם בחי' קטנות שבז\"א כשהוא כלול תלת גו תלת דהיינו חג\"ת בנה\"י והוא בבטן אימא כו', דהנה ששת ימים תעבוד שית אלפי שני הוי עלמא שהם הארות מדותיו ית' כידוע בזמן הגלות אין בחי' המוחי' והפנימי' מאיר בו' ימי המעשה רק הוא בבחי' שינה אלקיכם ישן הוא ולכן מחי' ישראל והאומות בשוה, והענין כידוע בענין אח דלי\"ת שהארת המדות בפנימי' מל' הוא מבחי'"],[2000500183,"חיצוניות המדות מבחי' נה\"י שבנה\"י, כמשל מדות הנרגשי' בבשר הלב שגם בשינה יחיו את כל הגוף כי הלב פליג לכל שייפין המובחר שבחיות הדם תמיד ותמיד דופק בו החיות כו' אלא שהארות פנימי' המדות שבלב להנהגת הגוף לאהוב ולשנוא אינו אלא עפ\"י הארת השכל הנק' רוח ממללא כידוע, זה א\"א להיות בשינה כ\"א המדות טבעיות שבלא שכל כמו שהם בבהמה זהו גם בשינה שאז הסתלקות השכל לגמרי וגם פנימי' מהות המדות לאהוב ולשנוא והתפארות, רק בחי' נה\"י שבהם דהיינו כמו הרגשת אהבה טבעי' שבבשר הלב שהוא השפעת האהבה הרוחניות לבד ואף גם זאת איננה בשינה כ\"א בחי' נה\"י שבנה\"י דהיינו החיות הדופק בלב שהוא בחי' נה\"י לאהבה טבעי' שבלב, כמו שבבהמה חיות לבה יוליכה להמאכל אשר תחשוק בלבה וד\"ל, וכמ\"כ בחי' שינה בז\"א דאצי' הוא הסתלקות המוחי' שבמדות והוא רק בבחי' עיבור בבטן אימא, פי' שהמדות הפנימי' כולם בשעת השינה כלולי' בשכל ואינם נמשכים לדבר בפ\"ע כמו שהעובר ירך אמו הוא כמ\"כ ו' ימי המעשה הנק' ימי עולם ומעשה עולם הוא בחי' קטנות מאד ולגבי עצמיות מדותיו ית' כלא ממש חשיבי ויכול להיות בחי' שכחה עליהם כמו המתעסק באיזו ציור בלא כוונה בשכל אף שנמשך מן הלב כח פועל ידיו, מ\"מ כיון שלא הי' הציור בכוונת שכל בבחי' פנימי' המדה כו' יכול לשכוח לגמרי על מעשה ידיו כו' וצריך להזכיר לו פועל ידיו שעשה כך והוא צריך ליתן זכרון מוחו על הציור שהי' נשכח ממנו כאלו לא הי' ובשעת זכרונו על הציור הרי כח פועל הציור המצומצם מתעלה אז מקטניות צמצומו שלא הי' תופס מקום כלל, ועתה כשנזכר עליו נחשב לדבר מה כו' וכמו מלך גדול ששוכח על הפחות הערך מאד ליתן לו מתנה או לקרוא אותו לסעודתו כו' וכשנזכר עליו הרי הוא מעליהו בזכרונו מפחיתותו, וזהו אתה זוכר מעשה עולם שיומשך פנימי' מדותיו ית' ויזכור על מעשה עולם ובזה יתעלו להתפס מקום וזהו יעלה ויבא שזכרון פנימי' המשפיע על בחי' חיצוניות שבו ה\"ז העלא' לחיצוניות שלו כנ\"ל, וזהו זכרון אבותינו מפני שאברהם אוהבי הי' בחי' מרכבה לאהבה דאצי' לבחי' קטנות שבמדת חסד דאצי' ויכול לשכוח על הגבלת אהבת נשמת"],[2000500184,"אברהם (כמו המשל בעת השינה כאשר ימשוך ידו מחמת חיות שבלבו בלא כוונה שישכח ע\"ז אחר הקיצו כו' כמ\"כ חסד דרועא ימינא דז\"א כו' וד\"ל) וצריך להיות ע\"ז העלא' הזכרון כו' וכן אפי' בכל ו' ימי המעשה מה שיהי' יום שכולו שבת ויהי' עוד שמטה כו' כולם צריכי' לזכרון מאחר שכולם הם רק התפשטות אורות מן א\"ס ב\"ה מהעלם עצמותו ומהותו ית' וכנ\"ל וד\"ל, וזהו צופה ומביט עד סוף כל הדורות, היוצר יחד לבם כו' מפני שענין הזכרון הוא כמשל שיזכור האדם על ריבוי דבריו ומחשבותיו, שיהי' תנועת הזכרון כולל אותם בסקירה א' אף שהיו המחשבות והדבורים רבים מאד וכמ\"ש במ\"א, ומ\"מ אף שיכלול אותם ברגע הרי ירידה הוא לבחי' עצמיות שבו מאחר שהמחשבות והדבורים הם בחי' התפשטות שהי' ממנו לבד א\"כ מה שהוא נותן זכרון מוחו עליהם ויכללם הוא בחי' ירידה וצצום ממהותו העצמי, וזהו ויבא לשון המשכה מפני שהזכרון הוא ירידה למעלה למטה להיות צופה בסקירה א' כל הדורות וד\"ל.\n<b>והנה</b> כל זה הוא ענין הנסירה להחזיר פני המקבל שלא יהי' אב\"א ואז יומשך הזכרון שהוא פנימי' המשפיע וזהו בכל המדרגות עד רום המעלות כי מלכותך מלכות כל עולמים כידוע, אבל פנימי' המשפיע בלי החזרת פני המקבל א\"א כי פנים באחור אינו כלל בזווג אדם כו' רק בבהמה וד\"ל. והנה ענין זוכר הברית כי הנה הזכרון מפני שהוא ירידה מעצמיות המשפיע וצמצום עצמותו מאד לכן תיקנו לומר אב הרחמים זוכר יצוריו בברכת אתה גבור שברכת אתה גבור שם אגל\"א שהוא מקור הגבורות מהארת מ' דא\"ס שיהי' בחי' קו לבד כו' וכן כל העליות וירידות האורות וכלים דאצי' שהוא ענין השבירה והתיקון כידוע בשית אלפי שני האיש דרכו לכבש כו' הכל ע\"י בחי' גבורות וצמצום הקו אור א\"ס ב\"ה וזהו מקיים אמונתו לישיני"],[2000500185,"עפר כו' מי כמוך בעל גבורות ה' איש מלחמה להפך חשך לאור מה שנפל בשבירת הכלים הנק' ישיני עפר וכו', ולכן גם הזכירה על יצוריו אע\"פ שהוא מבחי' פנימי' הארת הקו כו', אבל להיותו ירידה לזכור כל ו' ימי המעשה והבירורים כו' ומה שיהי' עליי' באלף הז' ועוד שמטה כו' כי גם בגבורות שהוא התפשטות אור א\"ס ב\"ה אין דומה לך פי' למהו' א\"ס ב\"ה ממש כי מה שיהי' נ' אלף יובלות הכל הוא מבחי' קו כו' וד\"ל, וא\"כ גם הזכירה על התפשטות מעצמותו ומהותו הוא ג\"כ צמצום גדול ולכן נזכר בברכה זו אלא שמ\"מ נמשך הארת הזכירה מן רחמים רבים אב הרחמים הוא הזוכר יצוריו כי חסד הוא לגבי רוח שפלים כו', אך ענין התעוררות המשכת חסד זה שיומשך לזכור על אהבת אברהם מאחר שאין אהבת אברהם ערוך אל אור אהבה דאצי' כמ\"ש במ\"א בענין אנכי עפר ואפר, וכן באהבת כנ\"י שיעוררו על נשמתם אהבה עילאה אהבת עולם בית ישראל אהבת כו' הוא אשר נשבעת לאבותינו וכרת עמהם ברית וע\"י זכרון הברית הכרותה ביניהם הוא נזכר גם על מהות הגבלות נשמתם וזהו זוכר הברית, אך ענין השבועה והכריתת ברית הוא ענין ההתקשרות הנפלא כמו שני אוהבים נאמנים שאהבתם נפלאה בהיותם יחד וכשרוצים להפרד וכל א' יטרד מאד לזמן רב במקומות רחוקים כו' אזי כורתים ברית ושבועה שלא ישכח א' על חבירו אף בעת ריחוקם הגדול שהי' ראוי אז להיות השכחה מפני שנתעלמה אז האהבה מפני הריחוק בזמן ומקום כו' והנה ע\"י השבועה שנשבע א' לחבירו שלא ישכחנו לעולם אז בעת השבועה הוא ענין ההתקשרות הנפלא שמחמתה תעורר זכרון מוחו עליו אף בשעת ריחוקו מאד, והטעם מפני שהתקשרות זו הוא התערבות החיות כל א' ממשיך מחיות בחבירו עד שישאר הארת חיות חבירו כלול בו בהעלם, והוא המעורר הזכרון עליו כו', נמצא שהתקשרות זו הוא העולה על אהבתם הנפלא' ביתרון ההשפעה שמשפיע ומקשר חיותו בחבירו מה שלא הי' בהאהב' הנפלאה זאת ההשפעה והוא בחי' יסוד המשפיע האהבה וד\"ל, ובהשפעתו הוא מתקשר בהמקבל עד שהוא מוכרח לזכור עליו מפני חיותו שהשפיע בו וכמו שזוכר"],[2000500186,"הוא עצמותו תמיד כו' וכן מפני התקשרו' חיות המקבל בו מוכרח המקבל לזכור עליו כמו שהוא זוכר עצמותו כו' וד\"ל, וזהו אין האשה כורתת ברית מפני ששלימות' בהמשפיע ושלימות המשפיע בה וד\"ל ועפי\"ז יובן ענין השבועה משכונא דילי גבייכו לא מאסתים כו' אבל עת שיעוררו אהבתם יומשך עליהם אהבה אלקי' ע\"י ההתקשרו' השבועה שנשבע ה' לאבותינו וד\"ל וזוכר חסדי אבות ומביא גואל זכרנו לחיים שבברכת אבות הוא השבועה המעורר הזכרון שבברכת אתה גבור זוכר יצוריו כו'.\n<b>וז\"ע</b> החצוצרות כי הנה הרה\"מ ממעזריץ ז\"ל פי' חצוצרות שני חצאי צורות פי' שזהו ע\"י הכריתות ברית שכ\"א הוא רק חצי צורה וא\"כ ז\"ע השבועה אשר נשבעת לאבותינו, וזהו שופר של ר\"ה של יעל פי' ע\"ד שאה\"כ הרים הגבוהי' ליעלי' פי' הרים הוא בחי' אהבה ובבעלי תשובה הוא בחי' תשובה מעומקא דליבא ועי\"ז הוא בבחי' יעל ל' עולה ופי' מצופה זהב הוא בחי' אה\"ר ושני חצוצרות הוא ב' חצאי צורות שהוא נגד אמת דיעקב וחסד דאברהם שז\"ע אשר נשבעת לאבותינו ועכ\"ז שופר מאריך שמצות היום בשופר כי הנה ארז\"ל אמרו לפני כו' ובמה בשופר שע\"י השופר בחי' מן המצר קראתי עי\"ז בא לבחי' זכרון והמשכות מל' להיות מלוך כו' וגם במה בשופר מה הוא בחי' ביטול וע\"י השופר שמטיל חרדה עי\"ז בא לבחי' ביטול ואז ע\"י המצר שנעשה לו מפגמי' הקודמי' עי\"ז נמשך להיות במרחב י\"ה כו'."],[2000500187,"<h3>יוה\"כ אסור באכו\"ש כו'</h3>\n<b>בס\"ד מיוהכ\"פ</b>\n<b></b>שבת ויוה\"כ תענוג המורכב, הפשוט כו' שעיר לעזאזל כו' כבישה, כביסה\nמחרת יוהכ\"פ\n<b>יוהכ\"פ</b> אסור באכילה ושתי' ורחיצה כו' שיום הוא שנאסר בה' עינוים ולכאו' צ\"ל הלא יוהכ\"פ נק' שבת שבתון ובשבת מצוה לאכול וכמארז\"ל במה מענגו באכו\"ש ויש ג' סעודות מה שבכל יום הוא רק ב' סעודות כמ\"ש בערב כו' ובבוקר תשבעו לחם, וביוהכ\"פ שהוא שבת שבתון הוא עינוי בה' דברים הנ\"ל, ויובן בהקדם השבת שהוא השביתה מששת ימי החול שכל יומא עביד עבידתא, ובשבת הוא השביתה ועד\"מ אדם שעושה מלאכה המוחין שלו מוטרדים בהמלאכה, והגם כי ידיו הם העושים מ\"מ מתייחס עשיית המלאכה להמוחין וכששובת אז מתעלי' המוחין ומתענג מהמלאכה שנעשית בטוב וז\"ע השבת שהוא בחי' התענוג כי שבת דמעלי שבתא היא החזרת המוחין, ולכן א\"א להיות שבת כ\"א שתחלה יהי' חול, ולכן המהלך במדבר מונה ששה ומשמר יום א' שצ\"ל תחלה מונה ששה, ושבתא דיומא הוא בחי' המשכת העונג, והנה עונג זה הוא תענוג מורכב והיינו שהוא מורכב מהדבר שממנה נמשך העונג שהרי בלתי דבר זה לא יש ממה לקבל תענוג והגם כי עצם ענין העונג אינו נמשך מדבר זה כ\"א מעצמיות התענוג עכ\"ז מאחר שזה סיבה שיומשך הארת העונג ה\"ה קשור בו דוקא וגם זה מורה כי לא נמשך מהתענוג רק הארה לבד ולא העצם, וזהו דכתי' וקראת לשבת ענג שצריך לקרות היינו להמשיך העונג מפני כי העונג מורכב כנ\"ל,"],[2000500188,"וזהו אז תתענג על הוי' שדרשו בזהר על סעודת שבת כי פי' על הוי' הוא כי ש' הוי' לשון מהוה, והיינו דכתי' מה רבו מעשיך הוי', וכתי' מה גדלו מעשיך הוי' שכולם נעשו מש' הוי' כי הוא צוה ונבראו, והגם כי ברא אלקי' מ\"מ המצוה הוא שם הוי' ועל שם הוי' זה תתענג על הוי' וזהו בשבת, ולכן צ\"ל סעודה, רק שבסעודה שלישית יוצאין בפירות או מיני תורגימא מפני כי כתי' היום לא שגם ע\"י לא ממשיכים זה והוא מפני כי בסעודה ג' היא סעודתא דעתיקא, אבל בשני סעודות הקודמים צ\"ל פת דוקא, להיות כי צ\"ל איזה דבר שיומשך התענוג עליו, וגם בשינה אמרו ר\"ת שבת שינה בשבת תענוג שכ\"ז הוא תענוג המורכב מאכו\"ש ושינה, ולמעלה הוא שמתענג מכל אשר עשה כו'.\n<b>אמנם</b> יוהכ\"פ הוא שמאיר בו עצם תענוג הפשוט לגמרי ומובדל מכל דבר והיינו כי לאחר שעשו ישראל תשובה על כל עוונותיהם הרי אז כאילו קיימו כל המצות בפועל ויותר מכן שהרי במקום שבע\"ת עומדים אין צ\"ג כו', א\"כ יובן למעלה שכל התומ\"צ הם בחי' רצון העליון והיינו מה שרצון הוא אותיות צנור שהם צנורות פרטים כו' ולכן הם נק' רצה\"ע שהוא מה שארז\"ל נח\"ר לפני שאמרתי ונעשה רצוני, ואמנם מצות התשובה היא רמה ונשאה שמעוררת לבעהר\"צ שלכן התשובה מועיל על הכל ואין לך דבר שעומד כו' ועכ\"ז הרי תשובה היא דבר פרטי וא\"כ לכאו' העונג הנמשך ממנה ה\"ז"],[2000500189,"מורכב כמו עונג דשבת כי מה לי אם מורכב מזה או מזה איך שיהי' מורכב הוא אמנם באמת לא כן הוא שהרי אין התשובה הוא כמו כל המצות שעל כל המצות נצטוינו לעשות בהכרח אבל תשובה הרי אם לא יחטא א\"צ לתשובה כלל, ומה שמ' אתא לאתבא צדיקייא בתיובתא י\"ל שזהו בדקות מאד וגם כי לפ\"ע מעלת הצדיק ג\"ז יחשב לחטא אמנם בלתי שום חטא פי' חסרון א\"צ לתשובה כלל, א\"כ אין העונג מעשיית הדבר כ\"א כשצריכין לה וא\"כ אין שייך לומר שמתענג מזה כ\"א שאם לא היו צריכין כלל לתשובה הי' עוד יותר טוב, וא\"כ לפ\"ז הי' עשיית המצות העלאה לעונג זה אך באמת מה שהי' נמשך ע\"י העונג המצות ואפשר גם ע\"י התשובה מאחר שבשם מצוה יקרא ה\"ז יכול לקרות תענוג מורכב אלא שזהו ורכב בבחי' היותר גדול שהרי זה מורכב ברוחניות משא\"כ העונג מכל אשר עשה מורכב בגשמיות, ואמנם ענין יוהכ\"פ הוא שנק' שבת שבתון הוא שבתו של שבת פי' ששבת גם מהשביתה דשבת שהוא התענוג המורכב כ\"א שנמשך עונג העצם שאינו מורכב כלל, ולכן מצינו ביוהכ\"פ שהי' עבודה מה שבימי החול לא נמצא כזה כלל, והוא שעיר המשתלח לעזאזל דכתי' ונשא השעיר כו' ארץ גזירה ע\"י שהתוודה עליו כל עוונות בנ\"י, ולכאו' צ\"ל מה\"ע הוידוי שאפי' אם יעמיק דעתו במחשבתו בתשובה אמיתית אין זה מועיל כמו הווידוי בפה ולכן תקנו לומר ע\"ח ואשמנו יו\"ד פעמים ביוהכ\"פ בכדי שיגיע לכל כח מעשר כחות הנפש ע\"ח שלם, ולכאו' מה ענינו, אך הענין הוא דהנה ע\"י חטא ופגם גורם שני דברים הא' הסתלקות הקדושה כי לא יגורך רע וטהור עינים מראות ברע, והב' הוא שנמשך מהקדושה יניקה לסט\"א במקום שפגם, ולזאת ע\"י התשובה מעומקא דלבא ממשיך מהקדושה שיומשך מאוא\"ס הממלא כל הפגמי' למלאות הפגם"],[2000500190,"והעון, ובכדי שלא ינקו ממקום הפגום ומקולקל עי\"ז הרי הוידוי בפה שעי\"ז מדחה יניקתם לגמרי שלא יקבלו כלל והיינו כי הדבור הוא בחי' מעשה שבכחות הנפש הפנימי', וגם כי עקימת שפתים הוי מעשה ולכן כמו שפגם ע\"י מעשה בפו\"מ כן ע\"י התשובה בפו\"מ במעשה מרפא מקום שפגם לבלי יקרבו זרים לינק מהקדושה כו', וז\"ע הפלוגתא דב\"ש וב\"ה שב\"ש אומרים יכבוש עוונותינו מל' כובש פי' שכובש העון אבל עון עצמו אינו נמחק, אבל ב\"ה סברי יכבוש מל' כיבוס שמכבס גם מקום העון עצמו שמלבין גם שם, פי' שכל אדם יש לו נפש עכ\"פ ממל' דמל' דעשייה ולכן ע\"י שפגם עי\"ז נעשה פגם שמסתלק הארת אלקות שמאיר במל' דמל' דעשייה על חלקו, וגם בכלי המל' נעשה פגם שיונקי' הסט\"א מזה אמנם ע\"י התשובה מעומקא דלבא עי\"ז נמשך המשכת אלקות במל' דמל' דעשייה, וע\"י וידוי פה מתרפא גם כלי המל' דמל' הנ\"ל שלא יומשך שום שפע מותרות לסט\"א, וכ\"ה במי שיש לו רוח דיצי' או נשמה דבריאה, אבל חי' דאצי' אינה חוטא כלל לפי שלא יגורך רע, ולכן במי שחטאו נסתלקו תחלה מהם הארות האצי' כו', וההפרש בין נפש דעשייה לרוח ונשמה דיצי' ובריאה הוא בענין ההתדבקות לסט\"א ע\"י החטא שהרי בעשיי' רובה רע לכן שם נדבק באופן אחר, וביצי' ששם מחצה על מחצה ובבריאה ששם רובו טוב אין ההתדבקות וההתערבות כ\"כ ולכן כתי' ונפש כי תחטא, אמנם מזה עצמו יובן שהפגם שביצי' ועשייה הוא יותר הרבה שהרי ביצי' ששם מחצה על מחצה והוא העריבם וכ\"ש בבריאה ששם רובו טוב והוא פעל בחטאיו לערב הסט\"א עם הקדושה והרי הם יונקים ממקום שרובו טוב, ולזה צריכים ע\"י התשובה בוידוי פה לרפאות מקום הפגום שלא ימשך שום יניקה לסט\"א, וז\"ע שילוח שעיר המשתלח לעזאזל פי' כי תחלה נא' וכפר על הקדש פי' וענין הכפרה להפריד בין התערובות שנתערב הקדושה בסט\"א, ומה ששולחי' לו השעיר הוא כי מוטב שיומשך לו מעט מן הקדושה משיהי' מעורב ח\"ו, כי לפוטרו בלא כלום א\"א כי טוען מה לי תשובתו הלא נהנה מהחטא, ורק הקב\"ה שהוא טוב וישר מקבל תשובה כמארז\"ל שאלו"],[2000500191,"להקב\"ה אמר יעשה תשובה אבל בלעו\"ז אינו רוצה בלי כלום ולכן נותני' לו שעיר שהוא בחי' עזים פי' שנותנים לו מעט יותר ממקום יניקתו עצמו ועי\"ז מתרצה ולהיות כן נעשה שלום בין הסט\"א והקדושה ואינה מקטרגת ולכן יכול להיות נמשך אז מעצם העונג הפשוט שה\"ז הוא בערך כמו אדה\"ר לפני החטא, ולכן אסור באכו\"ש וכל הה' דברים בכדי שלא להרכיב התענוג בדבר אחר כ\"א יהי' פשוט בתכלית הפשיטות וע\"ד עוה\"ב פי' תחה\"מ שיהי' מבחי' טלא דנטיף מעתיקא שעי\"ז יחיו המתים אין בו לא אכילה ולא שתי' כ\"א שהגוף גשמי שיהי' ניזון מרוחניות והיינו כי עכשיו אין עצו ופריו שוים אבל לע\"ל יהי' עצו ופריו שוים כפי הציווי עץ פרי, והיינו שלע\"ל גם הגשמיות יקבלו חיות כמו הרוחניות והיינו כי גוף האדם לא יצטרך לאכו\"ש כ\"א יהי' ניזון מרוחניות כמו הנשמה שהיא חלק אלק' ממעל, והוא מפני כי לע\"ל יזדכך העולם שגם הגשמיות יזדכך לקבל חיותם מן הרוחניות ועד\"ז הוא יוהכ\"פ שאין בו לא אכו\"ש ולא שא\"ד ע\"ד דוגמת עוה\"ב כו', ובד\"פ יש בכל יום מעין זה והוא ענין הוידוי כל יום בתפלה ובק\"ש שעהמ\"ט, וכמו יוהכ\"פ שאסור באכו\"ש כמו\"כ קודם התפלה אסור לאכול ולשתות משקה (זולת מים חמים התירו מפני חלישות הדור אבל מעצם הדין ג\"ז אסור) וה\"ז כמו יוהכ\"פ והיינו שזהו הארת יוהכ\"פ שבכל השנה כו'."],[2000500192,"<h3>ושאבתם מים כו'</h3>\n<b>בס\"ד חגה\"ס</b>\n<b></b>נסוך המים בלא מדה משא\"כ נסוך היין כו' חו\"ב\nחג הסוכות\n<b>ושאבתם</b> מים בששון ממעייני הישועה, להבין ענין ניסוך המים בחג שהוא בלא מדה וניסוך היין כל השנה שהוא ג' לפר כו', הנה ענין ניסוך היין שהוא מבחי' בינה מקור הגבורות והוא העלאת הקרבנות באש של מעלה וכן התפלה ברשפי אש ההסתלקו' מאחר דכולא קמי' כלא א\"כ צ\"ל ביטול היש באין מקורו כידוע, אך אין זאת מבחי' התיקון כי לא לתהו בראה אלא לשבת יצרה, פי' ענין עולם התהו הוא הסתלקות האורות מן הכלים כידוע, וטעם ההסתלקות הוא כמשל אש הגשמי הנאחז בקיסם הדולק שכאשר יכלה וישרף הקיסם הרי אין להאש במה להתאחז ולימשך מלמעלמ\"ט, אז יסתלק למקור האש היסודי ולא יאיר ויהי' חשך ובאמצעית אחיזת הקיסם בו שהוא תנועת היפכו שלא יסתלק מזה בא ההארה שיאיר ולא יסתלק לגמרי כו', אך אם לא הי' בו בחי' ההסתלקות כלל לא הי' מאיר ג\"כ כמו במקום שאין אויר כחפירה שבעומק הארץ וכדומה שיכבה במהרה כידוע, נמצא שמשני ההפכי' ההמשכה וההסתלקו' יהי' סיבת הארתו, דהיינו המשכת הכלי שימשכנו"],[2000500193,"אצלו יעשה את בחי' הסתלקותו הטבעי שיהי' במדה גזורה ומחמת זה יאיר, ואופן ריבוי או מיעוט הארתו הוא לפי אופן ריבוי הכלים שימשיכוהו ביותר או שיגרמו הסתלקותו ביותר כו', ועפי\"ז יובן למשכיל ענין גבורות ממותקו' בחי' התיקון לגבורות שבתהו שהי' מיעוט הכלים, ולא לתהו בראה פי' לא הי' המשכות האורות דאצי' בתחלה בשביל עצם האורות שהרי מדרגתם מאד נעלה כשאינם נמשכי' בכלים כלל ואינם מאירים כלל כי כל הארה הוא לשלמטה הימנו, אלא לשבת בכלים יצרם פי' שיהי' בהם בחי' הארה דהיינו בחי' מקור דמקור לבעלי גבול דבי\"ע ע\"י הכלים שהם הפכים להם המגבילי' את האור שהם בחי' אותיות כידוע, וזהו ניסוך היין כל השנה שהוא גזור במדה וגבול לכל קרבן דהיינו ערך העלא' הקרבן מלמטלמ\"ע אם יהי' הסתלקות גדול או קטן הוא ענין היין המנוסך עליו שהוא גבורות דבינה עילאה אם הבנים ולפר שהוא העלא' גדולה צ\"ל ג' לוגין, וכמ\"כ ברשפי אש שבתפלה צ\"ל ממותקות ע\"י הכלים ואינו אלא עפ\"י הבינה שבנפש שממנה נמשך הרשפי אש בחי' הסתלקות, וזהו שפיר אמר מט\"ט דארמי מיא לגו חמרא שהוא בחי' התיקון להמתיק הגבורות ע\"י הכלים ששרשם מבחי' חסדי' כמ\"ש במ\"א.\n<b>והנה</b> מוח חכ' הוא מקור החסדי' שהוא קר ולח בטבעו ונק' מים ע\"ש לחלוחי' מים שנמשך ממנו והוא אהבה רבה שבמוח בינה בהתגלות אבל מוח חכ' עצמו הוא ענין הביטול האמיתי בחי' מ\"ה דהיינו שאין בו בחי' הסתלקות היש לגבי האין מקורו כנ\"ל אלא הוא אדוק וקשור בהאין עצמו המהוה את היש כי כל בחי' שמיעה והתבוננו' הוא כשאלקו' בחי' אין המהוה הוא מרחוק אצלו וצריך הוא בחי' הסתלקו' בנקודת הלב להתפשט מן הגבלתו כו', אבל כשבחי' אין המהוה מקרוב בנפשו דהיינו שכבר הדבר כן וכמ\"ש במ\"א"],[2000500194,"בפסוק אם זכרתיך על יצועי אז לא יהי' בכלל המשכה כלל שיהי' לו אהבה רבה והמשכה גדולה מפני הוא דבוק וסמוך מאד אל בחי' אלקו' המהוה מאין ליש ואז הוא בבחי' ביטול אמיתי מכל כחות נפשו אוי\"ר כו' כמשל המשתחוה לפני המלך בקרוב מאד שיהי' בו ביטול הרגש עצמותו מכל וכל מפני הקירוב וכל מה שמתרחק קצת יותר ירגיש יותר עצמותו אלא שיומשך מאד כידוע, וזהו על ראשי החיות כעין הקרח הנורא הוא בחי' חכ' כח מ\"ה המהוה אותם מאין ליש ששם התלבשות אור א\"ס ב\"ה כידוע מפני הביטול שבכח מ\"ה, וזהו הקרח כמו משליך קרחו דאגלידו מים עליונים כח המשפיע והמהווה שהוא בחי' א\"ס אינם עדיין בבחי' המים שהוא ההמשכה לירד ממקום גבוה כו' אלא הם נגלדי' כקרח שאינם נמשכי' כלל והוא כח מ\"ה שעל ראשי החיות כולם בחכ' עשית כידוע, והנה ישראל אכלו מצה שהם חסדי' דאבא ופי' אבא ידוע שהוא מקור השכל הגלוי ואינו בכלל השגה עדיין ולהיות כי להיות שורה בנפשם בחי' אין ממש השורה בכח מ\"ה שבנפש שאינו עדיין בכלל התבוננו' איזה טעם ודעת באלקות איך הוא מהוה שההשגה והטעם איך שהוא מהוה כו' הוא בחי' בינה הרחוק מאד מן בחי' נקודה העיקרי' דהיינו שהוא כבר מהוה כידוע, והוא בחי' מוח חכ' שהוא הקרירות וגלידת מים עליונים בחי' אלקו' ממש כנ\"ל ולהיות שהיו בבחי' קטנות המוחין אפי' להיות בנפשם הטעם וההשגה באלקו' בהרחקת ההתבוננו' איך שהוא מהוה הנק' בינה לכן ציוה ה' שיאכלו מצה והוא טעם דגן שיש בו הארת מוח חכ' בהעלם כמו שאין התינוק יודע לקרות אבא עד שיטעום טעם דגן אז ידע לקרותו אבא, וענין ידיעה וקריאה זו איננה בבחי' השגה וטעם ודעת שיבין שהוא אביו מפני שהולידו אלא קוריהו אבא בלא השגת טעם כלל והרי בקרותו אבא יש בו הטעם בהעלם ואפי' הדבר שלמעלה מן הטעם דהיינו ההבחנה עצמה שהוא מבחין וקוריהו אביו מפני שהוא אביו באמת כו' בלי שידע הטעם כמו הגדול שיקרא אבי הרי הארת בחי' ההולדה עצמה בקריאה זו ולא השגת ההולדה לבד,"],[2000500195,"אך בקטן מוח החכ' דהיינו הארת אביו בו כמו שהוא באמת היא בבחי' קטנות וירידה דהיינו שלא נמשך אלא בבחי' התקשרות לבד מה שהוא נמשך אחריו כו', ובגדול הוא בבחי' גדלות שיקרא אבא כמו שהוא באמת כו', ועפי\"ז יובן שבחי' חכ' העצמי' המהוה כל הנבראי' לא הי' ביכולתם עדיין שיקראוהו אבינו כמו שהוא באמת ואפי' ההשגה איך דכולא קמי' כו' רק העלם החכ' בקטנות שידעו לקרות אבא לבד הי' ע\"י אכילת מצד שהי' כמו סגולה באכילתם ז' ימים שיהי' מוח אבא כולם בחכ' עשית מאיר בנפשם והיינו אכילת המן לחם מן השמים.\n<b>והנה</b> ניסוך המים הוא שאיבת מי החכ' בחי' ביטול האמיתי שאינו עדיין בכלל המשכה כנ\"ל וכשבא לכלל ניסוך והמשכה מלמעלמ\"ט דהיינו שיהי' הארת מוח החכ' דאצי' בנפש האלקי' לפי ערך הגבלתה וכן בדרך כלל אפי' בחכ' שבמ' דאצי' שהיא חכ' דבי\"ע כידוע זה נק' ניסוך המים שהוא בלא מדה דוקא והוא בחי' קרירות דוקא להמתיק האש של המזבח עילאה דהיינו לכבותו שיוכלל בחסדי' ממש (ואינו דומה לנסכי היין שאינו אלא שעפ\"י הכלים המונעים בחי' הסתלקותו לבד כו'), אך שאיבת מי החכ' א\"א אלא בשמחה שבבינה וימינו תחבקני כל ימי הסוכות כידוע שהם בחי' מקיפי', וענין המקיף ידוע כמו מה שאינו נכנס בכלי המוח בהשגה גמורה כ\"א מרחוק נדמה לו שהוא משיג אפס קצה ההשגה שאז ההשגה על כלי מוחו בבחי' מקיף, ועד\"ז בחי' מקיף דבינה עילאה אם הבנים על בי\"ע ונשמות ישראל בבחי' חביקה שאינו כמו זווג שהוא בבחי' השפעה פנימי' אבל החביקה באחורי חבירו הוא בחי' הקירוב שמבחוץ לגופו כו' וכמ\"ש במ\"א, כמ\"כ ימינו אהבה עליונה דאצי' שמחבקת נשמת כל א' מישראל ענינה שאינו מרגישה בבחי' פנימי' בנפשו כמו שבר\"ה עד אחר יו\"כ נכנסי' חסדי' פנימי' פי' שנכנס הארת אהבה עליונה בנשמה לפי ערכה לבד, וזהו אמירת המלכיות שנמשך בחי' יראה עילאה בכל נפש לפי ערך קבלתה לבד, וכן חסדי' שאחר יו\"כ במחילת העוונות נמשכי' בבחי' א\"פ לבד, אבל סוכה פסלו בה דירת קבע דהיינו כפי שהוא דר כל השנה בבחי' פנימי לפי מזגו כו' והוא לשון קבע שקבוע בנפשו אבל סכך הסוכה לפי שהוא השרא' המקיף שאינו מרגיש צ\"ל דוקא דירת עראי לפי שעה לבד לא בדרך קביעות וכן לא יקבל טומאה כי לא בא לכלל חו\"ג"],[2000500196,"עדיין כו', אך בחביקה זו שבימי החג מתעלי' הנשמות ויכולים לקבל ניסוך המים בחי' חכ' כו' כמו החובק את חבירו ומגביהנו בחביקתו אך אינה אלא כאשר תהי' החביקה בשמחה גדולה כמשל תינוק שהי' בבית השבי' ויצא לחירות כשרואהו אביו ישמח בו מאד ויחבקנו מחמת גודל השמחה אז יגביהנו בחביקתו פי' שיאיר בו מבחי' פנימי' נפשו שהוא למעלה ממדרג' התינוק כי לא יבין התינוק שמחת אביו איך ומה היא אך שמחת אביו יקיפו מבחוץ עד שישמח גם התינוק והוא ענין זמן שמחתינו כמ\"ש במ\"א.\n<b>והנה</b> אם הבנים שמחה מהסרת העוונות וכנ\"ל כל ימי החג והוא בחי' חיצוניות בינה שהוא מקור הגבורות של ניסוך היין כי חג לה' ז' ימים, וענין החג לשון אש הוא וחגותם חג וכמו חגים ינקופו וכמו אסרו חג שהוא הקרבן הניתן על האש וג\"כ לשון רקידה כמ\"ש השיר יהי' לכם כליל התקדש חג כו' והוא מורה על ענין הגבורות שברשפי אש התשוקה מלמטלמ\"ע, אלא שניסוך המים הוא המקרר את רשפי אש החג, והענין הוא כי זהו ענין לשון שמחת בית השואבה שצ\"ל השאיבה בשמחה דוקא להיות כי עד\"מ משמחת המלך מבנו שיצא מן השבי' שמפני שהמלך בתענוג ושמחה גדולה אז יוכל לעשות דבר מה שלא הי' עושה עד הנה והוא שילך לאוצרותיו ויגלה לבנו כל מחמדי' שבאוצרו ועוד זאת יוכל להיות שע\"י השמחה והתענוג יתן לבנו מתנה כלי נחמד ויקר מאד שהמלך מתענג בו מאד מאד עד שאין התענוג והשמחה שיש לו כעת מן בנו ערוך אל התענוג שמהכלי היקר מאד נעלה כי הנה טבע השמחה לעשות שלא בהדרגה לכן יכול ליתן מתנות בעת שמחתו מה שהם יקרים בעצמותם מן השמחה עצמה, ועפ\"י משל זה יובן למשכיל שהשמחה של המקיפי' דאימא בחג הסוכות יכול לעשות שלא בהדרגה דהיינו שיהי' בחי' ניסוך המים שאיבת החכ' בחי' ביטול האמיתי שבה התלבשות אור א\"ס ב\"ה דהיינו בחי' האין ממש המהוה כנ\"ל שהוא גבוה מאד נעלה משמחת אם הבנים ממה שיצאו הבנים מהשבי', וזהו ותתן לנו ה' אלקינו אחר שרוממתנו מכל הלשונות מחמת כי שמך הגדול אם הבנים נקרא עלינו דהיינו השמחה שבאהבה רבה שבהתבוננו' הנק' מקיפי' דאימא וימינו תחבקני ע\"י מצות הסכך ואז נתרוממה כללות נש\"י ויכולה לקבל מתנת ה' אלקינו שהוא השאיבה ממי החכ' שה' יהי' אלקינו תמיד דהיינו מוח החכ' והזכרון בבחי' האין המהוה תמיד והוא ענין ניסוך המים כנ\"ל, וענין ותתן לנו הוא השאיבה מחכ' עילאה כמשל השואב בכד ממעיין עמוק מאד מן כל חכמי"],[2000500197,"ישראל עיני העדה היו שמחים בשמחת בית השואבה להמשיך בכדים כח מ\"ה לכללות נש\"י מן מקור מעיין חכ' עילאה כולם בחכ' עשית וכידוע, וכמו הלל הזקן שהי' מרקד בביטול גדול כו'.\n—————— ּ ——————"],[2000500198,"<h3>ביום השמיני שלח כו'</h3>\n<b>בס\"ד, שמע\"צ</b>\n<b></b>דבקו שערים כו' ארון כו' חו\"כ ארוסין ונשואין בתורה (א)\nשמע\"צ\n<b>ביום</b> השמיני שלח את העם ויברכו את המלך וילכו לאהליהם שמחים וטובי לב על כל הטובה כו' לדוד עבדו כו', וארז\"ל בשעה שביקש שלמה להכניס את הארון להיכל קהק\"ד דבקו שערים כו' אמר ך\"ד רננות ולא נענה, כיון שאמר ה' אלקי' אל תשב פני משיחך זכרה לחסדי דוד עבדך (דה\"י ב' סוף סי' וא\"ו) מיד נענה, וצ\"ל למה דבקו שערי' והלא שלמה בנה בהמק\"ד ז' שני' וטרח ויגע הרבה מאד, והשתדל לבנותו מהרה שהרי בבנין ביתו נתרשל ובנה אותה י\"ג שנים ובהמק\"ד בנה בז' שנים ואחר רוב העמל והיגיע שלו דבקו שערים כו', ויש דיעה במדרש ששכח שלמה ועשה את הארון יו\"ד אמה ושערי ההיכל הי' ג\"כ יו\"ד אמות ואין אמה נכנסת באמה, אמנם לשון רז\"ל לא משמע כן שהרי אמרו דבקו שערי' שמשמע שאם השערי' לא הי' נדבקי' הי' נכנס וסיבת מניעת הכנסו הוא מחמת שדבקו שערי', משמע שעשו אותו כדין אמתים וחצי כו' אלא שדבקו שערי' שמוכרח לומר שזה הי' מחמת איזה חטא"],[2000500199,"ועון וצ\"ל מהו, הנה הארון נק' ארון הברית אדון כל הארץ כמ\"ש (יהושע ג' י\"א) הנה ארון הברית אדון כל הארץ עובר לפניהם בירדן, נשמע מזה שארון הברית עצמו הוא אדון כל הארץ, והענין הוא דהנה ארון הברית הוא תושב\"כ ותושבע\"פ שלוחות הברית שהיו מונחי' בארון הם בחי' תושב\"כ והארון עצמו הוא בחי' תושבע\"פ, והיינו שכמו הארון הי' כלי להלוחות שהיו מונחי' בו כן תושבע\"פ הם כלי לתושב\"כ שכמו ע\"י הארון הי' לוקחי' הלוחות כן ע\"י תושבע\"פ לוקחי' תושב\"כ ומקיימי' שהרי בלתי תושבע\"פ א\"א לקיים כלל תושב\"כ עד\"מ מצות תפילין כתי' ולטוטפות בין עיניך הרי לא נתבאר כלל איך לעשות התפילין ובתושבע\"פ מבואר הכל איך לעשותם, או בשבת דכתי' ל\"ת כל מלאכה והייתי סבור שטלטול משא בבית ממקום למקום זהו מלאכה, ובתושבע\"פ מבארי' ומגלים הכל, שטלטול משא בבית זהו מדרבנן ומלאכות הם ל\"ט מלאכות אבות מלאכות ויש להם תולדות שנמצא ע\"י תושבע\"פ מתבאר המצוה הנאמר בתושב\"כ איך לעשותה ובתושבע\"פ מתגלה תושב\"כ וה\"ז כמו הארון שהלוחות היו מונחי' גלוים בתוכו וע\"י הארון היו לוקחי' אותם, וזהו שנק' ארון ל' אור וגילוי היינו שע\"י מתגלי' האמור בהלוחות כמו שבתושבע\"פ מתבאר הנאמר בתושב\"כ כו'.\n<b>וביאור</b> הענין, דהנה תורה נק' כלה כמארז\"ל ע\"פ תורה צוה לנו משה מורשה א\"ת מורשה אלא מאורסה שנק' התורה כלה, ופעם אמרו צאנה וראינה כו' ביום חתונתו, זו מ\"ת שנק' הקב\"ה בשם חתן וכנס\"י נק' כלה והתורה היא השפעת חתן לכלה, והענין הוא דהנה תושב\"כ ותושבע\"פ נק'"],[2000500200,"חתן וכלה, ויובן זה מענין אדם וחוה שנק' ג\"כ בחי' תושב\"כ ותושבע\"פ, כי אדם הוא בחי' תושב\"כ וכמ\"ש זאת התורה אדם, וכמו האדם הוא שכלול מרמ\"ח איברין ושס\"ה גידין כן תושב\"כ הוא רמ\"ח מצ\"ע שהם רמ\"ח איברין דמלכא, ושס\"ה ל\"ת הם שס\"ה גידין, וזהו יום ליום יביע אומר פי' יום ליום קאי על תושב\"כ ולכן משה כשהי' בהר מאין הי' יודע זמן יום ולילה כשלמדו עמו תושב\"כ ידע שהוא יום וכשלמדו עמו תושבע\"פ ידע שהוא לילה, פי' יביע כמשל נביעת המעין שנובע גיד דק מהארץ שהוא בבחי' צמצום עצום שאינו מתפשט לכאן ולכאן כמו הנהר שמתפשט על כל גדותיו, ועכ\"ז כל אורך ורוחב התפשטות הנהר הוא מהמעיין דוקא וכ\"ה בתושב\"כ שכל מצותיה של תורה נאמרו בקיצור נמרץ כמו המעיין דק, ובתושבע\"פ נעשה אורך ורוחב מכל מצוה שבתורה כמו מס' שבת מפסוקי' שנא' בהם ציוי השבת שהם מעטי' ועכ\"ז נעשה מזה מס' שלימה ועד\"ז כל המצות כו' וזהו ולילה ללילה יחוה דעת ל' גילוי שמגלה העלם המעיין דתושב\"כ להיות גילוי נהר באורך ורוחב, ועכ\"ז הוא הכל מתושב\"כ כמארז\"ל מנלן אמר קרא, והיינו כי אדם וחוה הם בחי' ש' הוי' והמילוי דש' הוי', כי אדם בגימ' מה שהוא ש' הוי' במילוי אלפין וחוה הוא גימ' י\"ט שהוא בחי' מילוי דש' הוי' שעולה מספרו י\"ט*.\n<b>והנה</b> כמו שחוה נבנית מצלע דאדה\"ר כמ\"ש ויבן את הצלע, שבנה מצלע דאדה\"ר בנין חוה כן תושבע\"פ ג\"כ נבנית מתושב\"כ כמו כל פ' השואל שבס' ב\"מ נבנה על ואו דוכי ישאל, וא\"ו מוסיף על ענין ראשון, והענין הוא כנ\"ל שכל ענין תושבע\"פ הוא לפרש ולבאר כל הדברי' הנאמרי' בתושב\"כ בקיצור נמרץ, ולכן נק' הת\"ח בונים להיות כי הם בונים תושבע\"פ מתושב\"כ, וז\"ש והאתנים מוסדי ארץ אתנים אותיות תנאים והם הם המיסדי' תושבע\"פ"],[2000500201,"שנק' ארץ, ועש\"ז נק' תושבע\"פ בשם כלה שמקבלת מחתן הוא בחי' תושב\"כ, וזהו אמרם ז\"ל א\"ת מורשה אלא מאורסה שתושבע\"פ היא מאורסה לתושב\"כ שנק' חתן היינו בחי' השפעה שנשפע מהקב\"ה שנק' בשם חתן כו'.\n<b>והנה</b> בבחי' המשכה והשפעה שנשפע מתושב\"כ לתושבע\"פ יש בזה ב' בחי' אירוסין ונשואין דהנה ענין האירוסין הוא מה שהחתן נותן להכלה טבעת קדושין, ועי\"ז אוסרה לכל העולם ושתהי' מופרשת ומובדלת לו, והיינו שהוא ממשיך לה חיות מועט משלו ע\"י הקדושין שקידשה, אבל ע\"י נשואין ה\"ה משובעדת לגמרי לבעלה שלכן פטורה ממ\"ע שהזמן גרמה מפני שבעלה מוציאה ידי חובתה, שהרי בזמן היא משובעדת לבעלה כמ\"ש מזה בסידור, אבל אירוסין אין מע\"י לבעלה שהרי אינו חייב במזונותיה, ורק מפני כי נשמתה מעלמא דנוק' והמל' משועבדת לז\"א בעלה ולכן גם בעודה נערה פטורה ממ\"ע שהזמן גרמה אבל אין לה מי שיפטור אותה עד הנשואין ועכ\"ז קצת חיות נותן לה משלו ע\"י שאוסרה לכל העולם ומזמן אותה לו ע\"י קדושין שקידשה כו', ועד\"ז יובן בתושב\"כ ותושבע\"פ שנק' חתן וכלה דהנה כל מה שנת\"ל שהתושבע\"פ הוא פי' וביאור דתושב\"כ זהו רק מבחי' אותיות התורה לבד וכמו שמצינו בגמ' מ\"ט אמר קרא, וכן דברי' הדברי' אלה הדברי' למדו מזה ל\"ט מלאכות דשבת שזהו רק מאותיות לבד או פ' השואל מוא\"ו דוכי ישאל שזהו רק אותיות, ועל כל דבר ודבר שבתושב\"כ יש ס' ריבוי פרושי' בפשט וכן בדרוש וכן ברמז וכן בסוד, וכ\"ז הוא באותיות התורה,"],[2000500202,"אמנם הנה נודע שיש טעמי' נקודות תגין ואותיות ומה שנתגלה הוא רק אותיות התורה לבד ונקודות ותגין מעט מן המעט אשר נתגלו כמארז\"ל על ר\"ע שהי' דורש על כל קוץ תלי תילי' של הלכות, אמנם מעט מהם אשר נתגלו, אבל טעמי שבתורה לא נתגלו כלל עדיין, והיינו נובלות חכמה שלמעלה תורה שכל גילוי התורה שנתגלה הוא רק נובלות לבד, ולכן יש ך\"ד ספרי' שזהו בחי' כד לבד מים החכמה עד\"מ השואב בכד מן הים או המעיין שאין ערוך כלל הנשאב בכד לגבי עצם הים או המעיין כך התורה היא רק נובלות חכ' שלמעלה, ואמנם ענין הנשואין הוא שיומשך המשכה עצמיות מעצם החכ' ולא הארת החכ' שהוא בחי' אותיות בחי' דבור שנמשך בתושבע\"פ שנק' מל' פה תושבע\"פ קרינן לה, אמנם ענין הנשואין הוא שיומשך המשכה עצמיות מבחי' החכ' וח\"ס, כמו שע\"י יחוד חתן וכלה נעשה הולדה שהיא הולדה בדומה לו ממש עם בחי' מוחין כמותו וגם להיות יכול להוליד בדומה לו כו', וז\"ע מה שאומרי' בש\"ע מוריד הגשם שהוא בחי' השפעת הטפה שנמשך המשכה עצמיות מהחתן הוא תושב\"כ לכלה היא תושבע\"פ, וכינו זה בשם גשם כי לע\"ל והי' אור הלבנה כאור החמה ואור החמה יהי' שבעתים כאור זה\"י ופי' רש\"י בפסחי' שאור שבעת הימי' הם זפ\"ז הם מ\"ט וז\"פ מ\"ט הם שמ\"ג שז\"ע גשם, והענין הוא דאיתא במדרש רבה פ' בראשית ס\"פ ך\"ו כל אורה האמור באלי' בירידת גשמי' הכתוב מדבר והיינו כי השפעת האורה שלמעלה שנמשכת למטה נק' בשם גשם ע\"ש שמתגשמת בירידתה למטה, ונת\"ל שבשמע\"צ הוא בחי' היחוד שנמשך מעצמיות ח\"ס לכן תקנו אז לומר מוריד הגשם ע\"ש השפעת אור כשנשפע למטה נק' בשם גשם, ופשוטו שמתחילין לבקש השפעת הגשם הוא כמארז\"ל בזמן שאין ישראל עושי' רצוש\"מ הארץ שותת ממי אוקינוס, ובזמן שעושין רצוש\"מ שותים ממים עליוני' היינו ממים שמעל השמי', ופי' עושי' רצוש\"מ הוא בחי' קיום המצות שנק' רצוש\"מ בחי' מקיפי' ה\"ז כמו אירוסין טבעת קדושין, ועי\"ז הוא אח\"כ"],[2000500203,"נשואין בחי' השפעה פנימית מבחי' ח\"ס עצמה ועי\"ז גם הארץ שלמטה שותה ממים עליוני' ועי\"ז נמשך שפע ברכה כמו שמצינו בדרז\"ל שנעשו חטים ככליות שהוא בחי' ריבוי ברכה, וגם י\"ל הארץ שהיא בחי' מל' פה תושבע\"פ מקבלת מבחי' מים עליוני' הוא מי החכמה עילאה היא בחי' ח\"ס והיינו שלא יהי' הגילוי מבחי' אותיות לבד כ\"א הארה מבחי' טעמי תורה כו'. —————— ּ ——————"],[2000500204,"<h3>והענין כו' אור מים רקיע כו'</h3>\n<b>בס\"ד, ש\"ת</b>\n<b></b>המחליף פרה בחמור כו' אמ\"ר בא\"א בע\"י (ב)\nשמח\"ת\n<b>והענין</b> הוא דהנה יש ג' בחי' אור מים רקיע, פי' רקיע הוא כמו שאגלידו מיא ונעשה מהם בחי' רקיע וז\"ע מתיבתא דרקיע שהוא מה שלומדי' שם רוחניות ההלכות הערוכות לפנינו בדיני ההלכות שנמשכו מבחי' האותיות התורה, שהרי שם לא שייך גשם ההלכה כמו המחליף פרה בחמור או שנים אוחזי' בטלית שהרי לא יש שם פרה וחמור וטלית הגשמי אלא שלומדי' שם רוחניות דבר ההלכה ועינינה מה היא ברוחניות והענין הוא דהנה ממ\"ש במ\"א באריכות בענין מ\"ש ויקרא האדם שמות שארז\"ל חכמתו גדולה משלכם, ואם זהו רק הסכם לבד אין שייך לומר חכ' גדולה מהו החכ' בזה אלא עכצ\"ל שכל שם של כל בהמה וחי' בפרט שייך דוקא לנברא זו וכמ\"ש בבחיי שמקריאות האדם שמות מובן כי ידע סוד המרכבה העליונה,"],[2000500205,"והיינו לזה נאה לקרות שור להיות כי אותיות שור מחיים אותו וכן לזה חמור וכן לכולם עד אני מה שמי הוי' שאתה אדון, והיינו כי ש' הוי' נכתב בש' הוי' ונק' בש' אד', או כי כל ההתהוות הוא מש' הוי' כמ\"ש יהללו את ש' הוי' כי הוא ציוה ונבראו, וכמ\"ש אני ה' עושה כל, וא\"כ פרה אותיות פרה מחיים אותה וכמ\"ש במ\"א ענין פרה פר ה' והיא בהמה טהורה שיכולה ליכלל בקדושה ואמנם חמור הוא בהמה טמאה וא\"א לבררה, רק מ\"מ כתי' ביששכר חמור גרם היינו שויט שכמו לסבול עול תורה שמייגעת ונוטלת כח האדם כנודע מר\"ל, לכן ע\"י בירר גם בחי' חמור ע\"י היותו כחמור למשא, ולכן הלימוד שבג\"ע כשמחליף פרה בחמור אם בירור החמור היא כמו הפרה שהיא ק\"ן או באו\"א להיות כי הוא מג\"ק לכן צ\"ל יתרון אור ע\"י החשך דחמור, וענין החליפין שמחליף נפשו הבהמית שנק' פרה שיסבול כמו חמור כו' ואיך הוא החליפין בכל דרכי החליפין וזהו ענין הלימוד בג\"ע התחתון ועד\"ז יובן בג\"ע עוד בדקות יותר ע\"ד דקות המחשבה ושייכותה והתאחדותה להאדם יותר מדבור ומעשה ולכן ממח' היא כוונה נעשי' לבושי' לג\"ע העליון, ועד\"ז יובן במתיבתא דרקיע ומתיבתא דמט\"ט שהם נגד ב' בחי' ג\"ע, ועד\"ז הוא לימוד הלכה דשנים אוחזין וכן עד\"ז כל ההלכות שבתורה, ומבחי' רקיע זה נעשה רקיע ע\"ג חוין עילאין כמ\"ש ועל ראשי החיות רקיע כעין הקרח הנורא, והגם שנת\"ל בד\"ה ושאבתם מי' שרקיע הוא מה שאגלידו מי' שהוא למעלה"],[2000500206,"מן המים כו', באמת כן הוא לגבי חכ' שבחיות דחיוין עילאין הנה רקיע זה הוא למעלה מן המי' שלהם הוא בחי' חכ' שלהם, ומ\"מ לגבי בחי' עצם החכ' דאצי' הנה רקיע זה הוא למטה שהרי זהו מה שמהמים נעשה כפור וקרח, וכנודע שיש ב' בחי' מים הא' קודם שנגלדו הב' לאחר שנגלדו ונמס והי' למים כו', ורקיע זה הוא כעין הקרח הנורא והיינו שכמו שהוא באצי' שמבחי' מים דחכ' דאצי' נעשה קרח ורקיע דבינה כמ\"ש מבטן מי יצא הקרח פי' מי הוא בינה כנודע, כ\"ה בח\"ס שבחי' חכ' שבכתר הוא בח' חכ' דא\"א בחי' מו\"ס הוא מים ובחי' בינה דא\"א הוא בחי' קרח הוא בחי' קרח הנורא, ורקיע דבינה הוא כעין בחי' הקרח הנורא דא\"א, ואמנם באמת גם למעלה מן המים דחכ' דא\"א יש כדוגמת רקיע והוא כעין שמצינו בגמ' אשתומם כשעה חדא פי' שלהיות שזהו למעלה מערך חכמתו לכן אשתומם והעלה מוחו ושכלו למקום הגבוה יותר לקבל משורש מקור חכמתו כו' ונמצא כי יש ב' בחי' רקיע הא' כמו שהוא בא בהשגה דבינה שאגלידו מיא להיות בחי' כפור וקרח הב' מה שהמשפיע הוא בחי' חכ' נעשה מקבל לקבל מבחי' משכיל, כי ענין הרקיע יש בו מפעולת מקבל כמובן ממשי\"ת לקמן בענין הטפה כשבא בבטן הנוק' נעשה ציור רמ\"ח איברי' וא\"כ נגע בה גם סיוע הנוק' בחי' מקבל דאל\"כ לא נעשה מהטפה ציור רמ\"ח איברי' שהרי נק' השחית כל בשר דרכו על הארץ, אמנם בענין אשתומם הוא שעצר כח חכ' מלהוריד ההשכלה כ\"א תהי' בבחי' שתיקא ע\"ד אגלידו לקבל מבחי' ח\"ס בחי' משכיל, ועד\"ז יובן בח\"ס עצמה בבחי' חכ' דח\"ס דא\"א איך שמקבל מבחי' משכיל נק' רקיע כו' ונמצא יובן בחכ' דא\"א שכמו שהחכ' מקבלת מבחי' משכיל מקור החכ' דח\"ס זהו עיקר בחי' הרקיע והקרח שנת' בד\"ה ושאבתם הנ\"ל, וכ\"ז הוא בחי' רקיע בכלל, ובחי' מים זהו בחי' חכ' בכ\"מ שנתבאר בחי' רקיע הנ\"ל בכל בחי' לפי ערכה, ובחי' אור הוא למעלה מבחי' מים ג\"כ עדיין עד שבחי' מים נחשב לתבנית איזה גשם כמו בריקת וסקירת השכל שהוא הרגש במוחו פרט הסברא, ולכן אמר ר\"ע לכשתגיעו לאבני שיש טהור א\"ת מים כפשוטו אלא זהו בחי' אור כו'."],[2000500207,"<b>וביאור</b> ענין אור מים רקיע יובן עד\"מ הטפה אשר מתהוה במוח האדם קודם ירידתה בשדרה היינו קודם שמתגשמת להיות טפה זרעית בחוהש\"ד היא רק כח רוחני עדיין, ואח\"כ בבוא הכח הרוחני בחוט השדרה מתהוה ממנה טפה זרעית שמתגלמת ומתגשמת בערך היותה קודם טפה רוחנית, ואח\"כ בצאתה מגוף האדם להוליד בדומה לו שהוא ע\"י התפשטות הטפה במעי הנוק' היא עוד ירידה והגשמה עד שמצטייר ממנה ציור הולד ברמ\"ח איברים שלא הי' ציורם ניכר בהטפה כלל ע\"ד כמו שבגרעין זרע פרי העץ או האדמה אינו ניכר תמונת פרי כלל, ונמצא יש כאן ג' מדריגות הא' כח הטפה ברוחניות קודם שמתגשמת להיות טפה גשמית במוח שבחוה\"ש, ואח\"כ כמו שמתגלמת להיות בחי' טפה גשמיות שיש בה בכח לבד על כל ציור הרמ\"ח איברי' ושס\"ה גידים אבל לא בפועל, וע\"י שיצאת למעי הנוק' בהרגש דוקא עי\"ז מצטיירי' להיות רמ\"ח איברי' בפו\"מ בהבדל בין אבר לחבירו כו', וזהו משל להבין בחי' אור מים רקיע למעלה בבחי' טיפת אור אבא דהיינו בחי' אור הוא שורש ומקור בלבד למציאת התהות אור חכ' דאצי' הנק' מים, ובחי' החכ' דאצי' עצמה נק' מים והוא כדמיון גשמיות הטפה והתפשטות החכ' להיות מאין ליש בבינה הוא הנק' רקיע כמו שהמים עליונים שמעל לרקיע אינם עדיין עומדים ממש בבחי' התפשטות נגלית כ\"כ ממש כמו הרקיע שנגלה להתפשטות יש ממשי כו' והוא כדמיון הולד שנמשך מהתפשטות הטפה.\n<b>ולהבין</b> בתוס' ביאור ג' מדריגות אלו דאור מים רקיע הנה יובן בשכל האדם עצמו ע\"ד שאנו רואי' בכח הטפה שיש בה ג' מדריגות כנ\"ל, הנה גופו ומהותו של מציאות השכל הוא נמשך מלמעלה מן השכל כידוע והוא הנק' משכיל וכנראה בחוש בהולד לאדם במוחו איזהו שכל וסברא שזהו בא לו בבחי' שפע מלמעלה והיינו מבחי' הכתר שהוא נק' אין ומושלל הוא לגמרי ממציאות ומהות שכל הנראה במוח כידוע, אלא רק שממנו נמצא מציאות השכל ואופן ההמשכה מאתו הוא כדמיון הטל שממנו מתהוה גשם המים אח\"כ, כך בחי' המשכיל* הוא דק מאד נבדל בערך לגמרי מן גשם השכל אלא שממנו נמצא הגשמת מהות השכל כמי' שמתגלמי' מן הטל והוא בחי' יסוד"],[2000500208,"לחלוחיות הרוחניות שבמוח שמוליד שכל וסברא כמ\"ש במ\"א, והנה לאחר שנמצא מציאת הגשמת השכל הגם שהוא גשם בערך דקות בחי' כח המשכיל הרוחני הנה מ\"מ עדיין גם הוא נק' בחי' כח הרוחני לגבי בחי' הבנת משכיל והשגתו בבינה שהרי שם הסברא באה בבחי' יש ודבר מושג ממש אבל כמו שהסברא בכח ההשכלה עדיין הנק' חכמה הרי הוא בחי' כח היולי עדיין וכידוע, והרי יכולים להסביר אותה בכמה מיני אופנים שונים, וזהו עיקר ההפרש אשר בין חכמה לבינה דבחכמה שנק' כח היולי יכולים להטותה עדיין בכל מה שירצו משא\"כ כשבא השכל לידי השגה ממש א\"א להם להטותה לאופן אחר מכמו שכבר הושג כו' ויובן כדוגמא זאת ממש בטפת המוח הגשמיות שכאשר עדיין לא נתפשטה במעי הנוק' יכול להצטייר הולד באופן אחר, וכמו שקודם ארבעי' יום מועיל תפילה לשנות מזכר לנקיבה, משא\"כ כאשר כבר נתפשטה בציור צורת הולד א\"א שישונה באופן אחר מכמו שהוא אחר שכבר נתפשטה בכל חלקיו כו' וכך יובן ג' מדריגות אלו בג' מדריגות אור מי' רקיע בגשמיות, דבחי' האור הוא כח התהוות הגשמת המים, ועדיין מושלל הוא מבחי' הגשמות ממשת המים ממש, אבל גם המים נק' כח רוחני לגבי התהוות הרקיע שהרקיע הוא עומד במעמד ומצב להיות קרוש וגלוד מן המים כמו מי היאור כשנקרשי' ונגלדים בחורף, משא\"כ המים הם מתנענעי' לכאן ולכאן ויכולים להמשיכם לאיזה צד שירצו, אבל הרקיע עומד מבלי הטיה כלל והיינו להיותו כמו הקרח והכפור שהמי' בהם גלודי' וקרושי' מבלי הטיה כלל והוא מורה למעלה בחי' הגשמת המים ביותר כדמיון הולד שנתהוה מן הטפה כו' וכמו מציאות ההשגה שנמשך ומתגלם מן כח ההיולי שבשכל, וע\"כ המים אין בהם גון מצד עצמם רק לפי מראה הכלי אבל הרקיע יש בו מראות וגוונין כידוע, ואחר שנתב' ענין הב' מדריגות דאור מי' רקיע יובן עינינם ברוחניות האצי' דבחי' אור הוא ח\"ס דא\"א בכלל שממנו נמצא מציאות חכ' דאצי' שנק' מים, ואמנם גם בחי' המים דחכ' עדיין הם נחשבי' לבחי' אין ואין להם גון כו' לגבי ההשגה דבינה שנק' רקיע, והוא בחי' רקיע דאגלידו מיא שלמטה מן המים כנ\"ל, וכן יובן בפרטיות בא\"א עצמו שבחי' כתר דא\"א הוא בחי' אין העצמי שמהוה בחי' מים הוא בחי' חכ' דח\"ס דא\"א שנק' מים בערך האור דכתר, ועדיין הוא בחי' אין לגבי רקיע דבינה דח\"ס דא\"א כו', שהוא בחי' השגה שבמשכיל מקור השכל דאצי' כו' וכן יובן ענין אור מים רקיע גם בבחי' ע\"י שז\"ע מה ששלש שעות ראשונות הקב\"ה יושב ועוסק בתורה זהו ג' בחי' אור מי' רקיע,"],[2000500209,"או י\"ל שזהו ג' ראשי ראשים אור צח אור מצוחצח אור קדמון רק ששם כולם נק' אור אפי' בחי' רקיע, וכ\"ז הוא בכלל רצון שהוא בחי' מה שעלה ברצונו כו', אך לפ\"ז יובן עד\"מ למטה אינו שייך שירצה האדם איזה דבר מה שלא יש בעולם וא\"כ יובן מאחר שעלה ברצונו עד\"ז דוקא מוכרח להיות שישנו תחלה והיינו כמ\"ש בדרושי אאזמו\"ר זצלל\"ה זיע\"א שיער עצמו בכח מה שעשה בפועל שענין מה שעלה ברצונו זהו שעשה בפועל כי מיד שעלה ברצונו עי\"ז נתאוה ואיך עלה זה דוקא ברצונו ע\"י שישנו תחילה בעצמותו ששיער עצמו בכח א\"כ גם שם יש ג' בחי' אלו דאור מים רקיע כו'.\n<b>ולפ\"ז</b> יובן ענין בחי' הנשואין שבתורה שיומשך מפנימיות ח\"ס הוא בחי' אור הכתר דח\"ס דא\"א, רק שעיקר ענין הנשואין יהי' לע\"ל ועכשיו בשמע\"צ הוא רק הארה מבחי' זו שזהו שמתחילין לומר מוריד הגשם בשמע\"צ שהוא בחי' אור שנתגשם כנ\"ל בפי' המד\"ר כל אור האמור באלי' בירידת הגשמי', וזהו בחי' מים מג' בחי' אור מי' רקיע, או י\"ל שזהו ג\"כ מבחי' אור אלא שבחי' אור שבא בירידה למטה מוכרח להתגשם מעט ולכן נק' מים וגשם, ובשרשו הוא ז' פעמי' אור שבעת הימי' אלא שלע\"ל יאיר כלליות האור ולא יצטרך לבוא בהגשמה מפני כי לע\"ל יזדכך העולם, ועכשיו בא בהגשמה מעט ורק בחי' הארה בעלמא מבחי' אור הכתר דח\"ס דא\"א, ואעפ\"כ גם כפי שמתגשם מעט עד שנק' בשם מים וגשם דק הוא בערך הרקיע הוא בחי' השגה בכלל כו'. —————— ּ ——————"],[2000500210,"<h3>ולהבין ענין אירוסין ונשואין בתורה כו'</h3>\n<b>בס\"ד פ' בראשית</b>\n<b>ולהבין</b> ענין אירוסין ונשואין בתורה הנגלית שלפנינו, יובן במה שביקש דוד גל עיני ואביטה נפלאות מתורתיך, שלכאו' צ\"ל מה\"ע שביקש שיגול ה' עיניו ויביט נפלאות מתורתיך דאם הכוונה שיבין פי' הפשוט בטוב"],[2000500211,"טעם ודעת יותר אין זה בכלל נפלאות כלל, שפי' הפשוט הכוונה שיבין כאו\"א לאשורו, כמו כל מי שאומר סברא רצונו שזולתו יבין בטוב מה שהוא אומר, וא\"כ כל תושבע\"פ הכוונה שיבין זולתו א\"כ אין זה בכלל נפלאות כלל והרי כל ענין תושבע\"פ היא לפרש ולבאר מצותיה שנאמר בתושב\"כ בקצרה א\"כ בהכרח שכאו\"א ידע איך ומה לעשות המצוה כו', אלא הענין ע\"ד דכתי' כימי צאתך מאמ\"צ אראנו נפלאות, דהנה התורה נק' אדם כמ\"ש זאת התורה אדם, והנה כמו באדם יש גוף ונפש כן בתורה יש בחי' גופא דאורייתא ויש בחי' נפש, והנפש יש לה ה' שמות נרנח\"י, כן ג' בחי' אור מים רקיע כוללי' ה' בחי' נרנח\"י, רקיע הוא בחי' נר\"ן מים חיה אור הוא בחי' יחידה, ויש לבושי דאורייתא וכמו שפי' רש\"י בפ' בראשית אר\"י לא הי' צריך להתחיל את התורה אלא מהחדש הזה לכם שהיא מצוה ראשונה שנאמרה לכלליות ישראל, אלא משום כח מעשיו כו' והיינו בחי' לבושי תורה שנתלבש בעת מעשה בסיפור ההוא כמו כל ענין תהו ותיקון שהוא סיפור זמ\"ק דתהו וכשמתו היו כלא היו ומלך השמיני הדר הוא בחי' התיקון שמתקן שבה\"כ דתהו וכמוהו רבות בסיפור המתנה דיעקב שהוא העלאת מ\"ן לעולם התהו שיעקב ידע ענינם כמ\"ש בת\"א בפ' וישלח, ויש בחי' גופי תורה כמ\"ש במשנה ספ\"ק דחגיגה הן הן גופי תורה, ויש בחי' נשמתא דאורייתא, שהוא בחי' סתים רזין דאורייתא ויש נשמתא לנשמתא (שבזהר כולל ה' שמות דנשמה בד') והוא בחי' סתימא דכל סתימין או רזי דרזין, וע\"ז שביקש דהע\"ה גל עיני ואביטה נפלאות שיביט בחי' נפלאות שבתורה הוא בחי' סתי' וסדכ\"ס וג\"ז הוא מתורתך הוא בחי' תורה הנגלות וז\"ע ארון אור נו\"ן שבחי' נפלאות הוא בחי' נון פלאות אפשר להתגלות ע\"י הארון הוא נו\"ן אור כו', וענין אומרו גל עיני הוא כמארז\"ל במד\"ר פ' וירא הכל בחזקת סומין עד שהקב\"ה"],[2000500212,"מאיר את עיניהם, והראי' מהגר דכתי' ויפקח אלקי' את עיני' משמע שהבאר הי' קודם לכן רק שלא ראתה וע\"י שנפקחו עיני' ותרא באר מים כו' ועד\"ז ביקש דוד גל עיני.\n<b>ובכ\"ז</b> יובן שורש ענין ההפרש בין אירוסין לנשואין שבתורה דהנה כל מה שנדרש בתושבע\"פ הוא רק מבחי' אותיות התורה לבד כנ\"ל בענין דברי' הדברי' אלה הדברי' או ואו דוכי ישאל וכמוהם, אבל ענין הנשואין שיומשך המשכה עצמיות מפנימיות אור אבא ולמעלה יותר להוליד בדומה לו זהו בחי' נשואין, וזהו שכל התורה הוא רק כד מים כנודע מענין וכדה על שכמה שזהו ך\"ד ספרין דאורייתא שנתנו לדרוש בחי' גופי תורה, אבל הנשואין הוא ע\"ד והאדם ידע שיומשך דעת מפנימיות התורה בבחי' ידיעה גמורה על אמיתתן מה שעכשיו הוא רק הידוע מציאותו יהי' מושג בבחי' ידיעה והכרה שהמקבל יהי' כלי לזה, כי יש הפרש גדול בין ידוע ליודע, וכנודע ממ\"ש במ\"א בענין גלוי וידוע שלכן הידיעה אינה מכרחת הבחירה, אבל יודע הוא בבחי' התלבשות כו', וכנ\"ל בענין אור מי' רקיע שמבחי' האור נמשך הרקיע בבינה ועוד יותר שהרי בענין ג' בחי' דאור מי' רקיע משתנה להיות בחי' רקיע ולא אור, אבל בכאן הכוונה שיומשך הדעת ע\"ד מ\"ש ומלאה הארץ דיעה כמים לים, והענין דהנה שמים וארץ הם תושב\"כ ותושבע\"פ שמים הוא בחי' שם מים בחי' תושב\"כ וארץ הוא בחי' תושבע\"פ וע\"י המשכת הדעת יומשך גם בארץ שימלא הארץ דעת כמים היינו כמו בשמים שם מים כו' וז\"ע כשתגיעו לאבני שיש טהור א\"ת מים מים פי' להפריד בין מ\"ע שמעל לשמי' ובין המי' שמתחת השמי' כי באמת יכול להיות שגם בארץ יהי' מלא דיעה כמים כו' וצ\"ל יחוד והתחברות שמו\"א להיות מלאה הארץ דיעה כו'.\n<b>והנה</b> כדי לייסד הארץ שתהי' בה הדעת כמים לים מכסי' זהו ע\"י והאתנים כנ\"ל בענין והאיתנים מוסדי ארץ, ולהבין בחי' זו בעבודה בנפש"],[2000500213,"האדם, הנה איתן כמשמעו קשה והוא בחי' הביטול שלמעלה מן השכל ועז\"נ כי עם קשה עורף הוא וסלחת דלשבח קאמר שלכן וסלחת כו' והענין הוא דכתיב כי חלק ה' עמו, וכתי' פב\"פ דבר ה' עמכם ודבורו של הקב\"ה חשיב מעשה שעי\"ז נעשה הוי' עמכם בכאו\"א מישראל, ונודע כי יו\"ד דש' הוי' וקוש\"י הם בחי' שלמעלה מן השכל ולכן כאו\"א מישראל יכול לבא לבחי' זו ע\"י שיתבונן תחלה בבחי' התבוננות שע\"פ השכל היינו שהוי' אלקינו הוא הוי' אחד פי' הגם כי נתהוו ז' רקיעי' וארץ וד' רוחות עכ\"ז כולם בטילי' לאלף הוא בחי' אלופו ש\"ע בתכלית הביטול כמ\"ש ביאור ד\"ז במ\"א בכ\"ד, ואח\"כ יוכל לבוא לבחי' הביטול שלמעלה מן השכל לגמרי שזהו בחי' איתן ועי\"ז מוסדי ארץ שיומשך הדעת גם בארץ כמים לים כו', והנה חדש תשרי נק' ירח האיתנים כמ\"ש ויקהלו כו' בירח האתנים בחג הוא החדש השביעי, לפי שבו יוהכ\"פ זמן התשובה דבכל מאדך שלמעלה מהגבלת הכלי שזהו בחי' איתן כנ\"ל ואח\"כ בחגה\"ס מאיר בחי' זו בבחי' מקיף דכתי' משכיל לאיתן האזרחי שלע\"ל יזרח בחי' איתן בנש\"י ועכשיו כל האזרח בישראל ישבו בסוכות פי' שכל זה שעתיד לזרוח בישראל עכשיו יש בו בסוכות שעכשיו מאיר בחי' זו במקיפי' דסכך הסוכה כו' וע\"י ד' מינים שבלולב מאיר המקיף בפנימי להיות כי ע\"י נמשך המשכת הדעת בנש\"י עד שבשמע\"צ נעשה הקליטה שיוקלט בנש\"י הדעת באלקות ולא יהי' פולטי', רק כי לע\"ל נא' כי"],[2000500214,"בועליך עושייך, להיות כי אז תקראי אשי, והיינו כי לע\"ל יהי' כל עיקר העסק בתורה לבד כי להשפעות גשמיות לא יצטרכו כלל כי הרי ארז\"ל עתידה ארץ להוציא גלוסקאות וכלי מילת כו' ולכן כל עסקי' לא יהי' כ\"א בעסק התורה לבד, ועכשיו מוכרח לעסוק בדברי' הכרחי' עכ\"פ והיינו כי לע\"ל יהי' גילוי בחי' נשמתא לנשמתא, ועכשיו הוא רק היחוד בבחי' נשמתא לנשמתא כו'.\n<b>והנה</b> ש\"ת עושי' אחר שמע\"צ, והגם כי מ\"ת הי' בחגה\"ש אמנם זהו רק בחי' אירוסין לבד, ובלוחות שניות שניתנו ביוהכ\"פ הגם כי למצותי' ש\"ת לא ניתן לדרוש רק בחי' אותיות התורה שזהו רק אירוסין כנ\"ל, מ\"מ יש בה גם בחי' נשואין וכנ\"ל ושמע\"צ הוא הקליטה מטיפת אור אבא בבחי' פנימיות לכן עושין אז ש\"ת כמו השמחה שבעת נשואין, ולכן ביום חתונתו זו מ\"ת אמרו במשנה סוף תענית* על לוחות אחרונות שניתנו ביוהכ\"פ דוקא והיינו מטעם הנ\"ל וד\"ל.\n—————— ּ ——————"],[2000500215,"<h3>ובכ\"ז יובן מה שנק' הארון כו'</h3>\n<b>בס\"ד פ' נח</b>\n<b>ובכ\"ז</b> יובן מה שנק' הארון בשם ארון הברית, שנת' לעיל שברית הוא הכוונה על לוחות הברית שמונחי' בארון שהם תושב\"כ שהיו כתובי' באצבע אלקי', והארון עצמו הוא בחי' תושבע\"פ וכנ\"ל בענין אור נון שיתגלה ע\"י כל בחי' נון אור כנ\"ל, וגם ענין ברית הוא לשון התקשרות ג\"כ"],[2000500216,"מענין ברית בין הבתרי' שהוא ענין ההתקשרות למעלה מן הטו\"ד, כן יובן בענין יחוד תושב\"כ ותושבע\"פ שנת\"ל בענין איתן שהוא למעלה מן הטו\"ד וע\"ז מורה לשון ברית בחי' התקשרות שלמעלה מן השכל, ואמנם העוברי' בברית מוכרי' שניהם לעבור בברית לכן גם בנש\"י צ\"ל בחי' איתן בחי' תשובה דבכל מאדך דיוהכ\"פ בחי' קשה עורף ועי\"ז וסלחת כו', ועי\"ז נמשך מלמעלה ג\"כ מבחי' שלמעלה מן החכ' ושכל המושג מאותיות התורה, והיינו שיומשך מבחי' טנ\"ת שלמעלה מאותיות התורה, והנה ההמשכה הוא ע\"י ברית העליון והגם כי הוא למטה מן החכ' מ\"מ הרי אנו רואי' שנמשך ע\"י להוליד בדומה עם חכ' כמותו וביתר שאת וכנודע ממ\"ש במ\"א מענין יפה כח הבן מכח האב, ולכן מוכרח לומר כי גם השפע העצמי שלמעלה מן החכ' יורד ברית העליון כו' וגם כי שרשו גבוה מן החכ' וכנודע מענין תמן מל תמן נצח ששרשו מבחי' יסוד דא\"ק ושורש ענין היחוד נמשך מהכתר כמ\"ש במ\"א, וא\"כ מה שהארון נק' ארון הברית מורה גם על בחי' התקשרות בחי' תושב\"כ ותושבע\"פ ע\"י בחי' ברית העליון כו', ועפ\"ז יובן מה שכשהי' צריך שלמה להכניס את הארון לבית קדה\"ק דבקו שערי' זב\"ז, כי הנה נת\"ל שלהיות היחוד תושב\"כ עם בחי' תושבע\"פ זהו ע\"י ברית העליון ומקום היחוד הוא בבית קדה\"ק, והגם שגם בעת עברו בירדן נק' ארון הברית אמנם כ\"ז הוא ע\"ש היחוד כנ\"ל שמקום היחוד הוא בקה\"ק, ולכן דבקו שערי' ע\"י הפגם שפגם שלמה בברית העליון כמשי\"ת, וענין מה שדבקו שערי' דוקא ולא מניעה אחרת לפי דכתי' נודע בשערי' בעלה שבחי' המשכת הדעת ע\"י ברית העליון הגם כי הוא בבית קדה\"ק צ\"ל עובר ע\"י השערי' שלכן נודע בשערי' דוקא כי כן הוא דרך העברת טיפת אור אבא ע\"י בחי' השערי' ובחי' ברית העליון, ובשערי' כתי' שאו שערי' ראשיכם שבחי' השערי' יש להם ראשים ושלמה פגם בזה והיינו שבנה על חכמתו דכתי' ויחכם מכל האדם ולכן הרבה לו נשי' וטעה"],[2000500217,"בזה נשיו הטו את לבבו* וכן פגם בברית העליון ע\"י שנשא בת פרעה שארז\"ל בשעה שנשא כו' בא גבריאל ונעץ קנה בים והעלה שרטון ונבנה עליו כרך גדול של רומי והיינו כי לאום מלאום יאמץ, והגם דכתי' ויביאה עיר דוד כו' מ\"מ לגבי שלמה הי' נחשב זה לחטא ועון, ולכן כשהי' צריך להכניס הארון דרך השערי' לקה\"ק להיות היחוד עליון ע\"י ברית העלין דבקו שערי' זב\"ז מחמת פגמים הנ\"ל.\n<b>ולהבין</b> בתוס' ביאור מה שע\"י חטאי' הנ\"ל דבקו שערי' יובן ממה שארז\"ל על יוסף הים ראה וינס מה ראה ארונו של יוסף דכתי' בי' וינס ויצא החוצה ששמר שמירת הברית, ולכן כל מם שנה שהיו ישראל במדבר היו הולכים ב' ארונות ארון הברית וארונו של יוסף זה אצל זה ואם ישאל אדם כו' התשובה קיים זה מ\"ש בזה*, כי יוסף במצרי' מסר נפשו על שמירת הברית שלא רצה לפגום בברית העליון כמ\"ש ולא שמע אלי' לשכב אצלה להיות עמה וסבל יסורי' קשים ומרים שהי' בבית האסורי' י\"ב שנה* חנם על לא דבר, ועי\"ז זכה להיות מרכבה לבחי' ברית העליון וזהו קיים זה מ\"ש בזה עד שהי' בחי' צ\"ע*, ולכן הלכו בשוה ארונו עם ארון הברית כו' ולכן הים ראה ארונו של יוסף וינס, דהנה נת' לעיל שהארון הברית נק' אדון כל הארץ פי' אדון ל' זכר, אדנ\"י הוא לשון נקבה דכתי' והוי' בהיכל קדשו היכל בגימ' אד' והיינו מפני כי שם אד' מסתיר על ש' הוי'"],[2000500218,"כמו ההיכל שמסתיר ומכסה על האדם היושב בו כו', ואמנם אדון ל' זכר הוא כאשר ש' אד' אינו מסתיר על ש' הוי' ועיקר הגילוי הוא מש' הוי' המשפיע ולכן הוא ל' זכר, גם אדון הוא ל' מושל ושולט ועושה כל אשר חפץ, וע\"ד דכתי' כל אשר חפץ הוי' עשה בשוב\"א כו' וכמארז\"ל במד\"ר אדון כל הארץ מה אדון עוקר דיורים ומושב דיורין כך עקר ל\"א מלכי' בימי יהושע וישב בהן ישראל ולכן נק' ארון הברית אדון כל הארץ שע\"י בחי' ברית העליון נעשה יחוד והמשכת ש' הוי' בש' אד' והו\"ע יחוד תושב\"כ עם הארון תושבע\"פ עד שהארון נק' אדון ל' זכר, ויוסף שהו' מרכבה לבחי' זו לכן נקרא הים מפני ארונו וכמ\"ש הים ראה וינוס כו' מלפני אדון, היינו ארונו של יוסף שנק' ג\"כ אדון ע\"ש שקיים זה מ\"ש בזה שהי' מרכבה לבחי' ברית העליון כו', אבל שלמה שפגם כנ\"ל לכן דבקו שערים וכנ\"ל.\n<b>אמר</b> ך\"ד רננות ולא נענה, הנה בתענית תיקנו חז\"ל ך\"ד ברכות כמארז\"ל במשנה פ\"ב דתעניות ואומר ח\"י ברכות שבכ\"י ומוסיף עליהם עוד שש, והיינו להיות כי התעניות שעל ירידת גשמים הוא כענין המשכת היחוד דתושב\"כ ותושבע\"פ וכנ\"ל בענין מוריד הגשם, וכתי' בתורה יערוף כמטר לקחי, וזהו שהמשכיל בקרא כי כאשר ירד הגשם והשלג מן השמים והרוה את הארץ והולידה והצמיחה כן יהי' דברי אשר יצא מפי שהמשיל דברו אשר יצא מפיו שהוא ענין התורה כמ\"ש ודברי אשר שמתי בפיך שהוא ההמשכה מבחי' שמים לבחי' ארץ מתושב\"כ לתושבע\"פ, והשפעה זו נק' גשם שלכן נמשלה לגשם, ולכן מצינו ברשב\"י כשהי' צריכי' למטרא דרש בפסוק מה טוב ומה נעי' שבת אחים גם יחד ועי\"ז ירדו גשמי' וזהו כסדר המדריגות אמנם כשהגשמי' נעצרו צריך להמשיך מבחי' י\"ג מדה\"ר לרחם על הבריות ולהיות נושא עון ועובר על פשע וזהו שהוסיפו ששה ברכות על ח\"י שבכ\"י, כי בכ\"י הח\"י ברכות הוא בחי' יחיד חי העולמים מלך והם כנגד ח\"י חוליות השדרה עד שבשים שלום נמשך הטפה כמ\"ש במ\"א באורך, אבל בזמן עצירות"],[2000500219,"גשמים הוסיפו עוד ששה להיות כי ע\"י וא\"ו הוא בחי' ההמשכה מבחי' יחיד לחי העולמי' מלך, והוא\"ו רומז על הק\"ו ראשית ההמשכה ולכן תקנו ך\"ד ברכות, ורשב\"י שפעל ע\"י לימוד התורה לבד י\"ל שדוקא רשב\"י שהי' תורתו אומנתו פעל ע\"י התורה מה שצריכי' בתפילה ך\"ד ברכות, כי התורה היא חיי עולם והתפילה חיי שעה ויש בכלל מאתי' מנה, ולכן שלחו לרשב\"י דוקא, כמ\"ש בזח\"ג אחרי דנ\"ט, ובתענית גשמי' היו אומרי' ך\"ד ברכות, ועד\"ז אמר שלמה ך\"ד רננות לפעול שיומשך היחוד מתושב\"כ ותושבע\"פ וכנ\"ל בענין גל עיני ואביטה נפלאות, גם ך\"ד הוא דך וכתי' אל ישוב דך נכלם שהוא בחי' תפלה לעני שמעורר למעלה מאד, וע\"י דך יומשך מכ\"ד ספרין דאורייתא, ועכ\"ז לא נענה, כיון שהזכיר ה' אלקי' אל תשב פני משיחך זכרה לחסדי דוד עבדך נפתחו השערי', והענין הוא דהנה דוד הי' מרכבה למדת המל' ומסר נפשו עלי', ולכן נק' המלוכה ע\"ש מב\"ד וכל ימיו הי' עסקו לבנות מדת המל' וכמ\"ש זכור כו' את כל ענותו, אם אתן שנת לעיני, עד אמצא מקום לה' כו' מל' פה תושבע\"פ קרינן לה, והיינו כי עיקר ענין המלוכה הוא ציוים לגלות רצונו שזהו בתושבע\"פ וכנ\"ל בענין מה שבתושבע\"פ דוקא מתגלה הרצון עליון איך ומה לעשות המצוה, ולכן מאחר שכל ימיו עסק דוד בבנין המל' היינו שיומשך היחוד עליון מתושב\"כ לתושבע\"פ ולכן כשהזכיר חסדי דוד פי' ע\"ד איזהו חסיד המתחסד עם קן דילי', והיינו שהתחסד עם בחי' מל' ותושבע\"פ והי' מרכבה לבחי' זו ועסק כל ימיו בזה וכנודע מענין אבן מאסו הבונים והוא נטל אבן זה, וכמארז\"ל ע\"פ ואנכי תולעת שהי' מעדן עצמו כתולעת בלמדו תורה, מיד נפתחו השערי' והכניסו ארון הברית להיכל קוהק\"ד שהוא מקום היחוד שיומשך היחוד"],[2000500220,"מתושב\"כ לתושבע\"פ כו' ומזה נשתנו פני שונאי דוד כשולי קדרה כי כולם ידעו שנמחל לו דאל\"כ לא הי' נענה בשבילו כנ\"ל בענין שלמה וזהו ביום השמיני שלח את העם פי' שיהיו בבחי' עם היינו ע\"ד דכתי' אשרי העם שהוי' אלקיו, וכתי' כי עם קדוש אתה להוי' אלקיך, עם נושע בהוי' פי' שימשיכו ההמשכה מבחי' ש' הוי' לש' אלקי' והו\"ע ההמשכה מתושב\"כ לתושבע\"פ, ועי\"ז ויברכו את המלך ע\"ד שארז\"ל בזמן שישראל עושי' רצוש\"מ מוסיפי' כח בגבורה של מעלה, ועיקר בנין המל' הוא מהגבורות ולכן עי\"ז ויברכו את המלך, על כל הטובה אשר עשה ה' לדוד עבדו שכיון שהזכיר חסדי דוד מיד נענה כו'. —————— ּ ——————"],[2000500221,"<h3>ואעשך לגוי גדול כו'</h3>\n<b>בס\"ד פ' לך</b>\n<b>ואעשך</b> לגוי גדול, ואברכך ואגדלה שמך והי' ברכה, וארז\"ל בפב\"ת דפסחים דקי\"ז ע\"ב א\"ר שמעון בן לקיש ואעשך לגוי גדול זהו שאומרים אלקי אברהם ואברכך זהו שאומרים אלקי יצחק ואגדלה שמך זהו שאומרים אלקי יעקב יכול יהו חותמין בכולן ת\"ל והי' ברכה בך חותמי' ואין חותמין בכולן, והענין הוא כי הנה נודע ממארז\"ל אר\"ל האבות הן הן המרכבה, והיינו בחי' מרכבתא עילאה דחג\"ת דאצי' כי אברהם הי' מרכבה למדת החסד דאצי' ולכן איתא בפרד\"ס בשם ס' הבהיר שאמרה מדת החסד כל ימי היות אברם"],[2000500222,"בארץ לא הוצרכתי לעשות מלאכתי שהרי אברם עומד ומשמש במקומי שנא' וישמור משמרתי ששמר משמרת מדת החסד וא\"כ הי' במקום מדת החסד דאצי', ולכן איתא בס' או\"צ שאברהם הי' נדיב בין בנפשו בין בגופו בין בממונו, ויצחק הי' מרכבה למדת הגבורה ולכן נא' ופחד יצחק הי' לי, ונמצא שכינה ליצחק שם אחד כמו למדת הגבורה שכמו מדת הגבורה קורי' מקובלי' הראשוני' בשם מדת הפחד כן יצחק נק' פחד שז\"ע אומרו פחד יצחק, ויעקב הי' מרכבה למדת הת\"ת ולכן כמו שהת\"ת כולל ב' בחי' דחו\"ג כן יעקב עשה לו מקל לבנה לח ולוז וערמון כמ\"ש ויקח לו יעקב מקל לבנה לח ולוז וערמון ויפצל בהן פצלות לבנות פי' שלקח לו מדה זו שכולל חו\"ג להיות מרכבה לה להיות במקומה, ולכן בירך יעקב את בניו כשירדו למצרים ברחמים כמ\"ש ואל שדי יתן לכם רחמים להיות כי כל ימיו הי' עבודתו בבחי' זו עד שנתאחד בה כו', וא\"כ מה שאומרים אלקי אברהם היינו בחי' שלמעלה מהחסד דאצי' והוא בחי' חכ' עילאה דאצי', וכמ\"ש בזח\"ב פ' בשלח דנ\"ה ע\"ב אלקי אבי וארוממנהו כמד\"א אלקי אברהם וכ' המק\"מ פי' אבא שהוא אלק' של חסד, א\"ר יוסי אי הכי אמאי וארוממנהו דהא אלקי אברהם לעילא הוא, פי' כי הוא בח\"ע וא\"צ הרמה, א\"ל אפי' הכי אצטריך, והיינו להעלותו לבחי' אריך כו', נשמע דאלקי אברהם הוא בחי' אוא\"ס המלובש בחכ' עילאה דאצי', ולכן מקדימין שבח זה לשבח האל הגדול הגבור שהוא בהתפשטות ההמשכה במדות חג\"ת, אבל אלקי אברהם הוא בחכ', וא\"כ זה שיתעלה אברהם כ\"כ שיהי' מרכבה עילאה זהו ואעשך לגוי גדול כו' ועי\"ז זכה לעמוד אומה שנק' גוי גדול.\n<b>וביאור</b> ענין לגוי גדול, הנה ארז\"ל במד\"ר עפ\"ז ואעשך לגוי גדול אותה עומה דכתי' בה ומי גוי גדול ממך אני מעמיד אותה, שנק' גדולי' ע\"ש גדול הוי' ומהולל מאד בעיר אלקינו, וכתי' כי חלק הוי' עמו שיש בכאו\"א ש' הוי' ולכן נק' גדול ע\"ש גדול הוי' כו' ומקורם אברהם חסד עליון,"],[2000500223,"והענין הוא דהנה ארז\"ל ברבות ע\"פ ויעש אברהם משתה גדול, גדול העולמי' הי' שם, וכן בפ' איננו גדול פי' במד\"ר וישב פ' פ\"ז על גדול הוי' ומהולל מאד ע' במד\"ר שם ובמת\"כ שם, וא\"כ פי' גוי גדול שגדולת הוי' הוא גם בחלק הוי' עמו, ולכן כל רואיהם יכירום ע\"ד וראו כו' כי שם הוי' נקרא עליך, וביאור ענין שם הוי' שיש בכאו\"א מישראל, הנה היו\"ד הוא בחי' הביטול שלמעלה מן החכ' ולמעלה משכל המושג שאין רצונו להיות נפרד מאלקות בלי שום טו\"ד ומה שעושה איזהו דברים אשר לא כדת נדמה לו שעי\"ז לא יהי' נפרד מאחדותו ית', אבל אם הי' יודע שעי\"ז יפרד מאחדותו ית' לא הי' רוצה בשו\"א בעולם שהרי גם הנשים והקטנים וקלי הדעת אינם רוצים ליפרד מאחדותו ית' שזהו מפני שמושרש בכ\"י בירושה לנו מאבותינו הביטול שלמעלה מן הטו\"ד כלל, וה\"ה הוא בחי' התבוננו' באורך ורוחב באריכות ההתבוננו' איך שמה רבו מעשיך ה' הוא בחי' ריבוי התהוות הנבראי' שנתהוו ריבוי בחי' דומם כמו מן האבנים הפשוטי' עד אבנים טובות שמאירים בזוהר ניצוצי' שנתזי' מהם שיש ריבוי מינים בהם שכל אחד מובדל מזולתו הן באיכותו והן בזיו זוהרו כו', וכן בצומח יש ריבוי מינים אילנות ודשאים וצמחי' רבים מספר עצום מאד וכל מין נבדל מזולתו במראיתו וטעמו ופעולתו, וכן בחי יש ריבוי מינים מאד בהמות חיות ועופות ושקצים ורמשים, וכל א' מובדל מזולתו בטבעו והנהגתו וציורו כו' וכן באדם יש כמה וכמה מינים וכל אחד טבעו משונה מזולתו ובציורו אין א' מהם דומה לחבירו* הגם כי כל א' נטבע בחותם של אדה\"ר כמארז\"ל במשנה בספ\"ג דסנהדרין, ועז\"נ מה רבו מעשיך ה', וכתי' מה גדלו מעשיך ה' שקאי על נבראי' הגדולים"],[2000500224,"מלאכים שכלי' נבדלים שמלאך בשליש העולם עומד, והשמש והירח וכוכבי' ומזלות וגלגלי' שהם נבראי' הגדולים וג\"כ כ\"א מובדל מזולתו בכל פרטי פרטיהם וכחותיהם אשר ניתן להם ועבודתם משונה זמ\"ז ועלי' נא' מה גדלו מעשיך ה', וכלליות כולם נבראו מאות א' בהבראם בה' בראם, וכלליות עוה\"ב הוא ג\"כ מאות א' ביו\"ד נברא העוה\"ב, וכמארז\"ל ע\"פ כי בי\"ה הוי' צור עולמים ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז שדעת לנבון נקל שגם באדם שהוא נברא פרטי אינו תופס מקום כלל ב' אותיות נגד מה שיוכל לדבר אפי' ביום אחד וכ\"ש נגד כלליות הדבור של האדם, וכ\"ש לגבי אוא\"ס ב\"ה הסוכ\"ע וממכ\"ע, אשר גם בחי' נשגב הוא אוא\"ס הסוכ\"ע הוא ג\"כ רק שמו לבדו* כו' וע\"י התבוננו' זו יבוא לדבקה בו ית' כי למה יחפוץ במה שנתהוה מב' אותיות ולמה לא ירצה יותר לאוא\"ס ב\"ה עצומ\"ה שבב' אותיות ברא הכל וכתי' כי עמך מקו\"ח שמקור החיים ומקור התענוגי' הוא עמך שבטל וטפל לך ובמה יחפוץ יותר אם בדבר הטפל אם במי שנטפל לו כו' וכאשר יאריך הרבה בהתבוננו' זו בהעמקת הדעת יבין גם שכלו הגשמי איך שהוא האמת באמת לאמיתו ויבא לדבקה בו בדיבוק אמיתי וקשר חזק בל תמוט, וגם נפשו הבהמי' לא ימנע אותו מאחר שגם ע\"פ שכל אנושי שהוא מקור למקור לשכל המדות דכח המתאוה דיצה\"ר יבין בטוב טעם ודעת איך שמה טוב ומה נעים ההתדבקות באלקי' חיים ומלך עולם, וזשא\"ה ואתם הדבקי' בה' אלקיכם חיים כולכם היום פי' שע\"י ההתדבקות לאלקות תהיו כולכם חיים בחיי החיים גם בבחי' היום שהוא בחי' היום לעשותם בעוה\"ז הגשמי, ולא יחי' בחיי בשרים ושכל הגשמי כמו שהוא בלי בחי' התבוננו' הנ\"ל שממשיך לאדם לפנות אחר ההבל ויהבלו לפנות כל היום וכל הלילה אחרי תאוות גשמים, וכל עסקו כל היום להיות בקנאה עבור התאוה והכבוד שהם מוציאים את האדם מן העולם היפך בחי' החיים הנ\"ל, או מי שהוא רודף לבצעו כל היום הוא ג\"כ כנ\"ל בכדי שיוכל להשיב מה שלבו מתאוה או כבוד המדומה או שארי תאוות או שמתאוה לעצם הממון שיש מי שהוא משוקע בתאוה זו ג\"כ לאהוב עצם"],[2000500225,"המעות ולא הבכן שיוצא מזה שהרי הוא לא יתאוה כלל לקנות לעצמו חפצים יקרים או לפזר עבור להשיג כבוד יותר גדול מהראוי מפני כי חס על ממונו, וגם הנצרך לגופו ג\"כ יקמץ בזה מפני שממונו חביב עליו מגופו*, וכ\"ש לעשות איזה מצוה שעולה בדמים יקרים שיפלא בעיניו האיך יוותר ממונו אשר זהו כל חיותו ותענוגו לפי הסכמת שכלו המשוקע בתאוות גשמיות ורצונות זרים לא זהו הדרך אשר ישכון בה אור הוי' ונמשל כבהמות נדמו שהלא הבהמה היא שרודפת אחר מאכל וכדומה מבלי השיג יותר והאדם הרודף אחר דברים שטוב לו לחיי גופו או כבודו ה\"ה גרוע מהבהמה שהרי לבהמה לא ניתן שכל יותר שתשכיל איזה דבר יותר ולא יש בה נפה\"א שישכיל דבר מה בהתבוננו' הבורא יחיד ומיוחד, אבל האדם אשר ניתן לו להשכיל דבר חכ' בהתבוננות אלקות ומניח זאת לרדוף אחר ההבל כבהמה הרי הוא גרוע יותר הרבה שה\"ה אדם ועושה מעשה בהמה, ואוי לו לנפשו שירדה פלאים מתחת כסה\"כ לבוא בגוף הגשמי שירידתה היא צורך עלי', וזה שנמשך אחר ההבל לא די לו שלא תיקן מאומה הרי הורידה ממקום כבודה שהיתה עומדת באהוי\"ר כמ\"ש חי ה' אשר עמדתי לפניו שענין העמידה הוא כמ\"ש שרפים עומדים שעמידתם הוא בביטול, והגם כי לא יש שם מונע מ\"מ ה\"ה כמו שצריך להיות, אבל כשירדה בגוף ונמשכה אחר ההבל הרי ירדה ממהותה לגמרי, וצלל במים אדירים שהי' יכול להתדבק בבחי' אדיר במרום ה' והעלה בידו חרס, ולא עוד אלא שעי\"ז נעשה כתמי' בנפשו שצריכה זיכוך וטהרה לרפאותה מחוליתה ע\"י גיהנם וכף הקלע עד שמזככי' אותה, והלואי תהי' השבה למעליותא כנתינתה עכ\"פ, שטהורה היא עכ\"פ כמאמר נשמה שנתת בי טהורה, והוא עשה בה כתמי' ופצעי' רבים מכף ראשה עד רגלה בכל ציור קומה הן בשכל והן במדות אין בה מתום כלל, וכאשר יעמיק דעת גודל עוצם העלאתה ע\"י התבוננו' והעמקת הדעת כנ\"ל נגד ירידתה עשר מעלות אחורנית כאשר נמשכה אחר ההבל יעורר ר\"ר על נפשו איך שירדה פלאים כו' והוא רחום יכפר עון להוציאה מחוליתה ושתבוא לדבקה בו ית' אוא\"ס חיי החיים ע\"י התבוננות הנ\"ל."],[2000500226,"<b>והוא\"ו</b> הוא בחי' מדות ע\"ד דכתי' לך ה' הגדולה והגבורה והת\"ת והנצח וההוד כי כל בשמים ובארץ לך ה' הממלכה, והיינו שכל מדותיו יהי' בבחי' לך היינו בחי' אוא\"ס דלאו מכא\"מ איהו כלל, והיינו שיהי' מדת חסדו לה' להרבות בצדקה וכמו שלמעלה נא' מכלכל חיים בחסד כן יהי' הוא משפיע לדל להחיות נפשו ע\"י השפעת מדת חסדו, ובחי' הגבורה הוא להיות בבחי' איזהו גבור הכובש את יצרו להיות סומ\"ר ועש\"ט ולהגביר על יצרו להיות גומל לחייבים טובות כו', ומדת הת\"ת הוא לבוא לבחי' רחמים לרחם על הבריות ולהיות טוב לשמים וטוב לבריות כו', והנצח הוא בבחי' עבודה כל היום להיות נשאר הסכם חזק אצלו כל היום בל תמוט כי הרי לא יוכל להיות בהתבוננו' כל היום כ\"א בעת תפלה או בעת מן העתים שיבחר להיות בהתבוננות, ועל כל היום צ\"ל הסכם חזק על בחי' סומ\"ר ועשה טוב, והוד הוא בחי' ההודאה שהרי בשכלו הדל לא יכול להבין הכל ולכן צריך להודות שכן הוא וכמ\"ש כי לך טוב להודות וכתי' טוב להודות לה', כי כל בשוב\"א הוא בחי' ההתקשרות כנודע שבחי' יסוד הוא בחי' התקשרות, לך ה' הממלכה הוא בחי' קעומ\"ש שמקבל ע\"ע עול מלכותו ברצון שזהו הקדמה לעול מצות קבלו מלכותי ואח\"כ קבלו גזרותיו וכמארז\"ל במשנה למה קדמה שמע לוהא\"ש כדי שיקבל עליו עומ\"ש ואח\"כ יקבל עליו עול מצות, והה' אחרונה דש' הוי' הוא בחי' צדקה כי צדקה הוא צדק ה', כי על הצדקה כתי' וצדקה כנחל איתן פי' שעי\"ז זוכה להמשיך מבחי' איתן שהוא כמשמעו קשה למעלה מן השכל המושג, ולכן קודם התפלה צ\"ל כמארז\"ל ר\"א יהיב פרוטה לעני והדר מצלי ע\"ש אני בצדק אחזה פניך שע\"י הקדמת הצדקה עי\"ז זוכה לבוא בתפלה ע\"י ההתבוננות לבחי' איתן קוש\"י ובחי' יו\"ד הנ\"ל שהוא ג\"כ למעלה"],[2000500227,"משכל המושג עדיין כנ\"ל וזהו שנק' כי גוי גדול ע\"ש בחי' גדול הוי' שנמצא בכאו\"א מישראל לפי ערכו כו', וזהו ואעשך לגוי גדול אותה אומה דכתי' בה ומי גוי גדול ממך אני מעמיד כו', וי\"ל כי ע\"י בחי' גדול זה ממשיכי' שיומשך מאוא\"ס ב\"ה מבחי' שמו הגדול ש' הוי' דלעילא ע\"ק וז\"ע לגוי גדול שהם עצמם בחי' גדול ע\"ש שהם מעוררי' בעצמם בחי' גדול הוי' שבכאו\"א ועי\"ז ממשיכים מבחי' שמו הגדול ש' הוי' דלעילא בחי' ע\"ק כו'.\n<b>וענין</b> אלקי יצחק הוא בחי' קו השמאל בג\"ה והו\"ע ההעלאה מלמטלמ\"ע כו' בענין עבודת הקרבנות וכענין הבארות שחפר יצחק כמ\"ש ענינם בת\"א בד\"ה אלה תולדות יצחק ובהגהות לשם, ועז\"נ ואברכך פי' וענין הברכה שיהי' ההעלאה והצמיחה בברכה וריבוי וכמ\"ש בלק\"ת פ' נשא בד\"ה כה תברכו בפי' יברכך ה', ולכן מצינו שיצחק בירך את יעקב ויתן לך האלקי' מטל השמים כי שרשו מקו המדה בוצינא דקרדוניתא שמשם באה הברכה, ואגדלה שמך זהו שאומרים ואלקי יעקב כי יעקב הוא בריח התיכון המבריח מן הקצה אל הקצה ונאמר בו לשון ואגדלה שענין הברכה בריבוי שזהו ואברכך דיצחק פועל הגדלה באדם המתברך וכמ\"ש ויגדל האיש הלוך וגדל שהוא ע\"י שנתברך בריבוי שהוא ע\"י הברכה שבירכו הוי' שמצא מאה שערים עי\"ז נתגדל הלוך וגדל עד כי גדל מאד כמ\"ש בפ' אלה תולדות, וגם כולל ענין אברהם דכתי' ואעשך לגוי גדול והיינו כנ\"ל שיעקב הי' מרכבה למדת הת\"ת שכולל ב' בחי' חו\"ג וכמ\"ש אלקי אבי אברהם ופחד יצחק הי' לי כו'. והיה ברכה, יכול יהו חותמין בכולן ת\"ל והי' ברכה בך חותמי' כי אברהם בחי' חסד נק' יומם דאזיל עם כולי יומין, בזח\"ג אמור ק\"ג ע\"ב שכל הו\"ק מקבלי' ממנו כי החסד מקבל מהבינה, ואזיל עם כולי יומין, ונמצא מקשר אור הג\"ר כח\"ב בכל הו\"ק וסיומן הוא ביסוד, וז\"ע בקר דאברהם ובקר דיוסף בזח\"ג פ' בלק דף ר\"ד סע\"א וע\"ב וע' בזהר נשא דקמ\"ב ע\"א.\n"],[2000450052,"<h3>וידבר כו' ויצוום כו'</h3>\n<b>בס\"ד פ' וארא ל\"ח</b>\n<b></b>מספר למעלה כו' שיטות אם אצילות הוא בלי מספר - (פרק: א-ג)\n[וארא]\n<b>וידבר</b> ה' אל משה ואל אהרן, ויצוום<sup data-n=\"1\">1</sup> אל בני ישראל ואל פרעה כו' להוציא<sup data-n=\"2\">2</sup> כו'. וצ\"ל מה\"ע הציוי לבנ\"י שיצאו מאמ\"צ, הלא סבלו כובד השעבוד, ובוודאי רצונם הי' לצאת וכמ\"ש וישמעו כי פקד ה'<sup data-n=\"3\">3</sup>, וכי<sup data-n=\"4\">4</sup> בלשון הזה הי' שמור אצלם מפי יוסף שיגאלו<sup data-n=\"5\">5</sup> ממצרי' ולמה היו צריכים לציוי. וגם לא בדידם תלי' מילתא כלל, ומה יועיל הציוי להם. והאיך יועיל הציוי להמשועבד שיצא משעבודו, שלכאו' אינו שייך כלל כ\"א להמשעבד אותם, ושנתנו לו להשתעבד, ומה גם כי הקדים הציוי להם מכמו לפרעה שהיו משעבדים<sup data-n=\"6\">6</sup> תח\"י, שכ\"ז אינו מובן כלל. וגם מה שהשיב משה ק\"ו הן בנ\"י לא שמעו אלי<sup data-n=\"7\">7</sup> ואיך ישמעני פרעה, הלא מה שלא שמעו בנ\"י זהו מטעם שאומר שם מקוצר רוח ועבודה קשה שכ\"ז אינו שייך כלל אצל פרעה מלך מצרים, ובאמת זהו מיו\"ד ק\"ו שבתורה<sup data-n=\"8\">8</sup>. וגם מנושא התירוץ שלא שמעו זהו מחמת הקוצר רוח ועבודה קשה הא בלתי זה היו שומעי' ושמיעתם הי'",[["1","1","<b>וידבר. . ויצוום</b>: מכאן מתחיל ההמשך הכולל ד מאמרים (י\"ג פרקים), והם: א) ד\"ה זה הכולל פרקים א — ג. ב) ד\"ה גדול אדונינו הכולל פרקים ד — ו. ג) אז ישיר הכולל פרקים ז — י. ד) ועמדו רגליו הכולל פרקים יא — יג.\nדרוש זה [הכולל פרקים א-ג] מיוסד על מאמר ד\"ה זה מכ\"ק אדמו\"ר הזקן משנת תקס\"ח שנדפס באוה\"ת וארא ע' קצו בתוס' הגהות מכ\"ק אדמו\"ר הצ\"צ, והערות נוספות שם ע' ריז ואילך, וקיצור מהדרוש באוה\"ת פרשתינו כרך ח ע' ב'תתצד. וביאור על הדרוש (משנת תקס\"ח) ע' קמו ואילך. (וראה) ע' רי ואילך. ראה סה\"מ תרכ\"ז ע' צה ואילך. וש\"נ. תרכ\"ח ס\"ע קמד ואילך. וראה גם ספר המאמרים תרס\"ד ע' ריא. תרס\"ח ע' סג ואילך. תרפ\"ד ע' רסה ואילך. פלח הרמון שמות ע' נג ואילך.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק ההנחות [ומשם נעתקה הכותרת שבריש המאמר פרט לתיבת בס\"ד].\nדרוש זה נזכר בסה\"מ תר\"ן ע' שז. ע' רפג. ע' שעח. ע' שעט. הגהות לד\"ה פתח אלי' תרנ\"ח ע' לו. המשך תער\"ב ח\"ג ע' א'תעא.\nההמשך נדפס מגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש הנמצא בבוך 1089 בתחילתו. ונמצא גם בכת\"י מעתיק הר\"ש סופר בבוך 2083 בתחילתו ונרשם לקמן: ב."],["2","2","<b>וידבר ה'. . ויצוום. . להוציא</b>: וארא ו, יג."],["3","3","<b>וישמעו כי פקד ה'</b>: שמות ד, לא."],["4","4","<b>וכי</b>: כ\"ה גם בב."],["5","5","<b>בלשון הזה. . שיגאלו</b>: ראה פדר\"א פמ\"ח. תנחומא באבער כא ובהערה קז. רש\"י שמות ג, יח."],["6","6","<b>משעבדים</b>: כ\"ה גם בב."],["7","7","<b>הן בנ\"י לא שמעו אלי</b>: וארא ו, יב."],["8","8","<b>מיו\"ד ק\"ו שבתורה</b>: ראה ב\"ר פצ\"ב, ז. רש\"י וארא ו, יב. שיחת ש\"פ מקץ תשל\"ו סכ\"ח. ס\"ל — סל\"ד."]]],[2000450053,"פעולה להענין אשר לכאו' זהו נגד השכל כלל שמה יועיל המשועבד ברצונו לצאת בלתי הסכם ורצון מי שנשתעבדו לו. וגם צ\"ל תשובת הקב\"ה על טענו זו<sup data-n=\"9\">9</sup> דמשה במה שצירף את אהרן אתו, שהרי לא נתחדש מאומה כ\"א מה שדיבר ה' אל משה ואל אהרן יחד, ומה יועיל חיבור אהרן עמו שעי\"ז ישמע גם פרעה לציויהם וכ\"ש בנ\"י שג\"ז אינו מובן כלל. ואם נא' שזהו תשובה על מה שאמר ואני ערל שפתים<sup data-n=\"10\">10</sup>, הלא כבר אמר לו תשובה זו בפ' שמות (ד' י\"ד) הלא אהרן אחיך הלוי ידעתי כי דבר ידבר הוא כו'. ובכדי להבין כ\"ז צ\"ל מ\"ש לעיל מיני' בתחילת הפרשה, וארא אל אברהם ואל יצחק<sup data-n=\"11\">11</sup> כו' באל שדי, ושמי הוי' לא נודעתי להם<sup data-n=\"12\">12</sup>. אשר לכאו' א\"מ כלל, הלא כמה פעמי' נא' ש' הוי' אצל אבות העולם<sup data-n=\"13\">13</sup> כמ\"ש באברהם, וה' אמר המכסה אני מאברהם<sup data-n=\"14\">14</sup>, וכתי' וירא אליו הוי'<sup data-n=\"15\">15</sup>, וכן ביצחק כתי' וירא ה' אליו (בראשית ך\"ו ב, ך\"ד)<sup data-n=\"16\">16</sup> וביעקב נא' ג\"כ (ך\"ח י\"ג) והנה ה' נצב עליו ויאמר אליו<sup data-n=\"17\">17</sup> אני הוי', ויובן בהקדם ענין מ\"ש ועלמות אין מספר א\"ת ועלמות<sup data-n=\"18\">18</sup> אלא ועולמות אין מספר, שצ\"ל מאחר שהם עולמות ה\"ה בע\"ג והאיך יתכן שיהי' בלי מספר כלל, ומקרא מלא כתי' המוציא במספר צבאם<sup data-n=\"19\">19</sup> שהם בבחי' מספר וגבול, ועד\"ז מצינו שהקשו בגמ'<sup data-n=\"20\">20</sup> כתי' אלף אלפים ישמשוני'<sup data-n=\"21\">21</sup> כו' וכתי' היש מספר לגדודיו<sup data-n=\"22\">22</sup>, ולגדודיו אין מספר<sup data-n=\"23\">23</sup>, וכן ארז\"ל ביומא<sup data-n=\"24\">24</sup> כתי' והי' מספר בנ\"י אשר לא יספר<sup data-n=\"25\">25</sup> שהקשו איך יתכן שיהי' במספר אשר לא יספר, והנה יש ב' תירוצי' ע\"ז הא' תירצו בגמ' שבגדוד אחד יש מספר, והיינו מ\"ש אלף אלפי' זהו מספר גדוד א' שכל גדוד הוא מספר אלף אלפי', אבל לגדודיו אין מספר, והב' תירצו שם<sup data-n=\"26\">26</sup> שבזמן שישראל ערש\"מ אזי אשר לא יספר, וכשאין עושי' רש\"מ אזי והי' מספר כו'.<sup data-n=\"e1\">*</sup>",[["9","9","<b>טענו זו</b>: ב: טענה זו."],["10","10","<b>ואני ערל שפתים</b>: וארא שם."],["11","11","<b>וארא. . ואל יצחק</b>: וארא ו, ג [ושם: אל. אבל כ\"ה גם לקמן (בחלק הנחות) ד\"ה ואהי' אצלו אמון על יד הערה 37. תו\"ח וארא ח\"א מט, ג. סה\"מ תרכ\"ט ע' מא]."],["12","12","<b>ושמי הוי' לא נודעתי להם</b>: ראה גם תו\"ח בא ח\"א קיג, ב והערה 102. וראה גם לקמן המשך חייב אדם לברך פל\"ו על יד הערה 1454."],["13","13","<b>אבות העולם</b>: ירושלמי סנהדרין פ\"י, ה\"א. תנחומא מקץ ט. ויחי ו. ועוד. שמו\"ר פל\"ב, ב. ועוד. ראה גם תו\"ח לך פה, א. תולדות קמב, ב. ויצא קעו, א."],["14","14","<b>וה' אמר המכסה אני מאברהם</b>: וירא יח, יז."],["15","15","<b>וירא אליו הוי'</b>: וירא יח, א."],["16","16","<b>ביצחק כתי' וירא ה' אליו. . ך\"ד)</b>: ושם: וירא אליו ה'. אבל כ\"ה גם לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב נדפסה בחלק ההנחות."],["17","17","<b>וביעקב. . ויאמר אליו</b>: תיבת אליו ליתא שם. וכן ליתא בב."],["18","18","<b>ועלמות. . א\"ת ועלמות</b>: שה\"ש ו, ח. ת\"ז בהקדמה (יד, ב). ראה זהר אחרי עא, ב. ע\"ז לה, ב. סה\"מ תרל\"ה ח\"א ע' נג."],["19","19","<b>המוציא במספר צבאם</b>: ישעי' מ, כו."],["20","20","<b>שהקשו בגמ'</b>: חגיגה יג, ב."],["21","21","<b>אלף אלפים ישמשוני'</b>: דניאל ז, י."],["22","22","<b>היש מספר לגדודיו</b>: איוב כה, ג."],["23","23","<b>ולגדודיו אין מספר</b>: לשון הגמרא שם. וכ\"ה בסה\"מ תרכ\"ז ע' צה."],["24","24","<b>ארז\"ל ביומא </b>: כב, ב."],["25","25","<b>והי' מספר בנ\"י אשר לא יספר</b>: הושע ב, א."],["26","26","<b>תירצו שם</b>: יומא כב, ב."],["e1","*","<b>בשולי היריעה נרשם בגוכתי\"ק</b>: צ\"ל שע\"י תומ\"צ מתוסף בחי' בלי מספר."]]],[2000450054,"<span data-k=\"ks\"><b>קיצור.</b> למה הוצרכו ישראל לציוי ומה יועיל להם הציוי, וגם מהו התועלת מחיבור אהרן, ואיך א' ושמי הוי' לא נודעתי להם ובאמת נא' כמ\"פ ש' הוי' אצל האבות, וענין איך שייך עולמות בלי מספר ובענין מספר ובלי מספר הגדודי' ב' תירוצי' שבגמ' ע\"ז.</span>\nב) <b>אמנם</b> הענין הוא דהנה בבחי' זיו והארה המאיר מאתו ית' להוות ולהחיות בחי' עולמות, והנבראי' בע\"ג ותכלית הנה בבחי' הארה זו וזיו זה שייך בחי' מספר, משא\"כ בבחי' אוא\"ס שלמעלה מבחי' הזיו וההארה המצמצמת וכן המתפשטת להוות ולהחיות העולמות בי\"ע הוא בלי מספר, כ\"ה דברי רבינו ז\"ל<sup data-n=\"27\">27</sup> וצ\"ל שמפרש שבחי' בי\"ע, ובחי' שרש ומקור המצמצם להוות בי\"ע הוא בבחי' מספר, משא\"כ בחי' האצי' מה שלמעלה משרש התהוות בי\"ע הוא בבחי' בלי מספר כו', ובאמת צ\"ל זה הלא לכאו' האיך אפשר להשוות המהוה עם המתהוה, ואם שניהם הם בע\"ג האיך יתהוה זה מזה ע\"ד בריאה חדשה, וכנודע שענין בחי' בריאה יש מאין אינו כמו סדר השתלשלות עד\"מ שכל ומדות שהגם שהמדות הם מובדלי' מהשכל עכ\"ז הרי הי' תחילה בשכל שהרי יש בחי' מדות שבשכל, אלא ששם הם בלתי מורגשי' כ\"כ שהשכל הוא העיקר, והמדות שבו נעלמי' הם בהשכל, וכשיוצאי' מהעלם אל הגילוי למדות שבלב אז הם נרגשי' לעיקר, והשכל המחייבם הוא בהעלם, והרי באמת נק' רק בחי' יציאה מהעלם אל הגילוי ולא דבר חדש כלל משא\"כ הבריאה א\"א לומר כלל כן האם נא' שהשמי' והארץ וכל תולדותיהן היו תחילה בהעלם ויצאו מהעלם אל הגילוי, אלא שנבראו יש מאין, שענין שם זה מוכיח עליו שלא הי' תחילה שהרי קורא אותו אין ע\"ש ההעדר כו', ואם נא' שגם האין המהוה ה\"ה ג\"כ מוגבל ה\"ז יש שכל הגבלה ליש יחשב, וגם הלא ארז\"ל אם מתכנשין כל באי עולם<sup data-n=\"28\">28</sup> אינם יכולי' לברוא יתוש א' ולהטיל בו נשמה, אלא שענין הבריאה הוא רק בכח האלקה הכל יכול, ואיך נא' על בחי' זו המהוה שזהו ג\"כ כח מוגבל, וכמו\"כ צ\"ל בהיפך שלפי משנת' לעיל שבאצי' שלמעלה מהארת האצי' המהוה בי\"ע הוא בלי מספר, ואיך הם במספר עשר ספירות שהוא מספר מוגבל, שכל מספר הוא מוגבל, וכ\"ש עשר דוקא, וכמ\"ש בס\"י ע\"ס בלי מה<sup data-n=\"29\">29</sup>, עשר ולא תשע, עשר ולא אחד עשר, וא\"כ גם באצי' בכללו ה\"ה בבחי' מספר קצוב שזהו כפל ההגבלה. אך הענין יובן ע\"פ מה שכ' העבוה\"ק, שאוא\"ס הוא שלימותא דכולא<sup data-n=\"30\">30</sup>, וא\"ת שאוא\"ס הוא בלתי בע\"ג ואין לו",[["27","27","<b>זיו. . מספר. . אוא\"ס. . בלי מספר כ\"ה דברי רבינו ז\"ל</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' קסד. אוה\"ת כאן ע' ריז־ סה\"מ תרכ\"ז־ תרכ\"ח שבהערה 1. לקמן (בחלק ההנחות) בהנחת כ\"ק אדמו\"ר מהורש\"ב בהנחה כאן על יד הערה 35."],["28","28","<b>אם מתכנשין כל באי עולם</b>: ראה ירושלמי סנהדרין ספ\"ז. ספרי ואתחנן ו, ה. ב\"ר פל\"ט, יד. וש\"נ. לקו\"ש משפטים כרך כו ע' 366."],["29","29","<b>בס\"י ע\"ס בלי מה</b>: פ\"א, מ\"ג [מנטובא שכ\"ב]."],["30","30","<b>שאוא\"ס הוא שלימותא דכולא</b>: ראה עבודת הקודש ח\"א רפ\"ח. דרך אמונה להנ\"ל מהדורת קה\"ת ע' יג ובהנסמן שם. לקו\"ת עקב טז סע\"א ובהנסמן במ\"מ לשם. לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב — נדפסה בחלק ההנחות — על יד הערה 32 עבוה\"ק בשם הזהר. לקמן המשך חייב אדם לברך על יד הערה 1160. הלשון שלימותא דכולא — ראה ת\"ז בהקדמה (יז, ב)."]]],[2000450055,"כח בגבול אתה מחסר שלימותו, והגבול הנמצא ממנו תחילה זהו בחי' הכלי' דע\"ס<sup data-n=\"31\">31</sup>, שזהו שא' בס\"י עשר דוקא ולא תשע ולא אחד עשר, שבאמת בהאור לא יש שום הבדל והפרש בין אור החכ' לאור החסד עד\"מ, שהאור שוה בכולם כמ\"ש בסש\"ב<sup data-n=\"32\">32</sup>, וההבדלה שבניהם זהו מצד הכלים שבהם וע\"י הוא המספר עשר דוקא, וא\"כ יתכן לומר גם על בחי' הזיו המהוה בי\"ע שהוא כח מוגבל מאחר ששרשו מהכלי' דמל' דאצי', אך איך יתהוה הגבול הנברא מכח הגבול, ואיך קורא אותו אין שפי' העדר, וה\"ה מציאות מוגבל עשר דוקא, אמנם באמת אין בכח הכלי' דאצי' כלל להוות בי\"ע כ\"א ע\"י שבחי' איהו מתייחד עם גרמוהי<sup data-n=\"33\">33</sup> להוות בהם וע\"י בחי' עולמות בי\"ע כמ\"ש באגה\"ק סי' ך' ד\"ה איהו וחיוהי חד, ולכן יתכן לקרות הבריאה יש מאין מב' טעמי' הא' אין שאינו מושג שה\"ז מבחי' איהו, וגם אין ע\"ש ההעדר שהרי הגבול הנמצא ממנו תחילה זהו הכלי' דע\"ס, וההתהוות הוא מבחי' איהו שמתייחד עם בחי' גרמוהי אשר בבחי' איהו אינו שייך שום הגבלה כלל, רק שמתייחד עם גרמוהי בכדי שיתהוה מבחי' יש הנאצל היינו הגבלה הנאצלת בחי' יש הנברא ועיקר התהוות היש הוא מבחי' איהו שהוא כח הא\"ס הכל יכול יכול<sup data-n=\"34\">34</sup>, רק שזהו ע\"י אמצעית יחודו ית' עם בחי' הכלים דע\"ס דמ' דאצי', וזהו דכתי' רבות עשית<sup data-n=\"35\">35</sup> אתה ה' אלקי שבחי' ריבוי הנבראי' שנבראו מאוא\"ס בחי' אח\"פ זהו ע\"י התייחדותו עם בחי' הכלים דע\"ס דמ' דאצי' שמתייחדי' ומתכללים יחד שעי\"ז נמשך ריבוי התהוות נבראי' שונים זמ\"ז כמ\"ש במ\"א, ונמצא מה שפי' שהכח המהוה בי\"ע זהו ג\"כ מוגבל הכוונה על בחי' הכלי', ובחי' האצי' שלמעלה מהתהוות בי\"ע הכוונה על בחי' אורות דאצי' שהם בלי מה כו'. ועוי\"ל שגם בהארה המאיר מבחי' היחוד דאיהו וגרמוהי ג\"כ שייך בה בחי' מספר מאחר שהארה זו נמשכת מבחי' היחוד עם גרמוהי כו' אבל בחי' איהו בעצם שהוא עיקר המהוה, והוא כל יכול שממנו נמשך להוות היש הגשמי זהו בלי מספר, וכ\"מ לשון רבינו ז\"ל שהארה הנמשכת מאתו ית' להוות בי\"ע הוא ג\"כ בבחי' מספר, פי' שהגם שההארה זו נמשכת מאתו ית' היינו בחי' איהו מ\"מ מאחר שנמשך ע\"י בחי' היחוד עם גרמוהי שייך בה בחי' מספר, וי\"ל שההארה זו היא בחי' כח הפועל בנפעל<sup data-n=\"36\">36</sup> שזהו בחי' מספר, אבל הפועל עצמו הוא בלי מספר כו'.",[["31","31","<b>הכלי' דע\"ס</b>: ראה לקו\"ת שם. הנסמן בהמשך חייב אדם לברך פ\"ל הערה 1163."],["32","32","<b>שהאור שוה בכולם כמ\"ש בסש\"ב</b>: ראה שם בהגהה בפ\"ב ובשער היחוה\"א ספ\"ט. פנ\"א (בנפש). אגה\"ק ס\"כ. לקו\"ת שה\"ש ח, ג. לקמן — בחלק ההנחות — הנחת כ\"ק אדמו\"ר מהורש\"ב על יד הערה 33."],["33","33","<b>איהו. . גרמוהי</b>: ראה ת\"ז בהקדמה (ג, ב)."],["34","34","<b>יכול</b>: ב: ליתא."],["35","35","<b>רבות עשית</b>: תהלים מ, ו. ראה גם אוה\"ת פ' ראה ע' תשפו. שה\"ש כרך ב ע' תקמט וע' תקנד. סה\"מ תרכ\"ו ס\"ע רכא ואילך. תר\"ל ע' רסו."],["36","36","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."]]],[2000450056,"<span data-k=\"ks\"><b>קיצור.</b> שעולמות בי\"ע והארת האצי' המהוה בי\"ע זהו בחי' גבול, אבל מה שלמעלה מהתהוות בי\"ע ה\"ז בלי גבול, והגם כי עיקר ההתהוות זהו ממה שבחי' איהו מתייחד עם בחי' גרמוהי מ\"מ זהו ע\"י אמצעית בחי' גרמוהי כלי' שהם בחי' גבול, והאור הוא בבע\"ג בלי מ\"ה בלי מהות, ועוי\"ל שכח הפועל בנפעל זהו בבחי' מספר אבל הפועל הוא בלי מספר.</span>\nג) <b>והנה</b> קוטב דרוש זה הוא לפי מה שאמר רבינו ז\"ל בדרוש זה ע\"פ דיעה זו והוא כפי מה שאמר בדרוש מה יפו פעמייך בנעלי' הנדפס בלק\"ת<sup data-n=\"37\">37</sup>, וז\"ל שם בפ\"ב והנה ענין בחי' כו' צ\"ל תחלה ענין ההשתלשלות<sup data-n=\"38\">38</sup> כו' הוא ע\"י מדותיו<sup data-n=\"39\">39</sup> ית' כו' עכ\"ז מהשתלשלות חסד עליון לא הי' יכול להתהוות בחי' יש ובע\"ג בבחי' נפרד, רק אדרבה ביטול לגמרי כמשל זיו השמש בשמש, אך עיקר ההתהוות הוא<sup data-n=\"40\">40</sup> ע\"פ מדת המל'<sup data-n=\"41\">41</sup> כי אין מלך בלי<sup data-n=\"42\">42</sup> עם כו' אך עכ\"ז הי' העולם מתפשט בלי<sup data-n=\"43\">43</sup> גבול וקץ, ושיהי' התהוות בבחי' גבול מהלך ת\"ק שנה<sup data-n=\"44\">44</sup> הוא ע\"י המלאך סנד\"ל החופה<sup data-n=\"45\">45</sup> כו' את בחי' מל'<sup data-n=\"46\">46</sup> להיות בבחי' גבול מוגבל כמו<sup data-n=\"47\">47</sup> מהלך ת\"ק שנה כו' יעו\"ש. וזהו ע\"ד מ\"ש בזח\"א פ' ויצא דקנ\"ו בענין הדודאים, וע' בפרדס שער השמות<sup data-n=\"48\">48</sup> ובשער י\"ז הוא שער אבי\"ע<sup data-n=\"49\">49</sup> פ\"ד ופ\"ה שמפרש מאמר הזח\"א הנ\"ל בדוחק, ובמק\"מ פי' בשם האריז\"ל כפשוטו וכמ\"ש כאן וכמשי\"ת.\n<b>ויובן</b> ד\"ז גם לפי מ\"ש לעיל בשם העה\"ק שהגבול הנמצא ממנו תחילה זהו בחי' הכלי' דע\"ס, וא\"כ למה צריכי' למלאך סנד\"ל החופה כו', אך הענין הוא דאם<sup data-n=\"50\">50</sup> היות שהגבול הנמצא ממנו תחילה הם בחי' הכלי' מ\"מ ה\"ה אצי' שבכללה אצי' הוא בחי' אלקות וכמ\"ש בד\"ה וככה תאכלו באריכות<sup data-n=\"51\">51</sup> רק שאינם בחי' אלקה כ\"א אלקות בל\"א<sup data-n=\"52\">*52</sup> געטליך ואינו בערך הנבראי' כלל, כי זהו בחי'",[["37","37","<b>מה יפו. . בלק\"ת</b>: שה\"ש מג, ג ואילך."],["38","38","<b>ההשתלשלות</b>: בלקו\"ת שם: השתלשלות."],["39","39","<b>מדותיו</b>: שם: בחי' מדותיו."],["40","40","<b>הוא</b>: שם: מאין ליש הוא."],["41","41","<b>המל'</b>: שם: מלכות."],["42","42","<b>אין מלך בלי עם</b>: ראה שער היחוה\"א פ\"ז ובמ\"מ הגהות והע\"ק שם. בחיי וישב לח, ל. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["43","43","<b>בלי</b>: בלקו\"ת שם: בלא."],["44","44","<b>שנה</b>: בלקו\"ת ניתוסף: כו'."],["45","45","<b>החופה</b>: בלקו\"ת: שהוא בחי' נעל החופה."],["46","46","<b>מל'</b>: שם ניתוסף: הנ\"ל."],["47","47","<b>מוגבל כמו</b>: שם: ליתא."],["48","48","<b>שער השמות</b>: בסה\"מ תרכ\"ז כאן ע' צו מציין: פי\"ג (ובתרכ\"ח ע' קמה ניתוסף תיבת: פ' ולא צויין מקומו). ושם (השם התשיעי בסופו) צויין: בשער אבי\"ע פד\"ה (המובא בסמוך בפנים)."],["49","49","<b>ובשער י\"ז הוא שער אבי\"ע</b>: וכ\"ה גם בסה\"מ תרכ\"ז שם. תרכ\"ח שם. לפנינו שער אבי\"ע הוא שער ט\"ז."],["50","50","<b>דאם</b>: כ\"ה בכ\"מ ומהם — לקמן פ\"ז. המשך כי תשא רפ\"ד ובריש הקיצור שם. פי\"א. ספי\"ד (ב\"פ). ועוד."],["51","51","<b>בד\"ה וככה תאכלו באריכות</b>: תרל\"ז ראה שם פ' עו — עח. לקמן המשך חייב אדם לברך פל\"ב על יד הערה 1270."],["52","*52","<b>בל\"א</b>: בלשון אידיש. ראה שיחת ליל הושע\"ר תשנ\"ב אות ג (שיחות קודש ע' 165 ואילך). ליל שמח\"ת קודם הקפות תשנ\"ב — סה\"ש תשנ\"ב ח\"א ע' 38 בשולי הגליון להערה 20. לקו\"ש משפטים כרך כא ע' 448 הערה 15."]]],[2000450057,"כח הגבול שבא\"ס שאינו בערך כלל בחי' גבול הנברא, רק מפני שמ\"מ ה\"ז בערך הא\"ס לגבול יחשב לכן מועיל כיסוי בחי' נעל שהוא המלאך סנד\"ל, דאל\"כ למה צריכי' שבחי' איהו יתייחד עם גרמוהי בכדי לברוא בהם וע\"י בחי' יש מאין התהוות הנבראי' ולמה לא די בכיסוי הנ\"ל לבד אלא שכיסוי הנ\"ל אינו פועל שיוכל להיות בחי' גבול ממש מהלך ת\"ק שנה כ\"א שבבחי' מדותיו שנק' בשם מדה ע\"ש שבערך הא\"ס הם בחי' גבול לכן שייך שבחי' כיסוי הנעל יפעול שיהי' נמשך בחי' הגבול דשמי' הגשמי' שעובים מהלך ת\"ק שנה<sup data-n=\"53\">52</sup> וכן בין כל רקיע ורקיע כו'.\n<b>וביאור</b> הענין דהנה מ\"ש העה\"ק שגבול הנמצא ממנו תחילה זהו בחי' הכלים הוא לפי שהם מגבילי' שזה חכ' וזה חסד, אמנם עצם בחי' החסד יכול להתפשט בלי גבול ממש, כי בחי' גבול הזה הוא בחי' הגבול שבא\"ס שבהכרח שיש בבחי' גבול זה גם כח הא\"ס ג\"כ, והיינו שא\"ס להתפשטותו, ולא הונח עליו שם גבול אלא מה שהוא מגביל שזה חסד ולא גבורה, וזה גבורה ולא חסד, אמנם התפשטות בחי' החסד הי' יכול להתפשט בלי גבול. וכן משמע מל' רבינו ז\"ל בד\"ה מה יפו פעמייך הנ\"ל וז\"ל אך עכ\"ז הי' יכול העולם להתפשט<sup data-n=\"54\">53</sup> בלי גבול וקץ, והיינו שגם מבחי' המל' הי' יכול להתפשט בלי גבול וקץ, לפי שבחי' המל' היא ממדותיו ית' שאין קץ להתפשטותן, ולא הונח עליהם ש' הגבלה כ\"א במה שמגבילי' להיות זה חסד וזה גבורה, עד שגם בענין בחי' אחליפו דוכתי'<sup data-n=\"55\">54</sup> אור החסד בכלי הגבורה, ואור הגבורה בכלי החסד, ועכ\"ז לא זזו ממקומן להיות זה חסד וזה גבורה כו', אלא שלפ\"ז צ\"ל שגם באור יש הגבלה זה חסד וזה גבורה, וכאן נת' שהאור שוה בכולן כנ\"ל. ואמנם בענין הגבלת בחי' הכלים זהו הגבלתן לבד, אמנם התפשטותן יכול להיות בלי גבול ממש, ולכן צריכי' לנעל הוא המלאך סנד\"ל כו'. ומ\"ש במ\"א בענין ההפרש בין אהבה דאברהם שהיא בחי' אהבת עולם לאהבה דאהרן<sup data-n=\"56\">55</sup>, שאהבה דאהרן היא בחי' אה\"ר שלמעלה מבחי' מקום וזמן, משא\"כ אהבה דאברהם היא בחי' אהבת עולם, ואברהם הי' מרכבה למדת החסד<sup data-n=\"57\">56</sup> דאצי', מזה אין שום סתירה למ\"ש כאן, ששם הכוונה שאהבה זו נלקחת מהתבוננות העולמות שבהם שייך בחי' אחד כמ\"ש בלק\"ת בד\"ה בהעלותך",[["53","52","<b>דשמי'. . ת\"ק שנה</b>: ראה חגיגה יג, א."],["54","53","<b>יכול. . להתפשט</b>: בלקו\"ת שם: העולם מתפשט."],["55","54","<b>אחליפו דוכתי'</b>: מובא בשם ע\"ח שער מטול\"ט. ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. ע' תשכג. תקס\"ה ח\"א ע' ח. תקס\"ו ע' יב. ענינים ע' סב ובהנסמן במ\"מ לשם. נזכר באג\"ק מכ\"ק אדמו\"ר מהורש\"ב ח\"א ע' קא."],["56","55","<b>ההפרש בין אהבה דאברהם. . דאהרן</b>: ראה ד\"ה ועשית בגדי קודש בתו\"א תצוה פב, א ואילך. מאמרי אדה\"ז תקס\"ה ח\"א ע' דש ואילך. מאמרי אדה\"א שמות ח\"ב ס\"ע שלח ואילך."],["57","56","<b>ואברהם. . החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."]]],[2000450058,"דרוש הראשון<sup data-n=\"58\">57</sup>, אמנם עצם התפשטות בחי' החסד דאצי' יכול להתפשט בלי גבול, ולכן בכדי שיתהוה בחי' הגבול דמדה ת\"ק שנה ולא יותר זהו ע\"י שהנעל חופה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שזהו לפי מ\"ש רבינו בדרוש זה וכן בד\"ה מה יפו פעמי' בלק\"ת, וענין הגבלת המדות הוא שזה חסד וזה גבורה, ומ\"מ א\"ס להתפשטותן לכן צריכי' לנעל החופה כו'.</span>",[["58","57","<b>בלק\"ת. . הראשון</b>: ראה גם מאמרי אדה\"א במדבר ח\"ג ע' תתפד ואילך."]]],[2000450059,"<h3>גדול אדונינו כו' שיעור קומה כו'</h3>\nד) <b>וביאור</b> הענין דהנה כתי' גדול אדונינו ורב כח<sup data-n=\"59\">58</sup>, ולתבונתו<sup data-n=\"60\">59</sup> אין מספר, פי' ורב כח יובן ע\"פ מ\"ש בפרקי היכלות<sup data-n=\"61\">60</sup> ששיעור קומה של יוצר בראשית רל\"ו אלפים ריבוי רבבות פרסאות כחשבון גימ' ורב כח, וכ\"ה במק\"מ פ' בשלח דנ\"ו ע\"ב בשם נ\"ב שהוא מהרח\"ו ז\"ל<sup data-n=\"62\">61</sup> ובשם האוצ\"ח הובא במק\"מ שם רל\"ו אלפים רבבות<sup data-n=\"63\">62</sup> פרסאות, והפרסאות הם פרסאות שלמעלה<sup data-n=\"64\">*63</sup> כמ\"ש במק\"מ שם גם שיעורם, ומ\"מ הוא בחי' מספר רק שהוא מספר גדול, ופי' יוצר בראשית הוא בחי' ההארה המהוה כל התהוות הנבראי' שנבראו בששת ימי בראשית וכמ\"ש מזה ג\"כ בד\"ה אני לדודי (ך\"א<sup data-n=\"65\">63</sup> ) וא\"כ הרי גם שרש המהוה ומחי' בי\"ע הוא בבחי' מספר, והיינו כנ\"ל שבחי' הארת המל' שמתצמצם להיות שרש ומקור לבי\"ע הוא ג\"כ בבחי' מספר, ואפ\"ל אפי' הארת ז\"א שמאיר במל' לצורך התהוות העולמות הוא ג\"כ בבחי' מספר, שהרי ענין המדות שייכי' לנבראי'<sup data-n=\"66\">64</sup> כי א\"א לומר",[["59","58","<b>וביאור. . גדול אדונינו ורב כח</b>: תהלים קמז, ה. ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (ב' מההמשך) והוא ד\"ה: ד\"ה ”גדול אדונינו ורב כח\" (הכולל פרקים ד-ו). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש. וראה לקמן הנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב פ' בא.\nדרוש זה נזכר בסה\"מ תרמ\"ח ע' רכה בשולי היריעה. תר\"ן ע' רפז בשולי היריעה. ע' שיח. תרס\"ט ע' קנד."],["60","59","<b>ולתבונתו</b>: בתהלים שם: לתבונתו. אבל כ\"ה גם בזהר תרומה קעא, ב. בחיי דברים כב, ז. לקמן בקיצור לפ\"ה. רפ\"ז. המשך כי תשא על יד הערה 140. בין הערות 358-9. 208-209. ובחלק ההנחות בהנחה כאן על יד הערה 2. לקו\"ת ברכה צג, ד. סה\"מ תרכ\"ז כאן ע' צו. תרכ\"ח ע' קמה. תרכ\"ט ע' צז. מים רבים תרל\"ו פקפ\"ג ע' רו. אוה\"ת כאן ע' ריט. תשא ע' א'תתכג. ע' א'תתכד. ע' א'תתכט. מאמרי אדה\"א בראשית ע' עח. וש\"נ. תו\"ח בא ח\"א קיב, ג הערה 59."],["61","60","<b>בפרקי היכלות</b>: וכ\"ה לקמן בהנחה כאן על יד הערה 3. מובא גם בשם: ס' היכלות־ ס\"י־ במ\"ר — ראה הנסמן באוה\"ת ואתחנן כרך ו ע' ב'רלג. שערי אורה לו, ב הערה 48. מאמרי אדה\"א נ\"ך ע' רס. וראה גם אוה\"ת על ענינים ע' ערב ואילך."],["62","61","<b>רל\"ו אלפים ריבוי רבבות. . במק\"מ. . נ\"ב שהוא מהרח\"ו ז\"ל</b>: וכ\"ה בהגהות מהרח\"ו אות ג בזהר בשלח נו, ב."],["63","62","<b>ובשם האוצ\"ח. . רל\"ו אלפים רבבות</b>: וכ\"ה בע\"ח שמ\"ב [שער דרושי אבי\"ע), פ\"ב. וראה גם מאמרי אדה\"א דברים ח\"ג ע' תתיט בהערה. אוה\"ת ח\"ש ע' קז (ביאוה\"ז להצ\"צ כרך א ע' עא)."],["64","*63","<b>פרסאות שלמעלה</b>: ראה גם פרדס שער עצמות וכלים ש\"ד, ספ\"א."],["65","63","<b>ופי' יוצר בראשית. . אני לדודי (ך\"א)</b>: אוה\"ת שה\"ש כרך ב ע' תקנ. סה\"מ תרכ\"ו ס\"ע רכב ואילך. תר\"ל ע' רסז."],["66","64","<b>המדות שייכי' לנבראי'</b>: ראה אוצרות חיים בתחלתו. הובא בלקו\"ת מסעי צג, רע\"א. לקמן (בחלק ההנחות) הנחה ד\"ה ב\"ה אלקי ישראל ובהערה 20."]]],[2000450060,"היותו חסדן או רחמן כ\"א כשיש זולת על מי להתחסד או להתרחם, והגם כי מזה א\"א להכריח כ\"כ שהרי הזולת יקרא גם באצי' עצמו גבורה היא זולת החסד והת\"ת וכן כל הספירות, אמנם באמת ענין הרחמי' והחסדי' אינו נופל כ\"א על הנבראי' ולא על הנאצלי' שאינם שייכי' לזה כלל, ומקרא מלא דבר הכתוב זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"67\">65</sup>, שבחי' הרחמי' והחסדי' שייכי' לעולמות דוקא, ומ\"ש במ\"א שגם על עולמות עליוני' שייך בחי' רחמי'<sup data-n=\"68\">66</sup>, מאחר שנק' עולם יתכן עליו ענין הרחמי' והחסדי', וביאור ד\"ז יתכן לפרש בשני אופנים<sup data-n=\"69\">67</sup>, הא' שענין הארת ז\"א שמאיר במל' לצורך התהוות העולמות ענינו יובן ע\"פ מה שנודע שבחי' המל' נאצלה בסוד שרש רק נקודה<sup data-n=\"70\">68</sup> אחת לבדה, ובנקודה זו יש ב' דיעות אם הוא בחי' כתר מל' או בחי' מל' שבמל'<sup data-n=\"71\">69</sup>, אמנם לדעת שניהם נאצלה רק בחי' נקודה א' לבד, וכדי להיות בנין המל' בבחי' פרצוף שלם בע\"ס שאז ראוי' לקבל ולהתייחד עם ז\"א וכמ\"ש ויבן את הצלע<sup data-n=\"72\">70</sup> זהו ע\"י שמקבלת מכל הע\"ס שמבחי' מל' שבחכ'<sup data-n=\"73\">71</sup> נעשה חכ' שבמל', ומבחי' מל' דבינה נעשה בינה שבמל' וכן מכל המדות כו' וזהו לצורך בינינה<sup data-n=\"74\">72</sup> עצמה, וזהו שרש ענין ט' תקיעות<sup data-n=\"75\">73</sup> וט' ברכות<sup data-n=\"76\">74</sup> דר\"ה שהם בכדי לעשות בנין המל', וא\"כ בהארתה שמאיר מבחי' המל' להוות התהוות הנבראי' דבי\"ע זהו ע\"י הארת המדות בה לצורך בינינה שתהי' בבחי' פרצוף שלם להוות הנבראי' דבי\"ע, והב' י\"ל בעומק יותר שענין הארת המדות שמאירי' במל' זהו ע\"י בחי' היחוד שאח\"כ אחר היותה לפרצוף שלם בפ\"ע, ע\"ד שכל אור הלבנה הוא ממה שמתייחדת עם השמש ומקבלת אור מהשמש, וה\"ז קרוב למשנת\"ל שגם הארת בחי' איהו שמתייחד עם גרמוהי מאחר שעובר דרך בחי' גרמוהי גם בו שייך בחי' מספר כו', אבל לתבונתו אין מספר, פי' תבונה הוא",[["67","65","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]. ראה גם המשך וככה תרל\"ז פכ\"ח."],["68","66","<b>על עולמות עליוני'. . רחמי'</b>: ראה מאמרי אדה\"א דברים ח\"א ע' צג. וש\"נ. תו\"ח בשלח ח\"א קעא, ב ואילך. רלה, ד ואילך. המשך מים רבים תרל\"ו פנ\"א ע' נח."],["69","67","<b>בשני אופנים</b>: מכאן עד התיבות ”שלם בפ\"ע\" נעתק בסה\"מ תרנ\"ט ע' צב בשינויים והוספות."],["70","68","<b>המל' נאצלה. . נקודה</b>: ראה ע\"ח (שער מיעוט הירח) של\"ו, פ\"א. פ\"ב. לקו\"ת צו יא, ב. לקמן (בחלק ההנחות) הנחה ד\"ה שיר המעלות ממעמקים על יד הערה 36."],["71","69","<b>המל'. . נקודה. . כתר מל' או בחי' מל' שבמל'</b>: בסה\"מ תרנ\"ט כאן ע' צב מציין: ”ועמ\"ש בפע\"ח ובשעה\"כ שער העמידה בכוונת ברכת דולמלשינים\". ראה גם סה\"מ תרכ\"ו ס\"ע כד."],["72","70","<b>ויבן את הצלע</b>: בראשית ב, כב בדילוג השמות."],["73","71","<b>שמבחי' מל' שבחכ'</b>: וכ\"ה לקמן בחלק ההנחות בההנחה כאן על יד הערה 13. בסה\"מ תרנ\"ט כאן: מל' דז\"א שבחכמה — ראה ע\"ח שער מיעוט הירח (של\"ו, פ\"א). מאמרי אדה\"א ויקרא ח\"ב ע' תשצה. שעה\"י קמא, ב ובהערה 41. תו\"ח יתרו ח\"ב רסח, ג."],["74","72","<b>בינינה</b>: ב: בנינה."],["75","73","<b>ט' תקיעות</b>: ראה ר\"ה לג, ב (במשנה). שו\"ע אדה\"ז הל' ר\"ה סתק\"צ, ס\"א. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 11. ד\"ה שיר המעלות ממעמקים על יד הערה 37."],["76","74","<b>וט' ברכות</b>: ראה רמב\"ם הל' תפלה פ\"ב, ה\"ו. שו\"ע אדה\"ז שם סתקצ\"א, ס\"א. ד\"ה שיר המעלות שם על יד הערה 38."]]],[2000450061,"בן ובת<sup data-n=\"77\">75</sup>, והיינו בחי' ז\"א ומל' כמו שהם באצי' ואינם בחי' מקור כלל לבי\"ע אינם בגדר מספר כלל.\n<span data-k=\"ks\"><b>קיצור.</b> שיעור קומה של יוצר בראשית רל\"ו כו' א\"כ ה\"ז כמשנ\"ל שההארה המהוה בי\"ע היא ג\"כ בבחי' מספר, ואפ\"ל גם הארת המדות שלצורך בנינה ואפשר גם מה שלצורך יחודה שייך ג\"כ מספר, אבל תבונה בן ובת ז\"א ומל' כמ\"ש באצי' הם בלי מספר.</span>\nה) <b>וביאור</b> ד\"ז אפשר לבאר בשני אופנים, הא' ע\"פ מ\"ש בזהר\"ק<sup data-n=\"78\">76</sup> על מאמר כשושנה בין החוחי' ר\"פ בראשית<sup data-n=\"79\">78</sup>, שיש ב' בחי' במל' הא' היא בחי' חיצוני' המל', והב' היא בחי' פנימיות המל'. שבחי' חיצוני' המל' דהיינו מה שיורדת לבי\"ע להחיותן ז\"ע שושנה בין החוחי', ובחי' פנימיות המל' שאינה יורדת כלל היא בחי' רעייתי<sup data-n=\"80\">77</sup>, ויובן זה<sup data-n=\"81\">*79</sup> ע\"פ מ\"ש במ\"ח דפי' כנס\"י הגם שמתייחס לספי' המל', אינה בחי' המל' הנעשית פרצוף בפ\"ע, אלא שהוא בחי' פרצוף המל' שבתוך פנימיות דז\"א<sup data-n=\"82\">79</sup> ושם הם שוים כי היא גדולה כמוהו ממש כו', וז\"ע כלת משה, וע' בסה\"מ סי' קנ\"ו, וביאור הענין הנה נודע שכל ההשתלשלות הם פנימיות וחיצוני', וגם בי\"ס יש פנימיות וחיצוני', כמו בבחי' חכ' שיש בה פנימיות והוא עד\"מ עומק ותוכן המושכל שהוא למעלה מהתלבשות באותיות המחשבה ודבור וכמ\"ש במ\"א*, ויש בה חיצוני' והוא הארת השכל שמלובש במח' ודבור, וכן במדות חסד וגבורה שפנימיותם הוא בחי' עומק ותעלומות ההתפעלות שבבחי' חסד או גבורה שאינו יוכל להיות נגבל ולהתלבש<sup data-n=\"e2\">*</sup>",[["77","75","<b>תבונה הוא בן ובת</b>: ראה זהר (אד\"ז) האזינו רצ, ב. רצא, א. תניא פט\"ז ובמ\"מ הגהות והע\"ק לשם. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרכג. פרשיות התורה ח\"א ע' לג. שעה\"י קי, ב. תו\"ח בראשית כח, ד ובהערה 26."],["78","76","<b>בזהר\"ק</b>: בזהר הרקיע [שער מאמרי רשב\"י ט, א]."],["79","78","<b>ר\"פ בראשית</b>: על מאמר הראשון שבהקדמת הזהר א, א. בזהר\"ק ”שכינתא עילאה שכינתא תתאה\" — ראה ביאוה\"ז להצ\"צ כרך ב ע' תקפו (פ\"ב) וע' תקפח (פ\"ד). לקו\"ת שה\"ש שבהערה הבאה."],["80","77","<b>כשושנה בין החוחי'. . רעייתי</b>: שה\"ש ב, ב."],["81","*79","<b>ויובן זה</b>: להבא לקמן עד התיבות עמקותו כו' הוא לשון הלקו\"ת שה\"ש לט, סע\"ג ואילך בשינויים והוספות."],["82","79","<b>במ\"ח דפי' כנס\"י. . פרצוף המל'. . דז\"א</b>: בלקו\"ת סוכות פב, ג מציין: ”מסכת אורות ז\"א פ\"ג משנה ז' ובפנימיותו\". וראה הוספות להערות וציונים ללקו\"ת שם מ, א."],["e2","*","<b>בגוכתי\"ק נרשם הבא להלן בפנים וממעל לשורה נרשם</b>: (מן וע' עד יכפר אצ\"ל)\nוע' בביאור ע\"פ והניף הכהן אותם בסופו<sup data-n=\"4706\">80</sup>, ובד\"ה הנה ים סוף שהוא דרוש והניף יד<sup data-n=\"4707\">81</sup>ו, ובביאור ע\"פ כי ביום הזה יכפר<sup data-n=\"4708\">82</sup>"],["4706","80","<b>בביאור ע\"פ והניף. . בסופו</b>: לקו\"ת אמור לט, סע\"ג."],["4707","81","<b>והניף ידו</b>: לקו\"ת צו טז, ד."],["4708","82","<b>כי ביום הזה יכפר</b>: לקו\"ת אחרי כח, ד. צויין אליו בלקו\"ת צו שם."]]],[2000450062,"באותיות הדבור, וכנודע שבעת גילוי תוקף המדה א\"י לדבר כלל מתוקף התפעלות המדה שהיא בחי' הפנימיות, וחיצוניותם הוא הארת המדה המתלבשת בדבור שיפרשנה לזולתו כו', ועד\"ז הוא בכל ההשתלשלות, והנה ידוע שבהשתלשלות עו\"ע<sup data-n=\"83\">83</sup> נעשה מחיצוני' העילה בחי' פנימיות בהעלול<sup data-n=\"84\">84</sup> כי הפנימיות של העילה א\"א להעלול לקבל אותה כלל מאחר שהוא רחוק בערך המעלה והמדריגה, וא\"כ הרי בחי' חכ' שהיא ראשית הנאצלים והתחלת ההשתלשלות דאצי' כי מהחכ' נמשכה הבינה, ומבינה נמשכו המדות כו', מעולם לא נמשכה ממנה רק החיצוני', אבל הפנימיות הוא למעלה מהשתלשלות ואינו מתלבש בבינה עד\"מ מהתלבשות השכל בהשגה שהחיצוני' לבד נתלבש ולא עמקותו כו'*, ועד\"ז יובן שמה שנמשך מבחי' המל' להוות בי\"ע זהו רק מבחי' פרצוף המל' שהוא בחי' חיצוני' המל', אבל בחי' פנימיות המל' הוא למעלה ממקור המהוה בי\"ע בחי' כלת משה שזהו בלי מספר כו'.\n<b>וביאור</b> הענין דהנה בע\"מ נברה\"ע<sup data-n=\"85\">85</sup> שהם המאמרות יהי אור יהי רקיע<sup data-n=\"86\">86</sup> הנה מלבד מה שהדבור<sup data-n=\"87\">87</sup> הוא מעלים ומכסה על אור ההמשכה כמו עד\"מ באדם הנה אותיות הדבור הם כלים להשכל ומדות<sup data-n=\"88\">88</sup> שהם נמשכים ומתלבשים בו, אך מ\"מ האותיות הם מעלימים שבתוכן<sup data-n=\"89\">89</sup> ומצפינים אותו בתוכן שהרי הקטן אף שמבין כל האותיות והתיבות ואומרן היטיב, עכ\"ז אינו מבין כלל ההשכלה שבתוך האותיות, רק מי שהוא חכם עצמו<sup data-n=\"90\">90</sup> מקודם אזי מבין מתוך האותיות כו' אבל מהות האותיות עצמן הוא בחי' העלם לגבי מהות השכל והמדות, ולכן למעלה שהתהוות החכ' דבי\"ע הוא רק מן הדבור עליון ולא כמו במשל שלומד<sup data-n=\"91\">91</sup> הוא חכם מקודם, שבענין הבריאה בחי' התהוות חכ' דבריאה לא הי' כלל מקודם מאומה<sup data-n=\"92\">92</sup>, הרי א\"כ הדבור והאותיות דמל' דאצי' הם מעלימי' ומצפינים על החב\"ד והמדות דאצי' המתלבשים בהדבור שלא יתגלה כלל בבריאה, כ\"א איזה הארה מועטת מאד כמו בחי' האור הנמשך ע\"י שערות כו', ומלבד זה מה שהדבור מעלים הנה כל ההמשכה שנמשך מהשכל ומתלבש בהדבור זהו רק חיצוני' השכל, אבל פנימיות השכל א\"א להתגלות כלל באותיות ודבור כו'<sup data-n=\"93\">93</sup>, כי הנה עד\"מ<sup data-n=\"94\">94</sup> האותיות המלבישים את השכל שאע\"פ שע\"י האותיות מתגלה השכל שהרב מסביר לתלמידו השכל ע\"י האותיות היינו פשוטו של השכל, אבל פנימיות",[["83","83","<b>עו\"ע</b>: בלקו\"ת ברכה צה, ב: הנזכר בספרים. שה\"ש א, ב: כמ\"ש בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["84","84","<b>מחיצוני' העילה בחי' פנימיות בהעלול</b>: ראה לקו\"ת שלח מא, ד. וש\"נ. שעה\"י קכד, א ובהערה 3."],["85","85","<b>בע\"מ נבה\"ע</b>: אבות רפ\"ה."],["86","86","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["87","87","<b>שהדבור. . ע\"י שערות</b>: לשון לקו\"ת צו שם בשינויים קלים והוספה."],["88","88","<b>ומדות</b>: בלקו\"ת שם: והמדות."],["89","89","<b>שבתוכן</b>: בלקו\"ת שם: על השכל שבתוכן."],["90","90","<b>חכם עצמו</b>: שם: עצמו חכם."],["91","91","<b>שלומד</b>: שם: שהלומד."],["92","92","<b>שבענין. . מאומה</b>: כל זה ליתא שם."],["93","93","<b>שנמשך. . כו'</b>: לשון הלקו\"ת שם."],["94","94","<b>עד\"מ. . מוסתר ונעלם</b>: לשון הלקו\"ת אחרי שם בשינויים קלים והוספה."]]],[2000450063,"ועומק השכל אינו מתגלה ממש בהאותיות כ\"א מוסתר ונעלם בהם בבחי' הסתר והעלם, ולכן ארז\"ל דלא קאים אינש אדעתי' דרבי'<sup data-n=\"95\">95</sup> עד ארבעים שנין והיינו מפני שעומק השכל של השפעת הרב הי' עדיין בבחי' הסתר והעלם ממנו, אלא שאעפ\"כ לאחר ארבעים שנין קאים לפי שמ\"מ הי' דעתי' דרביה בבחי' מקיף עליו שמוסתר ומלובש בתוך האותיות שקיבל מרבו בבחי' הסתר והעלם, ואחר מ' שנין נמשך מהעלם אל הגילוי, נמצא מובן<sup data-n=\"96\">96</sup> שהאותיות שהם לבושי' היינו שמסתירי' שהפנימיות לא יתגלה רק החיצוני' נמשך ומתגלה, ומ\"מ בהעלם יש בהם גם הפנימיות, מפני כי החיצוני' שמאיר בהם מוכרח להיות חיצונית מן בחי' הפנימיות, ולכן לאחר מ' שנין קאים<sup data-n=\"97\">97</sup>, ויובן זה עוד מענין<sup data-n=\"98\">98</sup> מארז\"ל בסנהדרין דל\"ה הטעם שאין דנין בע\"ש וגומרים באחד בשבת משום דמנשי טעמייהו, ואע\"ג דשני סופרי הדיינים עומדים לפניהם וכותבי' דברי המזכים ודברי המחייבין, פי' רש\"י דמ\"מ לבא דאינשי לא כתבי כו' ונשכח מלבו ישובו לטעמי'<sup data-n=\"99\">99</sup> כו' והיינו מפני<sup data-n=\"100\">100</sup> שפנימיות הסברא אינו מתגלה כלל מתוך האותיות כ\"א מוסתר ונעלם, והענין הוא דהנה בהשגת השכל יש ב' בחי' הא' מה שיכול לפרש ולהביא השכל בדבור או בכתב, הב'<sup data-n=\"101\">102</sup> הוא עצם השכל ועומק המושג מה שאינו יכול להסביר כלל בדבור, ויובן זה<sup data-n=\"102\">103</sup> ע\"ד מ\"ש בפע\"ח שעט\"ז פ\"א שהשיג האריז\"ל בשעת השינה בשבת רזין עילאין מה שלא יספיק לדרוש זה בשמונים שנה<sup data-n=\"103\">101</sup>, והיינו לפי שהשגתו הי' בבחי' ראי' עצם החכ', ולא בבחי' שמיעה והבנה ולכן במעט רגע יוכל להשיג ולראות מה שיצטרך זמן רב לפרש בדבור כו', וכעין זה עד\"מ הוא לחכימא ברמיזא<sup data-n=\"104\">105</sup> שא\"צ לזה הקדמת דברים והסבר כ\"א ע\"י הרמיזה משיג עצם השכל ושרשו, ועד\"ז הוא ענין הטעמי' והנגינות שבתושב\"כ שהם כמו רמיזות עד\"מ שעי\"ז מתגלה אפס קצה מח\"ע מה שלא יוכל לבוא ולהתגלות באותיות התורה דהיינו מה שא\"א להתגלות בדבור, שמה שנמשך בדבור ואותיות זהו רק חיצוני' ח\"ע נובלות חכמה שלמעלה תורה<sup data-n=\"105\">106</sup> זהו המתגלה באותיות התורה<sup data-n=\"106\">107</sup>, אבל הגילוי מפנימי' ועצמיות ח\"ע א\"א להתגלות בדבור ואותיות",[["95","95","<b>דלא קאים אינש אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. תו\"ח בשלח ח\"א ריז, ג הערה 418. המשך וככה תרל\"ז ספל\"ה."],["96","96","<b>מובן</b>: בלקו\"ת שם: מובן מזה."],["97","97","<b>ומ\"מ בהעלם. . קאים</b>: כ\"ז ליתא בלקו\"ת."],["98","98","<b>מענין</b>: שם: ג\"כ מענין."],["99","99","<b>לטעמי'</b>: שם: לטעמו."],["100","100","<b>מפני</b>: שם: לפי."],["101","102","<b>הב'</b>: שם: והבחי' הב'."],["102","103","<b>ויובן זה</b>: שם יש עוד שורה ואח\"כ כותב ויובן יותר."],["103","101","<b>בהשגת. . שנה כו'</b>: לשון הלקו\"ת אמור שם בשינויים קלים והוספות."],["104","105","<b>לחכימא ברמיזא</b>: ראה מדרש משלי כב, טו. מאמרי אדה\"א שמות ח\"א ע' סט. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנב. לקמן ד\"ה על חומותיך על יד הערה 34."],["105","106","<b>נובלות חכמה שלמעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["106","107","<b>תורה. . התורה</b>: כ\"ז ליתא בלקו\"ת."]]],[2000450064,"וכענין מעשה דהאריז\"ל הנ\"ל שלא יספיק דבור שמונים שנה כו'<sup data-n=\"107\">104</sup>, ונמצא כי מה שמתגלה בע\"מ זהו רק בחי' חיצוני' המל' כו', אבל בחי' פנימיות המל' כלת משה א\"א להתגלות בדבור, וה\"ז בלי מספר כו'.\n<b>הב'</b> יכולי' להבין ד\"ז ממ\"ש במ\"א שיש ב' בחי' במל' ונק' ים ויבשה<sup data-n=\"108\">108</sup>, יבשה זהו מה שנעשה מקור לבי\"ע, אבל בחי' ים זהו למעלה ממקור המהוה בי\"ע, ונק' ים סוף סופא דכ\"ד דאצי', גם פי' ים ע\"ש שמעלים אורות דאצי' בתוכו ע\"ד כמו הים שמכסה על הנבראי' שבו ובחי' זו דמל' אינו שייך בחי' מספר כלל. ומ\"מ י\"ל ששני הדרכים ענין אחד הם שהרי בד\"ה והניף ידו בלק\"ת<sup data-n=\"109\">109</sup> פי' שענין קרי\"ס שלא יסתיר הדבור עליון על האורות העליוני' שבו, שי\"ל גם על בחי' אורות הנעלמי' ז\"ע שמים נעשה יבשה, ועד\"ז יובן בבחי' המדות שכל ענין מה שהמדות הם מקור לעולמות זהו מפני היותם מוגבל זה חסד וזה גבורה שנת\"ל שזהו מצד הכלים לבד שהם בחי' חיצוני' בכלל ועל כלליות ההתהוות שנמשך מבחי' המדות נת' במ\"א שע\"ז נא' כי הוא ציוה ונבראו<sup data-n=\"110\">110</sup> מאיליו וממילא ולא בבחי' כח הפועל בנפעל, שזה קאי על ש' הוי' דז\"א שמאיר דרך הכלים להיות ההתהוות ממילא ומאיליו וכבר נת\"ל שכל המשכה הוא רק חיצוני' לבד, אמנם בבחי' פנימיותם אינו שייך כלל בחי' מספר, וכמשנת\"ל שגם מצד הכלים שמגבילי' שזה חסד וזה גבורה עכ\"ז יכול להיות התפשטות החסד בלי גבול ממש כו', ולכן תבונה בן ז\"א ובת מל' כלת משה כמו שהם באצי' הם בלי מספר.\n<span data-k=\"ks\"><b>קיצור.</b> בבחי' פרצוף המל' יש ב' בחי' פנימיות וחיצוני', והתהוות בי\"ע זהו רק מבחי' חיצוני' לבד, וכ\"ש מז\"א אבל פנימיותם הם בלי מספר וזהו ולתבונתו אין מספר.</span>\nוא\"ו) <b>ועפ\"ז</b> יובן מאמר הזהר הנ\"ל בענין הדודאים שהיחוד הוא ע\"י המלאך וכמ\"ש במק\"מ בשם האריז\"ל<sup data-n=\"111\">111</sup>, כמו שכדי שיתהוה העולם ליש ודבר מוגבל מן הארץ לרקיע מהלך ת\"ק שנה דוקא זהו ע\"י הנעל כנ\"ל שהוא ע\"י מלאך כו' כמ\"ש בלקו\"ת בד\"ה מה יפו פעמייך הנ\"ל, כן הוא בענין הדודאים כו', ועפ\"ז יובן ג\"כ מה שמפרשי' לפעמי' מט\"ט על בחי' מל'<sup data-n=\"112\">112</sup>, ולכאו' הלא הוא מלאך",[["107","104","<b>האריז\"ל. . בשמונים שנה</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשס הובא לקמן במאמר ד\"ה פי' פתחה בחכמה על יד הערה 81 ושם: בס' שנים. שער האמונה צג, א הערה 9. צג, ב הערה 12. תו\"ח בא ח\"א קג, א הערה 298. אוה\"ת ויקהל ע' ב'קכו: ס' או ע' שנה."],["108","108","<b>ב' בחי' במל' ונק' ים ויבשה</b>: ראה גם לקו\"ת צו יד, ב. מאמרי אדה\"ז תק\"ע ע' ע' וע' עו. מאמר ד\"ה ואתה הרם את מטך תקס\"ג בתו\"ח בשלח ח\"א קלט, ב. אוה\"ת בשלח ע' תקסט. המשך והחרים תרל\"א ע' מ ואילך. סה\"מ תרל\"ה ח\"א ע' רנט."],["109","109","<b>והניף ידו בלק\"ת</b>: צו טז, ד."],["110","110","<b>כי הוא ציוה ונבראו</b>: תהלים קמח, ה. ראה לקו\"ת שה\"ש יד, ג. בונה ירושלים סנ\"ג (ע' נח). מאמרי אדה\"ז אתהלך לאזניא ע' קיח. סה\"מ תרל\"ב ח\"ב ע' שפד. תרל\"ג ח\"א ע' כב. תרכ\"ז ע' קעה. ס\"ע שנט ואילך ובהנסמן בהנ\"ל. לקמן המשך חייב אדם לברך פ\"ד על יד הערה 101."],["111","111","<b>הדודאים. . במק\"מ בשם האריז\"ל</b>: ראה לעיל בפנים רפ\"ג."],["112","112","<b>מט\"ט על בחי' מל'</b>: ראה גם אוה\"ת משפטים ע' א'קצו ואילך. תהלים (יהל אור) ע' קמב."]]],[2000450065,"נברא<sup data-n=\"113\">113</sup>, אלא שיש הפרש בין מט\"ט ובין כשמחברי' יו\"ד במט\"ט שאז רומז על בחי' המל', ואפ\"ל שכאשר הארת ז\"א ומל' דאצי' נמשך להיות מזה התהוות בי\"ע שגם בההארה זו שייך בחי' מספר, לכן יכולה הארה זו להתלבש במלאך מט\"ט בחי' שרו ש\"ע<sup data-n=\"114\">114</sup> שאז הוא מט\"ט ביו\"ד מיט\"ט, ע\"ש הארת המל' שמאיר בו ועש\"ז מפרשים מט\"ט מל', וע' בד\"ה מה יפו פעמי' בנעלי' שלא נדפס<sup data-n=\"115\">115</sup> ובהגהות לשם בספר תרי\"ט<sup data-n=\"116\">116</sup> ובד\"ה קול מצהלות חתנים<sup data-n=\"117\">117</sup> מחופתם בענין נערי' ממשתה נגינתם.\n<b>אך</b> הנה על שיטה זו קשה מהמד\"ר פ' בראשית פ\"א<sup data-n=\"118\">118</sup> בענין המלאכי' שאפלגו אם נבראו בשני או בחמישי, ר' לולינא בר טברין אמר בשם ר' יצחק בין ע\"ד דר\"ח ובין<sup data-n=\"119\">119</sup> ע\"ד דר\"י הכל מודי' שלא נברא ביום ראשון כלום שלא יאמרו מיכאל<sup data-n=\"120\">120</sup> מותח בדרומו כו' שנא'<sup data-n=\"121\">121</sup> אנכי ה' עושה כל כו' מאתי מי אתי<sup data-n=\"122\">122</sup> כתי' מי הי' איתי שותף במע\"ב<sup data-n=\"123\">123</sup>, ולפ\"ז האיך יתפרש דרוש דמה יפו הנ\"ל, אך באמת הוא לפי פי' הזהר והאריז\"ל בענין הדודאים, ודיעות חלוקות הם, וליישב פסוק מי אתי מי הי' שותף י\"ל שגם הנעל הנ\"ל הוא ית' בראו א\"כ מי אתי שאינו שייך כלל לקרותו שותף, וכמו האומן שעושה כלי שע\"י כלי זו יצא מלאכתו שרצונו לעשות האם נא' שהכלי שותף עמו, ובאמת ב' דיעות הם.\n<span data-k=\"ks\"><b>קיצור.</b> יתורץ ענין הדודאי', וענין מט\"ט מל', ושבמד\"ר הוא שיטה אחרת, ומ\"מ לא יקשה על פי' רבינו ז\"ל ע\"פ הזהר והאריז\"ל.</span>",[["113","113","<b>מט\"ט. . מלאך נברא</b>: ראה בהערה הבאה."],["114","114","<b>מט\"ט בחי' שרו ש\"ע</b>: ראה יבמות טז, ב ובתוס' שם. מאמרי אדה\"א ויקרא ח\"ב ע' תתעא. במדבר ח\"ב ע' תשצ. דברים ח\"ג ע' תשצד."],["115","115","<b>מה יפו. . שלא נדפס</b>: בלקו\"ת. ונדפס במאמרי אדה\"ז תקס\"ג ח\"א ע' רנא נוסח א (הנחת כ\"ק אדמו\"ר האמצעי) ונוסחא שני' (שם הנחת הר\"מ בן כ\"ק אדה\"ז)."],["116","116","<b>ובהגהות לשם בספר תרי\"ט</b>: נדפס באוה\"ת שה\"ש ח\"ב ע' תקצה."],["117","117","<b>קול מצהלות חתנים</b>: בסה\"מ תרכ\"ז ע' צז־ תרכ\"ח ע' קמו ניתוסף: ”דתרי\"ד. וצ\"ע\" — הנחת כ\"ק אדמו\"ר מהר\"ש נדפסה בס' מאמרי אדמו\"ר הצ\"צ תרי\"ד ע' כד ואילך. מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרכב ואילך. ובהגהות וכו' לשם מכ\"ק אדמו\"ר הצ\"צ ע' תשל ואילך [נדפסו גם באוה\"ת סידור ע' רצו ואילך]. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרט ואילך."],["118","118","<b>מהמד\"ר פ' בראשית פ\"א</b>: ס\"ג (בשינויים קלים כדלהלן). ועד\"ז בסה\"מ תרכ\"ז ותרכ\"ח. תרל\"ב ח\"א ע' רג. וראה גם לקמן (בחלק ההנחות) מאמר ד\"ה כי המצוה על יד הערה 57."],["119","119","<b>ובין</b>: בב\"ר שם: בין."],["120","120","<b>מיכאל</b>: תוקן ע\"פ ב."],["121","121","<b>שנא'</b>: שם: אלא."],["122","122","<b>אנכי. . מי אתי</b>: ישעי' מד, כד."],["123","123","<b>איתי שותף במע\"ב</b>: שם: שותף עמי בברייתו של עולם. ראה לקמן מאמר ד\"ה להבין וכו' כי המצוה על יד הערה 59. ובחלק ההנחות שם ובהערה 13."]]],[2000450066,"<h3>אז ישיר כו' לתבונתו אין מספר כו'</h3>\nז) <b>ואמנם</b><sup data-n=\"124\">124</sup> יש עוד פי' בענין ולתבונתו אין מספר על בחי' בינה, דהנה מה שנת\"ל זהו לפי' רבינו ז\"ל באה\"ק סי' ך' ד\"ה איהו וחיוהי חד שחיוהי הם האורות, וגרמוהי הם הכלים די\"ס דאצי' שהם בבחי' גבול עכ\"פ שזה חכ' וזה",[["124","124","<b>ואמנם</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (ג' מההמשך) והוא ד\"ה: ”אז ישיר משה ובנ\"י\" (הכולל פרקים ז — יו\"ד). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש."]]],[2000450067,"חסד כו' ומ\"מ א\"ס להתפשטותם כנ\"ל, אמנם בכתבי האריז\"ל נת' חיוהי הוא בחי' חב\"ד האורות והכלים, וגרמוהי הם בחי' זו\"נ<sup data-n=\"125\">125</sup> האורות והכלים שלפי פי' זה יתבאר היטיב ענין אחליפו דוכתייהו אור החסד בכלי הגבורה מאחר שמפרש גרמוהי גם על אור המדות שזה חסד וזה גבורה, וביאור הענין הוא כנ\"ל שענין המדות הוא השפעה לזולתו דוקא וכנ\"ל בענין חסדן או רחמן שא\"א כ\"א כשיש על מי להתחסד או להתרחם, משא\"כ בבחי' חכ' שיכול לישב ולהשכיל השכלות, וכענין רשב\"י שניתוסף לו חכ' הרבה כמארז\"ל בענין רפב\"י<sup data-n=\"126\">126</sup> שמתחילה השיב לו רפב\"י י\"ב תירוצי' על קושייתו, ואח\"כ כשהקשה רפב\"י השיב רשב\"י ך\"ד תירוצי', הגם שלא הי' לו למי להשפיע שהרי הי' רק עם ר\"א בנו<sup data-n=\"127\">127</sup> לבד, וכן בענין הסנהדרין כשהי' נושאין ונותנים יש בזה ב' פי' רש\"י והרמב\"ם<sup data-n=\"128\">128</sup> כ\"א בפ\"ע או עם בן זוגו, שנמצא כשצריכין לברר ההלכה ע\"פ עומק החכ' זהו דוקא בפ\"ע או עם בן זוגו שא\"ז בדרך השפעה כ\"א העלאת כלי שכלו לבחי' משכיל מקור החכ' כו', שמכ\"ז מובן שענין החכ' הוא למעלה מבחי' השפעה לזולתו, א\"כ בחי' זו אינה שייך להתהוות העולמות, ולכן ארז\"ל אלפים שנה קדמה תורה לעולם<sup data-n=\"129\">129</sup> להיותה למעלה ממדריגת התהוות העולמות שאלפי' שנה אלו ז\"ע אאלפך חכ' אאלפך בינה<sup data-n=\"130\">130</sup> בחי' חיוהי, ועד\"ז יובן שענין המדות שייכים לברה\"ע וכמ\"ש זכור רחמיך וחסדך כי מעולם המה, כי אמרתי עולם חסד יבנה<sup data-n=\"131\">131</sup>, משא\"כ ג\"ר וגם כלי הג\"ר אינם שייכים כלל לברה\"ע, ונמצא כי פי' ולתבונתו אין מספר לפי שיטה זו יתפרש על בחי' בינה, משא\"כ ז\"א הם שרש ומקור הגבול, אך מה שיש להקשות על שיטה זו מאחר שז\"א הוא שרש ומקור הגבול, וכ\"ש כלים דז\"א הם בבחי' גבול איך הם חד עם בחי' איהו כמאמר איהו",[["125","125","<b>בכתבי האריז\"ל נת' חיוהי. . חב\"ד. . וגרמוהי. . זו\"נ</b>: ראה סה\"מ תש\"ג ע' 104 בהערה. תש\"ח ע' 161 ובהערה כו. הדרן בקונטרס כ\"ב שבט תש\"נ (סה\"מ מלוקט ח\"ד ע' קסד) הערה 26. קיצורים והערות לתניא ע' קה. מאמרי אדמו\"ר הצ\"צ תרי\"ד ע' סב (בע\"ח). ע' סח (האריז\"ל פי' בע\"ח). ע' רטו. תניא עם ליקוט פירושים ע' תמג. ע' תנ (בכהאריז\"ל). סה\"מ תרכ\"ז ע' צז (האריז\"ל). תרכ\"ח ע' קמו (האריז\"ל). תרכ\"ט ע' שעח. תר\"ל ע' רצו ואילך. ע' שטז. תרל\"ב ח\"א ע' סא. ע' ר. תרל\"ג ח\"ב ע' שמח (האריז\"ל פי' בע\"ח). המשך מים רבים תרל\"ו פקנ\"א ע' קסה. המשך יונתי תר\"ם ע' יב. וראה שם ע' יד: ”חב\"ד דאצי'. . חיוהי לפי' הזהר ולפי' הע\"ח ואגה\"ק זהו בחי' אורות\"."],["126","126","<b>בענין רפב\"י</b>: שבת לג, ב. ראה סה\"מ תרכ\"ח ע' ד."],["127","127","<b>רק עם ר\"א בנו</b>: נסמן בהערה שלפנ\"ז."],["128","128","<b>בענין הסנהדרין. . רש\"י והרמב\"ם</b>: רש\"י סנהדרין מ, א ד\"ה כל הלילה: איש איש לעצמו. רמב\"ם הל' סנהדרין פי\"ב ה\"ג: כל אחד ואחד עם זוג שלו או עם עצמו בביתו. וראה גם ד\"ה אלה פקודי תש\"ל (סה\"מ מלוקט ח\"ה ע' רא ואילך). סה\"מ תרכ\"ח ע' ה. תרכ\"ט ע' ט. המשך והחרים תרל\"א ע' כו וע' מט. וככה תרל\"ז פכ\"ח ע' לז ואילך. פקי\"ג ע' קפג. וראה גם המשך מים רבים תרל\"ו פ\"ו ע' יא."],["129","129","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["130","130","<b>אאלפך חכ' אאלפך בינה</b>: איוב לג, לג. שבת קד, א. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשח. המשך וככה תרל\"ז פקי\"ז ע' קפג."],["131","131","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם סה\"מ תרכ\"ז ע' רנג. וש\"נ. תרל\"ד ע' נד."]]],[2000450068,"וגרמוהי חד, ומה שעל שיטה זו יקשה יותר קושי' מעל שיטה הא' שנת\"ל, דהנה לפי שיטה הא' האורות אינם בכלל גרמוהי כלל אפי' אורות דז\"א וגם הכלים אם היותם כ\"א בחי' בפ\"ע זה חסד וזה גבורה עכ\"ז א\"ס להתפשטותם ע\"כ גם הם בלתי גבול רק שנמצא בהם גם כח הגבול שזה חסד וזה גבורה וזהו בחי' הגבול שבהם לבד, אבל מ\"מ גם חסד זה יכול להתפשט בלי גבול שהרי אצי' הוא אלקות רק שבזה הגבלתם שהחסד אינו גבורה, לכן לא יקשה כלל איך הם מתייחדי' עם בחי' איהו שהרי גם בהם יש כח הא\"ס שהרי יכול להתפשט בלי גבול, אבל לפי שטה זו הב' שמפרש שגם באצי' בחי' גרמוהי הם המדות שהם בבחי' גבול האיך מתייחדי' עם בחי' איהו, וצ\"ל שבחי' איהו מתייחד עמהם בבחי' פרט זה לבד היינו להוות עולמות בע\"ג, בכדי שיהי' ברה\"ע. אך הנה דרוש זה נאמר לפי שטה הא' שבי\"ע הם בחי' גבול, וגם כח המהוה בי\"ע כו' כנ\"ל ובאצי' הוא בלי גבול כו'.\n<span data-k=\"ks\"><b>קיצור.</b> לפי' האריז\"ל שמפרש גרמוהי מדות צ\"ל פי' ולתבונתו אין מספר על בחי' בינה דוקא, והגם שהם בבחי' גבול מ\"מ מתייחד עמהם בחי' איהו בכדי שיהי' ברה\"ע, אך דרוש זה הוא לשטה שאצי' הוא בלי מספר כו'.</span>\nח) <b>ולהבין</b> שרש ענין ההפרש בין בחי' מספר לבחי' בלי מספר, הנה נודע כי יש ג' בחי' עש\"נ<sup data-n=\"132\">132</sup>, ולבאר ענינם צריכים לבאר ענין מה שאנו רואים שכל מה שנברא ונתהוה למטה הוא רק משל לגבי מה שלמעלה כמו עד\"מ יום ולילה שלמטה יום הוא אור ולילה הוא חשך כמ\"ש ויקרא אלקי' לאור יום ולחשך קרא לילה<sup data-n=\"133\">133</sup>, וענין בחי' יום ולילה שלמעלה יובן ממה שארז\"ל בילקוט ס\"פ תשא* שבאותן מם יום שהי' משה בהר מאין הי' יודע עיתים דיום ולילה, כשאומרים קדוש הי' יודע שהוא יום, וכשאומרי' ברוך הי' יודע שהוא לילה, ונודע שענין ההפרש שבין קדוש לברוך זהו ההפרש שבין שרפי' לחיות<sup data-n=\"134\">134</sup> ואופנים<sup data-n=\"135\">135</sup> שהשרפי' עומדי' ממעל לו<sup data-n=\"136\">136</sup> ע\"ש שהם חפצים להתעלות ולכלל באוא\"ס הקדוש ומובדל ולכן אומרים",[["132","132","<b>עש\"נ</b>: ראה ס\"י פ\"ג, מ\"ג ואילך. מאמרי אדה\"א בראשית ע' נו ואילך. וש\"נ. תו\"ח וארא ח\"א נג, ב ובהערה 13. לקמן המשך אם כסף תלוה על יד הערה 163."],["133","133","<b>ויקרא אלקי'. . לילה</b>: בראשית א, ה.\n*134)בילקוט ס\"פ תשא: ראה אוה\"ת בראשית כרך ג ע' תקנט שמביאו בשם מדרש תהלים. הובא (המדרש וגם הילקוט) לקמן בהמשך חייב אדם לברך פט\"ו על יד הערה 545. מאמר ד\"ה וידבר וכו' אלה הם מועדי על יד הערה 46."],["134","134","<b>ההפרש שבין קדוש לברוך. . שרפים לחיות ואופנים</b>: ראה גם תו\"ח תרומה ח\"ב שיז, סע\"ב. סה\"מ תרכ\"ט ע' קסא. תרל\"ד ע' רמד וע' רמו. בהערה הבאה."],["135","135","<b>ההפרש שבין שרפי' לחיות ואופנים</b>: ראה גם לקו\"ת נשא כח, ד. שלח מז, א. האזינו עד, ד. עט\"ר ע' מא ואילך. סה\"מ תרכ\"ח ע' קכח. תרכ\"ט ע' פג. וש\"נ. ע' רלז ואילך. תרל\"ד שם. תרל\"ו פקי\"א. זאת חנוכת המזבח תר\"ם פ\"ג. סה\"מ ליקוט ח\"ב ע' עח ואילך. נדפס גם בסה\"מ תרס\"ג מהדורת תשנ\"ד ע' רו ואילך."],["136","136","<b>שהשרפי' עומדי' ממעל לו</b>: ישעי' ו, ב. ראה גם לקו\"ת אמור לב, ב. לקמן המשך אם כסף תלוה פ\"ה על יד הערה 106. חייב אדם לברך פ\"ל על יד הערה 1188. ד\"ה ומקנה רב על יד הערה 96 (בשם הבעש\"ט — נדפס גם באוה\"ת בראשית כרך ו ע' 2054)־ ו(בחלק ההנחות) בהנחה שם על יד הערה 141. הנחה ד\"ה וכל מאמינים על יד הערה 99 (בשם הבעש\"ט). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקמח. סה\"מ תרל\"ד ע' רנ (בשם הבעש\"ט). תרל\"ה ח\"א ע' ו (בשם הבעש\"ט). ח\"ב ס\"ע שב ואילך (בשם הבעש\"ט). המשך מים רבים תרל\"ו פקי\"ג (בשם הבעש\"ט). כתר שם טוב (קה\"ת — מהדורת תשנ\"ט) בהוספות סמ\"ח. וש\"נ. מאמר ד\"ה אתם נצבים תשכ\"ב."]]],[2000450069,"קדוש<sup data-n=\"137\">137</sup>, והיינו מפני שמשיגים את בחי' אוא\"ס הקדוש ומובדל ולכן רוצים לצאת מנרתיקם ליבטל ולכלל באוא\"ס ב\"ה, ונק' שרפים ע\"ש שנשרפו<sup data-n=\"138\">138</sup> ברשפי אש התשוקה כו', אבל החיות והאופנים הם ברעש גדול<sup data-n=\"139\">139</sup>, הנה שרש ענין הרעש שלהם הוא על בחי' העדר ההשגה, להיות כי הם משיגי' שיש איזה דבר שלמעלה מהשגתם שהם אינם משיגים כמו השרפים הנ\"ל ולכן הם בבחי' רעש על בחי' העדר ההשגה ולזאת אומרים ברוך<sup data-n=\"140\">140</sup> כו' פי' שיתברך ויומשך בחי' ש' הוי' ממקומו<sup data-n=\"141\">141</sup> פי' ממקורו ושרשו כמשנ\"ת ביאור ד\"ז במ\"א. אמנם מ\"מ שניהם הם בבחי' הביטול רק שהשרפי' הם בבחי' העלאה, והחיות והאופנים הם בבחי' המשכה, ואינם בערך כלל מיום ולילה שלמטה, ומ\"מ משה הבין מזה אימתי יום ואימתי לילה שנמצא מה שלמטה הוא יום ולילה למעלה הוא בחי' קדוש וברוך שאינו בערך כלל אלא שזהו משל לבד ליום ולילה שלמעלה וכמו שהמשל אינו בערך הנמשל כן גם יום ולילה שלמטה הוא ג\"כ אינו בערך כלל ועכ\"ז ה\"ז משל. ועוד ארז\"ל<sup data-n=\"142\">*142</sup> שם שכשלמדו עמו תושב\"כ ידע שהוא יום וכשלמד עמו תושבע\"פ ידע שהוא לילה, ויש לבאר זה ע\"פ משארז\"ל ע\"פ במחשכים השבני זה תלמוד בבלי<sup data-n=\"143\">142</sup> שנמשל לחשך ולילה שזהו עיקר בחי' תושבע\"פ, והתורה נק' אור כמ\"ש ותורה אור<sup data-n=\"144\">143</sup>, ונמצא כי תושב\"כ ותושבע\"פ נמשל ליום ולילה הגם שאינו בערך כלל לכלליות הבריאה, וכ\"ש ליום ולילה הפרטי, וכמארז\"ל אלפי' שנה קדמה תורה לעולם וכנ\"ל שענין הקדימה הוא בחי' קדימה במעלה<sup data-n=\"145\">144</sup> וכמו שנת' ביאור ד\"ז במ\"א באריכות, ועכ\"ז מוכרח לומר שיום ולילה שהוא האור והחשך שלמטה ה\"ה עכ\"פ משל לזה שהרי משה הבין מזה על יום ולילה עד שמנה ואמר שהי' שם ארבעים יום וארבעים לילה<sup data-n=\"146\">145</sup>. וכן יובן ד\"ז מכלליות",[["137","137","<b>שהשרפי'. . אומרים קדוש</b>: ראה חולין צב, רע\"א ובתוד\"ה ברוך. ראה גם לקמן המשך אם כסף הנ\"ל. סה\"מ תרכ\"ז ע' קלה. תרס\"ה ע' קמ."],["138","138","<b>שרפים ע\"ש שנשרפו</b>: ראה לקו\"ת נשא כח, ד. סה\"מ תר\"ל ע' צב. תרל\"ה ח\"א ע' ו. לקמן המשך אם כסף תלוה על יד הערה 105. מאמר ד\"ה כי תבואו אל ארץ מושבותיכם תשי\"ב (סה\"מ תשי\"ב ע' 240). ד\"ה צאינה וראינה שבועות תשכ\"ב."],["139","139","<b>החיות והאופנים הם ברעש גדול</b>: ברכת יוצר."],["140","140","<b>אומרים ברוך</b>: נסמן בהערה 137."],["141","141","<b>ברוך. . הוי' ממקומו</b>: יחזקאל ג, יב. ראה מאמרי אדה\"ז תקס\"ט ע' קפה וע' קצו. עטרת ראש מב, ב. מאמרי אדה\"א דברים ח\"ג ע' תתקנא ואילך. קונטרסים ס\"ע תמג ואילך. סה\"מ תרל\"ד ע' רמג ואילך (ובהנסמן בריש המאמר שם). המשך מים רבים תרל\"ו פקי\"ז. סה\"מ ליקוט ח\"ב ע' פב. נדפס גם בסה\"מ תרס\"ג מהדורת תשנ\"ד ע' רי."],["142","*142","<b>ועוד ארז\"ל שם</b>: הובא גם לקמן בהמשך חייב אדם לברך פכ\"ו בשם הילקוט. ושם פל\"ו וכן באוה\"ת בראשית כרך ג ע' 1134 בשם המדרש תהלים."],["143","142","<b>במחשכים השבני. . בבלי</b>: איכה ג, ו [ושם: הושיבני]. ראה סנהדרין כד, א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' קו."],["144","143","<b>ותורה אור</b>: משלי ו, כג."],["145","144","<b>קדמה. . קדימה במעלה</b>: ראה פיה\"מ יב, ג ואילך. מאמרי אדה\"א תקע\"ז ע' קלו. סה\"מ תרכ\"ז ע' שב. תר\"ל ס\"ע פ ואילך. והחרים תרל\"א ע' כו. תרל\"ב ע' צ. ע' קסג. ע' שטו. תרל\"ד ע' נד. וככה תרל\"ז ע' קפג. תער\"ב ח\"ב ע' תשכה."],["146","145","<b>ארבעים יום וארבעים לילה</b>: משפטים כד, יח."]]],[2000450070,"דצח\"ם שלמטה שאינם רק משל לגבי דצח\"ם שלמעלה, שענין הצומח שלמטה הוא אילנות ודשאים, ולמעלה הוא בחי' מלאכי' שנק' בשם עצי היער<sup data-n=\"147\">146</sup> כמ\"ש אז ירננו כל עצי יער<sup data-n=\"148\">147</sup> שקאי על המלאכים שנק' כן עד שברכת ק\"ש שהוא בחי' הסיפור משבח וביטול המלאכים נק' בשם יערי<sup data-n=\"149\">148</sup> כמ\"ש אכלתי יערי עם דבשי<sup data-n=\"150\">149</sup> שפי' יערי יוצר אור שמספר ביטול המלאכים, ודבשי הוא בחי' מתיקות האהבה דק\"ש, שעם היות שהמלאכים יש להם מוחין ג\"כ ומתפעלים באהוי\"ר ע\"י השגתם, מ\"מ ענין המדות יש בהם קטנות וגדלות שמתחילה המדות הם בקטנות ומתגדלת אח\"כ מעט מעט הרי מצד א' הם דומים לבחי' המדות הגם שאין ערוך כלל בחי' הצמיחה דדשאי' ואילנות הגשמיים לגבי צמיחות בחי' המדות דמלאכים עכ\"ז ה\"ה משל לזה. ובזה יובן מארז\"ל נשאו דשאים ק\"ו בעצמם<sup data-n=\"151\">150</sup> ומה אילנות שאין דרכם לצאת בערבובי' אמר הכתוב למינהו אנו שדרכינו לצאת בערבובי' עאכו\"כ, ולכאו' איך ילמדו הדשאי' ק\"ו כי אינם בני לימוד כלל וכלל, שהרי הם רק צומח לבד ואין בהם גם מעלות החי וכ\"ש המדבר שלפי' א'<sup data-n=\"152\">151</sup> מעלתו מצד השכל, אלא שקאי על בחי' הדשאים שלמעלה שהם המלאכים שהם בדעת ידברו ומבינים ומשיגים, ועכ\"ז נק' דשאים<sup data-n=\"153\">152</sup> כמ\"ש בזהר בפי' דשא ועשב<sup data-n=\"154\">153</sup>, ע\"ש שהעיקר בהם בחי' המדות דאהוי\"ר מיכאל אהבה גבריאל יראה כו', ובמדות יש בחי' הצמיחה מקטנות המדה לגדלות המדה לכן נמשלו לצומח עד שיתכן ענין אמרם נשאו דשאי' ק\"ו, ומ\"מ הדשאי' שלמטה ה\"ה רק בחי' משל לבד לבחי' המלאכי' שנק' דשא ועשב ועצי היער כו'.\n<span data-k=\"ks\"><b>קיצור.</b> בכדי להבין ענין עש\"ן יקדים שכל מה שנברא למטה ה\"ה רק משל לגבי מה שלמעלה, כמו יום ולילה לגבי קדוש וברוך או תושב\"כ ותושבע\"פ או דשא ועשב הגשמי לגבי המלאכים שנק' דשא ועשב ועצי היער כו'.</span>\nט) <b>ועד\"ז</b> יובן בכלליות מין החי יש כמה מיני נבראים בהמות חיות ועופות ששרש החיות הם מבחי' פני ארי'<sup data-n=\"155\">154</sup> אל הימין<sup data-n=\"156\">155</sup> שבמרכבה, ושרש",[["147","146","<b>מלאכי'. . עצי היער</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'קיד. וש\"נ. שה\"א פה, ב ובהערה 17. סה\"מ תרכ\"ט ע' ח וע' קנח. המשך מים רבים תרל\"ו ס\"ע מה וע' קעא. ח\"ב ס\"ע שעב ואילך."],["148","147","<b>אז ירננו כל עצי יער</b>: תהלים צו, יב."],["149","148","<b>המלאכים נק' בשם יערי</b>: ראה גם תו\"ח יתרו ח\"ב רס, ד הערה 220."],["150","149","<b>אכלתי יערי עם דבשי</b>: שה\"ש ה, א. ראה זהר פינחס רכו, ב. לקו\"ת שה\"ש לד, ב."],["151","150","<b>נשאו דשאים ק\"ו בעצמם</b>: ראה חולין ס, א ובחידושי אגדות מהרש\"א שם. סה\"מ תרכ\"ח ע' ג. ע' קסט וע' קצא. תרכ\"ט ע' ז וע' קנח. תרל\"ב ח\"א ע' רעג. מים רבים תרל\"ו ע' קעא. סה\"מ קונטרסים ח\"ב ע' שעב."],["152","151","<b>שלפי' א'</b>: ראה סה\"מ תרכ\"ח ע' צד ואילך. ס\"ע קסו ואילך. והחרים תרל\"א ס\"ע נט ואילך. תרל\"ג ח\"ב ע' תקט."],["153","152","<b>המלאכים. . נק' דשאים</b>: ראה לקו\"ת פינחס עט, ג וש\"נ ע\"י הצ\"צ. בהערה הבאה."],["154","153","<b>כמ\"ש בזהר בפי' דשא ועשב</b>: ראה זהר בראשית יח, ב. אוה\"ת בראשית לג, ב. לה, ב. סה\"מ תרכ\"ח ע' ג ע' קסט וע' קצא. סה\"מ תרכ\"ט ע' קח. תר\"ל ע' קנה. המשך מים רבים שבהערה 150."],["155","154","<b>ששרש החיות. . פני ארי'</b>: ראה טעמי המצות להרח\"ו ר\"פ ויקרא וציין לזהר פ' פינחס [רמ, ב — ומ\"ש באור החמה שם ראה אגרות קודש כ\"ק אדמו\"ר מהר\"ש ע' צב ואילך]. אור החיים אחרי יז, יד. מאמרי אדה\"א דברים ח\"ד ע' א'רו וע' א'רפה. לקמן המשך אם כסף תלוה על יד הערה 82."],["156","155","<b>פני ארי' אל הימין</b>: יחזקאל א, י."]]],[2000450071,"הבהמות הם מבחי' פני שור<sup data-n=\"157\">156</sup> שבמרכבה, ושרש העופות הם מבחי' פני נשר<sup data-n=\"158\">157</sup> שבמרכבה, וכאשר נערוך בחי' הארי' והשור שלמטה לגבי בחי' הארי' והשור שלמעלה שעומדים ביראה, ונושאים את הכסא<sup data-n=\"159\">158</sup> עם בחי' אדם שעל הכסא<sup data-n=\"160\">159</sup> לבחי' אוא\"ס שכי לא אדם הוא<sup data-n=\"161\">160</sup> דעת לנבון נקל שאין ערוך בניהם כלל, אך מאחר שמ\"מ שרש שרשם הוא מהם לכן נוכל לומר שה\"ה בחי' משל לבחי' ארי' ושור שלמעלה שהרי אותיות ארי' מחי' אותם וכן שור כו'. ובאמת גם בחי' ארי' ושור שלמעלה ה\"ה ג\"כ רק כמו בחי' משל לגבי שלמעלה מהם, דהנה נודע שכמו שיש בחי' ד' חיות המרכבה במרכבתא תתאה דבריאה, כן יש בחי' ד' חיות המרכבה במרכבתא עילאה<sup data-n=\"162\">161</sup> דאצי', שנמצא בחי' חסד שבאצי' ה\"ז כדוגמת בחי' הארי'<sup data-n=\"163\">162</sup> בבריאה, שזאת מובן לכל ערך הריחוק מן הנבראים דבי\"ע לבחי' הנאצלים שבאצי' שאינו בערך כלל אלא שהוא רק בחי' משל לבד, וכן בחי' הארי' דחסד עליון דאצי' ה\"ה ג\"כ רק בחי' משל לבחי' החכ' דאצי' שנק' ג\"כ ארי'<sup data-n=\"164\">163</sup>, כי ארי' הוא אותיות ראי'<sup data-n=\"165\">164</sup> וכתיב וירא ראשית לו<sup data-n=\"166\">165</sup>, ועש\"ז נק' החכמים עיני העדה<sup data-n=\"167\">166</sup> וכמ\"ש במ\"א ערך הריחוק שבין מוחין למדות<sup data-n=\"168\">167</sup> באריכות הן מצד עצמם והן בפעולתם כו' אלא שמ\"מ הרי בחי' הארי' דחסד דאצי' הוא משל לבחי' הארי' דחכמה, וכן בחי' הארי' דחכמה ה\"ה ג\"כ רק בחי' משל לבחי' הארי' שלמעלה הימנו, שהרי גם הכתר נק' ארי'<sup data-n=\"169\">168</sup> כמ\"ש ארי' שאג מי לא ירא ה' אלקים דבר מי לא ינבא, ואיתא שבחי' דבר זה",[["157","156","<b>ושרש הבהמות. . פני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. טעמי המצות שם. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרכ\"ט ע' קי. וש\"נ. לקמן המשך אם כסף תלוה על יד הערה 82."],["158","157","<b>ושרש העופות. . פני נשר</b>: ראה לעיל הערה 154. לקו\"ת נשא כח, ג. תו\"ח יתרו ח\"ב ער, א. סה\"מ תרכ\"ט שם."],["159","158","<b>ונושאים את הכסא</b>: נסמן לקמן הערה 227."],["160","159","<b>אדם שעל הכסא</b>: יחזקאל א, כו."],["161","160","<b>שכי לא אדם הוא</b>: שמו\"א טו, כט."],["162","161","<b>במרכבתא תתאה. . עילאה</b>: ראה גם סידור שחרית סד, א. ביאורי הזהר ויקרא סב, ב. מאמרי אדה\"א ויקרא ח\"א ע' רכג. שערי תשובה צב, ג. תו\"ח וארא ח\"א פו, ב. אוה\"ת שלח ע' תקפד ואילך. סה\"מ תר\"ל ע' קעה. והחרים תרל\"א ס\"ע כה ואילך. תרל\"ו ח\"ב ע' שעג. וככה תרל\"ז פקי\"ז ע' קפב ואילך."],["163","162","<b>חסד. . הארי'</b>: ראה תז\"ח צד, ג. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ. תו\"ח משפטים ח\"ב רפו, ד. וש\"נ."],["164","163","<b>החכ' דאצי' שנק' ג\"כ ארי'</b>: ראה גם סה\"מ תרכ\"ו ע' יז. ע' נד. ע' קסד. תרכ\"ז ע' צח. תרכ\"ח ע' קמז וע' קצא. תרכ\"ט ע' צד ואילך. והחרים תרל\"א ע' כו. תרל\"ב ח\"א ע' עדר. תרל\"ד ע' קעא. מים רבים תרל\"ו פקנ\"ז ע' קעג. וככה תרל\"ז שם ע' קפג."],["165","164","<b>ארי' הוא אותיות ראי'</b>: ראה ת\"ז ת\"ע (קכב, א). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ל."],["166","165","<b>וירא ראשית לו</b>: ברכה לג, כא. ראה גם סה\"מ תרל\"ד ע' קעא. והחרים. מים רבים. וככה שבהערה 163."],["167","166","<b>החכמים עיני העדה</b>: שלח טו, ד. ראה לקמן המשך חייב אדם לברך פ\"ח על יד הערה 246 שמציין ללקו\"ת ואתחנן ב, סע\"ד. ג, ג. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. תו\"ח בא ח\"א קב, א ובהערה 248."],["168","167","<b>הריחוק שבין מוחין למדות</b>: ראה המשך והחרים תרל\"א ע' ד ואילך. תרכ\"ט ע' ט. הדרושים שבהערה 35. לעיל פ\"ז."],["169","168","<b>הכתר נק' ארי'</b>: ראה גם אוה\"ת שבועות ע' רכא. איכה ע' א'נו וע' א'נז. הנסמן בהערה 163.\n169)ארי' שאג: עמוס ג, ח. ראה שמו\"ר פכ\"ט, ט. המשך והחרים תרל\"א ע' כז. מים רבים תרל\"ו שם ס\"ע קעג ואילך. וככה תרל\"ז שם."]]],[2000450072,"שדבר ה' אלקים היינו בחי' דבור אנכי ה' אלקיך<sup data-n=\"170\">170</sup> שהוא בחי' כתר<sup data-n=\"171\">171</sup>, שלגבי בחי' זו גם החכמה הוא רק בחי' משל לבד שהרי החכמה מאין תמצא<sup data-n=\"172\">172</sup>, וכולם בחכמה עשית<sup data-n=\"173\">173</sup> שהחכמה נחשב כעשי'<sup data-n=\"174\">174</sup> כו', ונמצא כי יש ריבוי בחי' והתחלקות המדריגות שכולם הם רק בחי' משל להגבוה ממנו כו' ועד\"ז הוא בכל הפרטים, וכמו בעוה\"ז הגשמי כשמציירים צורת אדם הגשמי ע\"ג לוח עם היות שהוא דומה ממש להאדם הרי מ\"מ הנה הוא בלתי חיות ואינו בערך אדם החי כלל הגם שהוא דומה לו ממש גם בציור החיות כמו שעושים האומנים הבקיאים עכ\"ז אינו רק כמו משל לבד להאדם החי, וכן בציור דצ\"ח כמשל המפה שמציירים בה ציור כל מה שעל כדור הארץ ימים ונהרות ודרכים וערים גדולים וקטנים וכפרים ומדבריות ודשאים וצמחים למניהן שמרומז בה הכל רק שהוא בקיצור נמרץ שאינו בערך כלל לגוף הדבר המרומז בה שתופסי' מקום ושטח, משא\"כ על המפה נרמז רק בתמונה כמו קו זה רומז על נהר גדול באורך ורוחב, וקו בתמונה אחרת מורה על הדרך ועיגול זה רומז על עיר בנוי' עם כו\"כ בתים שאינו בערך כלל וכלל, ועכ\"ז נוכל לומר שהמפה ה\"ה משל שע\"י נוכל להבין קצת הדברים המרומזים בה, וכמו\"כ יובן שכלליות העולם וד' רוחותי' ומעלה ומטה ה\"ז רק בחי' משל לבד לגבי שרש שרשם בחי' ו\"ק שלמעלה שהם בחי' המדות עליונות כו'.\n<b>ועוד</b> למעלה יותר יובן שגם התורה נק' משל הקדמוני<sup data-n=\"175\">175</sup>, ויתפרש זה בשני אופנים<sup data-n=\"176\">*176</sup> הא' שהתורה שלמטה שנתלבשה בענינים גשמיים שהם רק בחי' משלים לבד לדברים עליונים שבבחי' התורה כמו שהיא ברוחניות למעלה, והב' שגם התורה כמו שהיא למעלה היא ג\"כ רק בחי' משל רק שהיא משל הקדמוני פי' שהיא בחי' משל לבחי' אוא\"ס קדמונו ש\"ע, רק שבזאת יתרון בחי' המשל דתורה שע\"י בחי' משל דתורה יכולים להבין בחי' הנמשל משא\"כ שארי המשלים עד\"מ מארי' שלמטה א\"א להבין בחי' הארי' שבמרכבה וכדומה כו', ועכ\"ז גם התורה היא בחי' משל רק שהיא משל הקדמוני כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שגם בחי ג\"כ כ\"א הוא רק משל לגבי שלמעלה הימנו עד\"מ ארי' שלמטה לגבי בחי' ארי' דמרכבה, וכן למעלה יותר, וציור האדם והמפה ה\"ה ג\"כ משל, וכן כלליות ו\"ק דעולם לגבי ו\"ק שלמעלה עד שגם התורה נק' ג\"כ משל רק שהיא משל הקדמוני כו'.</span>\nיו\"ד) <b>וכמו</b> שהוא בכלליות הנבראים כן יובן ד\"ז בכלליות בחי' עש\"נ שבחי' עולם שנה נפש שלמטה ה\"ה רק בחי' משל לבחי' עולם שנה נפש שלמעלה",[["170","170","<b>אנכי ה' אלקיך</b>: יתרו כ, ב."],["171","171","<b>אנכי. . כתר</b>: ראה זהר רע\"מ פינחס רנו, ב."],["172","172","<b>החכמה מאין תמצא</b>: איוב כח, יב."],["173","173","<b>וכולם בחכמה עשית</b>: תהלים קד, כד."],["174","174","<b>שהחכמה נחשב כעשי'</b>: ראה תניא פ\"ב בהגהה. לקמן המשך חייב אדם לברך פ\"ח על יד הערה 223. וש\"נ."],["175","175","<b>התורה נק' משל הקדמוני</b>: שמו\"א כד, כג וברש\"י שם. ראה גם הנסמן במאמרי אדה\"א דברים ח\"ב ע' תב. שמות ח\"ב ע' שפג. סה\"מ תרכ\"ז ע' פז."],["176","*176","<b>משל הקדמוני. . בשני אופנים</b>: ראה גם סה\"מ תרכ\"ט ע' צו. תרל\"ה ח\"א ס\"ע נז ואילך."]]],[2000450073,"הימנו, ופי' עולם שנה נפש הנה השנה יש בה י\"ב חדשים שרומזי' לי\"ב גבולי אלכסון שאינם בחי' עצמיות המדות וכמשנ\"ת באריכות בדרוש דמחר חדש<sup data-n=\"177\">176</sup> רק שע\"י האלכסונים יכולים להגיע לעצמיות המדה, ועולם הוא בחי' מדות בעצם, וכנ\"ל בענין זכור רחמיך וחסדיך כי מעולם המה, ונפש הוא בחי' חיות העולם כן פי' רבנו ז\"ל<sup data-n=\"178\">177</sup>, אמנם בס\"י איתא עש\"ן הוא בחי' נר\"נ<sup data-n=\"179\">178</sup>, נמצא שנפש הוא בחי' מל' כו', אך רבינו ז\"ל ברוב הדרושים אמר כנ\"ל ומסתמא שמע כן מהמגיד ז\"ל<sup data-n=\"180\">179</sup>.\n<b>ובכ\"ז</b> יובן שרש ההפרש בין ש' הוי' לש' שדי<sup data-n=\"181\">180</sup>, שכל בחי' המספר והמשלים הנ\"ל נמשך מש' שדי כי ש' שדי הוא שאמר לעולמו די<sup data-n=\"182\">181</sup> בבחי' גבול כו' ובחי' בלי מספר הוא מבחי' ש' הוי' שהוא בלי גבול כו', וזהו שרש ההפרש בין בחי' מספר ומשלים לבחי' בלי מספר.\n<b>ואמנם</b><sup data-n=\"183\">182</sup> מה שצ\"ל הלא ש' שדי נאמר ונגלה לאברהם בציוי מצות מילה כמ\"ש אני אל שדי<sup data-n=\"184\">183</sup> התהלך לפני כו', ואתנה בריתי<sup data-n=\"185\">184</sup>, וא\"כ איך נאמר כאן שברה\"ע הי' ע\"י ש' שדי, אך הענין הוא דהנה במדרש פי' עוד על ש' שדי שדי באלקותי לכל ברי'<sup data-n=\"186\">185</sup>, פי' ענין בחי' די זה שמבחי' ש' שדי יכול להיות נמשך גילוי אלקות כ\"כ בשפע עד שיאמרו די, וכמו שאמר ע\"פ והריקותי לכם ברכה עד בלי די עד שיבלו<sup data-n=\"187\">186</sup> שפתותיכם מלומר די והגם ששם אמר בלי די וכאן די באלקותי ענינם אחד שפי' די לכל ברי' הוא ריבוי ההפלגה, וכמו בצדקה שהיא מצוה נא' בה די מחסורו, שאמרו אפי' סוס לרכוב עליו<sup data-n=\"188\">187</sup> שכ\"ז נכלל בכלל די, וע' בד\"ה אני לדודי שלא נדפס<sup data-n=\"189\">188</sup>",[["177","176","<b>י\"ב חדשים. . לי\"ב גבולי אלכסון. . בדרוש דמחר חדש</b>: ראה פרדס שער פרטי השמות שכ\"א, פ\"ו. מאמרי אדה\"ז תקס\"ז ע' מט ואילך. ע' נח ואילך. אוה\"ת בראשית ה, סע\"ב ואילך. טו, א ואילך. הנסמן בסה\"מ תרכ\"ז כאן ע' צט."],["178","177","<b>ונפש. . חיות העולם כן פי' רבינו ז\"ל</b>: ראה מאמרי אדה\"ז תקס\"ד ע' קכה. לקו\"ת חוקת סד, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' א וס\"ע שט ואילך. אוה\"ת וארא כאן ע' ר וע' ריח. יתרו ע' תתיח וע' תתכה. סה\"מ תרכ\"ז ע' צט. וש\"נ. תרכ\"ח ע' קמד. לקמן המשך אם כסף על יד הערה 163 ואילך."],["179","178","<b>עש\"ן הוא בחי' נר\"נ</b>: ראה אוה\"ת יתרו שם ע' תתטז ואילך. ע' תתכג ואילך."],["180","179","<b>ומסתמא שמע כן מהמגיד ז\"ל</b>: ראה גם סה\"מ תרכ\"ז ע' ק ובהנסמן שם. תרכ\"ח שם. וראה גם אור האמת אמרי צדיקים (אשר כתבם. . מו\"ה לוי יצחק. . ברדיטשוב) ברוקלין תש\"כ ס\"ע מד."],["181","180","<b>ההפרש בין ש' הוי' לש' שדי</b>: ראה גם אוה\"ת כאן ע' ריט."],["182","181","<b>שאמר לעולמו די</b>: ראה חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג."],["183","182","<b>ואמנם</b>: להבא לקמן ראה גם סה\"מ תרכ\"ט ע' מט. וש\"נ. ס\"ע צו ואילך. תר\"ל ע' סא. תרל\"ה ח\"א ע' מג ואילך. ד\"ה וארא אל אברהם תשל\"ה קונטרס כ\"ד טבת תנש\"א (סה\"מ מלוקט ח\"ה ע' קלז ואילך)."],["184","183","<b>אני אל שדי</b>: לך יז, א."],["185","184","<b>ואתנה בריתי</b>: לך שם ב."],["186","185","<b>במדרש. . שדי באלקותי לכל ברי'</b>: ראה רש\"י לך יז, א. ב\"ר פמ\"ו, ג."],["187","186","<b>והריקותי לכם ברכה. . עד שיבלו</b>: מלאכי ג, י. שבת לב, ב."],["188","187","<b>די מחסורו. . לרכוב עליו</b>: פ' ראה טו, ח. כתובות סז, ב."],["189","188","<b>אני לדודי שלא נדפס</b>: בסה\"מ תרכ\"ז ותרכ\"ח כאן: אני לדודי הנ\"ל, ולפנ\"ז הובא: אני לדודי ך\"א (ראה גם לעיל הערה 63), ראה אוה\"ת ראה ע' תשפג (ושם: הרמב\"ן והבחיי ר\"פ וארא). שה\"ש ע' תקנא. ע' תקנה."]]],[2000450074,"שמשם שדי נמשך ניסים נסתרים<sup data-n=\"190\">189</sup> כו' וע' בד\"ה ויכל אלקי' ביום השביעי, ך\"א<sup data-n=\"191\">190</sup>, ונמצא כי יש ב' בחי' בש' שדי הא' כמשנת\"ל שברה\"ע הי' ע\"י ש' שדי שזהו פי' שאמר לעולמו די בבחי' הגבלה, ומה שע\"י המילה נתגלה בחי' ש' שדי ז\"ע בחי' הב' שדי באלקותי לכל ברי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שגם בעש\"ן יש כו\"כ בחי' שכל א' הוא משל לבד לגבי שלמעלה הימנו, ופי' עש\"ן פי' רבינו ז\"ל שנה יב\"ח יבג\"א עולם מדות בעצם נפש חיות העולם, ובס\"י עש\"ן נר\"נ, ושרש ההפרש בין ש' שדי לש' הוי' זהו ההפרש שבין מספר לבלי מספר, רק ש' שדי שגבי מצות מילה זהו בחי' ב' שדי באלקותי לכל ברי' כו'.</span>",[["190","189","<b>שמשם שדי נמשך ניסים נסתרים</b>: ראה רמב\"ן ובחיי לך יז, א. בהערות שלפנ\"ז 188. 182. ד\"ה אנכי ה\"א תשכ\"ו ע' 3 ובהערה 6."],["191","190","<b>ויכל אלקי'. . ך\"א</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן ע' ק (וראה בהערה שם). תרכ\"ח ע' קמט."]]],[2000450075,"<h3>ועמדו רגליו כו' אותיות כו'</h3>\nיא) <b>ויובן</b><sup data-n=\"192\">191</sup> עוד ענין בחי' מספר ובלי מספר ממ\"ש במ\"א ע\"פ ועמדו רגליו ביום ההוא על הר הזתים<sup data-n=\"193\">192</sup>, פי' וענין רגליו הוא בחי' אותיות<sup data-n=\"194\">193</sup>, ויובן בהקדם ענין האותיות, דהנה שרש האותיות הם בנפש<sup data-n=\"195\">194</sup> עצמה רק שקבען בפה<sup data-n=\"196\">195</sup>, אמנם שרשם ומקורם הם בעצם הנפש עצמה כו' ורק שהם יוצאים ע\"י המוצאות אחה\"ע<sup data-n=\"197\">196</sup> מהגרון גיכ\"ק מהחיך דטלנ\"ת<sup data-n=\"198\">197</sup> מהלשון כו', והמופת לזה הוא מן קטן או חרש הגם שיש להם המוצאות ומנענעי' המוצאות מ\"מ א\"א להם לדבר, והיינו מפני שאין האותיות בהמוצאות כו' כ\"א בנפש, ולכן החרש מוליד שלם<sup data-n=\"199\">198</sup> מפני כי בנפשו יש בחי' האותיות, וההולדה נמשך מעצם הנפש<sup data-n=\"200\">199</sup> כמ\"ש במ\"א לכן מוליד שלם,",[["192","191","<b>ויובן</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (ד' מההמשך) והוא ד\"ה: ”ועמדו רגליו ביום ההוא\" (הכולל פרקים יא-יג). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש."],["193","192","<b>ועמדו רגליו. . הזתים</b>: זכרי' יד, ד (ושם: הזיתים — ראה גם לקמן מאמר ד\"ה גדול יהי' על יד הערה 85. ו(בחלק ההנחות) בהנחה שם על יד הערה 143)."],["194","193","<b>רגליו. . אותיות</b>: ראה מאמרי אדה\"ז תקע\"א ע' נט. נביאים ע' רסא (נעתק בשינויים ב)אוה\"ת כאן ע' רכ ואילך. אוה\"ת זכרי' ע' תקכג. סה\"מ תרכ\"ז כאן וע' תכ. תרכ\"ח כאן פ\"ו. תר\"ל ע' שכ. לקמן (בחלק ההנחות) הנחה ד\"ה גדול יהי' על יד הערה 145."],["195","194","<b>שרש האותיות הם בנפש</b>: ראה אגה\"ק ס\"ה. מאמרי אדה\"ז תקע\"א (ע' נז)־ נביאים (ע' רנח)־ אוה\"ת (כאן) וסה\"מ תרכ\"ז ותרכ\"ח שבהערה 193. תרל\"ג ח\"ב ע' שנז (ובהנסמן שם בע' שנו). ש\"א ו, ב ובהנסמן במ\"מ לשם. תו\"ח בשלח ח\"א קמח, א. וש\"נ."],["196","195","<b>שקבען בפה</b>: ס\"י פ\"ב, מ\"ג. ”ולא שבראן שם בפה\" תו\"א מקץ מב, ב."],["197","196","<b>אחה\"ע</b>: ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' קה."],["198","197","<b>אחה\"ע. . גיכ\"ק. . דטלנ\"ת</b>: ס\"י (מהדורת מנטובא שכ\"ב) פ\"ב, מ\"א."],["199","198","<b>החרש מוליד שלם</b>: ראה סה\"מ תרכ\"ז ותרכ\"ח כאן פ\"ו. תרל\"ב ח\"ב ע' שמח. וראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' שכא. ענינים ע' רפט."],["200","199","<b>וההולדה נמשך מעצם הנפש</b>: ראה גם אגה\"ק ד\"ה להבין מ\"ש בפע\"ח (תניא קנז, א). ביאוה\"ז בראשית ב, ב (ולהצ\"צ כרך ב' ע' תריג וע' תרטז). נח, ה, ד. בלק צט, א. מאמרי אדה\"ז ענינים ע' קנא. מארז\"ל ע' שי. ע' שכ. אמ\"ב שער הק\"ש כו, ד. שער האמונה נג, ב. פיה\"מ י, סע\"ד ואילך. סהמ\"צ להצ\"צ ג, ב. בהערה שלפנ\"ז."]]],[2000450076,"ומ\"מ אינו יכול לדבר מפני כי אין האותיות נמשכי' מהנפש לכלי המבטא שלו שיוציאו האותיות אחה\"ע הגשמי', ולכן לדבר אינו יכול, ומ\"מ מוליד שלם שאינו תלוי בהתגלותם בכלי המבטא כו', ונודע כי באותיות יש ב' בחי' אותיות<sup data-n=\"201\">200</sup>, היינו אותיות המחשבה ואותיות הדבור, ואם כי בהתגלותם בחי' אותיות המחשבה דקים וגבוהים יותר מאותיות הדבור מ\"מ בשרשם בנפש שרש אותיות הדבור קודמי' לאותיות המחשבה<sup data-n=\"202\">201</sup> כמ\"ש מזה במ\"א באריכות וע' בד\"ה אדם כי יהי'<sup data-n=\"203\">202</sup> בעור בשרו בענין ואדם אין ומעלת המדבר כו'.\n<b>והנה</b> שרש חיות כל העולמות הוא מבחי' אותיות כמו עד\"מ מאמר יהי רקיע עומד תמיד ברקיע להחיותו כמ\"ש לעולם ה' דברך נצב בשמים<sup data-n=\"204\">203</sup> שדבר ה' עומד תמיד בשמים להחיותו כמ\"ש בסש\"ב ח\"ב בשם הבעש\"ט ז\"ל<sup data-n=\"205\">204</sup> וכ\"מ ממדרש תלים ע\"פ זה<sup data-n=\"206\">205</sup>, ואם הי' האותיות מסתלקים כרגע א' הי' חוזר לאין ואפס המוחלט ממש, כ\"א ע\"י שהאותיות עומדים תמיד בשמים עד\"מ להוותם ולהחיותם עי\"ז נמצאים תמיד מאין ליש, וכ\"ה בכל הנבראים, ודעת לנבון נקל שהאותיות הנ\"ל הם בטלים בתכלית לאוא\"ס, שהרי מה שבכוחם להוות ולהחיות זהו לפי שהם דברי הקב\"ה שנמצא בהם תמיד כח האלקה הפועל ואינם מהות בפ\"ע כ\"א דברי האל ית', וממילא גם כלליות העולם המתהווים ומקבלים חיות מהאותיות ג\"כ בטלים בתכלית. ובזה יובן מ\"ש בסש\"ב ח\"ב פ\"ג<sup data-n=\"207\">206</sup> אלו ניתנה רשות לעין לראות ולהשיג את החיות והרוחניות<sup data-n=\"208\">207</sup> שבכל נברא השופע בו, היינו בחי' האותיות שרש ומקור העולמות לא הי' גשמיות הנברא וחומרו וממשו נראה כלל לעינינו כי הוא בטל במציאות ממש.\n<b>ועפ\"ז</b> יובן היטיב ענין בחי' ביטול העולמות שהגם שנת' במ\"א שמה שנראה העולם ליש ודבר זהו שקר גמור<sup data-n=\"209\">208</sup>, אם כי האמת כן הוא שגם היותו יש",[["201","200","<b>ב' בחי' אותיות</b>: ראה מאמרי אדה\"ז־ אוה\"ת וסה\"מ שבהערה 194."],["202","201","<b>שרש אותיות הדבור קודמי' לאותיות המחשבה</b>: ראה סה\"מ תרכ\"ח כאן בהחצאי עיגול. הנסמן בהערה שלפנ\"ז."],["203","202","<b>בד\"ה אדם כי יהי'</b>: אוה\"ת תזריע כרך ב ע' תקיח ואילך. סה\"מ תרל\"ה ח\"א ע' קצה ואילך."],["204","203","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."],["205","204","<b>בסש\"ב ח\"ב בשם הבעש\"ט ז\"ל</b>: שער היחוד והאמונה פ\"א. וראה כתר שם טוב קה\"ת מהדורת תשנ\"ט סע\"ז. וש\"נ. סה\"מ שבהערה הבאה ובהנסמן בסה\"מ תרכ\"ז שם."],["206","205","<b>ממדרש תלים ע\"פ זה</b>: קיט, לו. ראה גם סה\"מ תרכ\"ט ע' רטז־ ע' רפו־ ע' שא־ תרל\"ו ח\"ב ע' רסה. מ\"מ הגהות והע\"ק לשער היחוה\"א שם. אבל בסה\"מ תרכ\"ו ע' יט־ תרכ\"ז ע' רצו־ ע' שצג־ תר\"ל ע' קעז־ תרל\"ג ח\"א ע' רצז: במד\"ר."],["207","206","<b>אלו</b>: בשער היחוה\"א : אילו. ובסה\"מ תרכ\"ז ותרכ\"ח כאן פ\"ו כבפנים."],["208","207","<b>והרוחניות</b>: שם: ורוחניות. ראה גם סה\"מ תרכ\"ז ותרכ\"ח כאן. תרכ\"ט ע' קסד. המשך מים רבים תרל\"ו פקנ\"ט ע' קעו. הנסמן בתניא ליקוט פירושים כאן ע' צח."],["209","208","<b>שמה שנראה העולם ליש. . שקר גמור</b>: בסה\"מ תרכ\"ו ע' יז־ ע' נה וע' קסה מציין: בת\"א. ובתרל\"ב ח\"א ע' ערה־ תרל\"ד ע' שסא מציין: בפ' תשא ע\"פ זה יתנו (פו, ג). ע' רעו. וראה לקו\"ש יתרו כרך ו ע' 122 הערה 6."]]],[2000450077,"מ\"מ בטל הוא בתכלית, מ\"מ לפי הנ\"ל יוכל להקשות מ\"ע ברה\"ע דכתיב בראשית ברא<sup data-n=\"210\">209</sup>, משמע שנברא ליש, וכדמות ראי' לזה על פשוטו של מקרא ממארז\"ל במשנה פ\"ז דסנהדרין שנים לוקטים<sup data-n=\"211\">210</sup> קשואים כו' העושה מעשה חייב האוחז את העינים פטור ואם נאמר שזהו רק לעינינו למה יתחייב העושה מעשה כו' ואם נאמר שגם הסקילה היא רק לעינינו א\"כ אין שכר ועונש ח\"ו ישתקע הדבר ולא יאמר, אלא כנ\"ל יובן היטב שגם שנברא העולם ליש ודבר וכמ\"ש הרס\"ג דבר מלא דבר<sup data-n=\"212\">211</sup>, והתהוותו וחיותו וקיומו זהו מהאותיות וכנ\"ל ואותיות בטלים בתכלית א\"כ גם העולם בטל, וע' בד\"ה אנכי<sup data-n=\"213\">212</sup> באורך.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר ענין האותיות ששרשם בעצם הנפש, ואותיות הדבור קודמים, ומהם התהוות העולמות וקיומם והם בטלים בתכלית א\"כ גם העולם בטל כו'.</span>\nיב) <b>והנה</b> כאשר נמשכו האותיות להוות עולמות נמשכו אותיות שמהם נתהוו עולמות, ויש אותיות שנשארו למעלה שלא נתהוו מהם בחי' עולמות, ועפ\"ז יובן מ\"ש בזהר באד\"ר קך\"ח ב' בגולגלתא יתבין תליסר אלפי רבוא עלמין<sup data-n=\"214\">213</sup>, ומספר אלף אלפין ריבוא ושבעת אלפי' ות\"ק קוצי דשערי, שכוונתו אינו על עלמין ממש כ\"א על בחי' האותיות הנ\"ל שנשארו למעלה שלא נתהוו מהם עולמות, ונק' עולמות היינו שאם היו נמשכים למטה הי' מתהווה מהם עולמות. וז\"ע ועמדו רגליו ביום ההוא על הר הזתים, כי הנה שמן הוא בחי' חכ'<sup data-n=\"215\">214</sup>, וזיתים הוא מקור החכמה<sup data-n=\"216\">215</sup> והיינו בחי' מזלות ונוצר ונקה מקור החו\"ב<sup data-n=\"217\">216</sup>, וז\"ע שנים זיתים<sup data-n=\"218\">217</sup> כו', והר הוא עוד בחי' היותר גבוה<sup data-n=\"219\">218</sup> כו', ולע\"ל ועמדו רגליו על הר הזיתים שיהי' הגילוי מבחי' רגליו על הר הזיתים, והיינו בחי' אותיות היותר עליונים.",[["210","209","<b>בראשית ברא</b>: בראשית א, א."],["211","210","<b>במשנה פ\"ז דסנהדרין שנים לוקטים</b>: מי\"א (סנהדרין סז, א). ראה גם סה\"מ תרכ\"ו שבהערה 208. תרכ\"ח ע' קצב ושם: ”בשבת\" (אמנם כאן מציין כבפנים). תרכ\"ט ס\"ע קסא. תרל\"ב ח\"א ע' ערה. מים רבים תרל\"ו פקנ\"ח ע' קעה."],["212","211","<b>וכמ\"ש הרס\"ג דבר מלא דבר</b>: ראה לקמן (בחלק ההנחות) הנחה ד\"ה וידבר וגו' ויצוום הערה 29."],["213","212","<b>בד\"ה אנכי</b>: בסה\"מ תרכ\"ז ותרכ\"ח כאן: ך\"ו — ראה סה\"מ תרכ\"ו ע' נה. ע' יז וע' קסה. וראה גם סה\"מ תרכ\"ח ע' קצא ואילך. תרכ\"ט ע' קסא ואילך. מים רבים תרל\"ו ע' קעה."],["214","213","<b>בגולגלתא יתבין תליסר אלפי רבוא עלמין</b>: ראה גם מאמרי אדה\"ז תקע\"א ע' נח. נביאים ע' רנט. בסמוך בפנים ד\"ה ובכ\"ז יובן. תרכ\"ז כאן ע' קא. וש\"נ."],["215","214","<b>שמן הוא בחי' חכ'</b>: ראה מאורי אור מערכת שמן אות מח וביאיר נתיב שם. מאמרי אדה\"א קונטרסים ע' תקמה. וש\"נ. מאמרי אדה\"ז תקע\"א ע' נט. נביאים ע' רסב. סה\"מ תרכ\"ז ותרכ\"ח כאן. תר\"ל ע' שכב. ד\"ה ועמדו רגליו תשח\"י (סה\"מ תשי\"ח ע' 276 ואילך)."],["216","215","<b>וזיתים הוא מקור החכמה</b>: ראה סה\"מ תרכ\"ז ותרכ\"ח כאן. ד\"ה הללו את ה' תשל\"א (סה\"מ מלוקט ח\"א ע' קה). לקוטי שיחות ח\"א ע' 103."],["217","216","<b>מזלות ונוצר ונקה מקור החו\"ב</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. תו\"ח שמות ח\"א לו, א ובהערה 455. אוה\"ת בראשית כרך ו ע' 2084. סה\"מ תרכ\"ז ותרכ\"ח כאן. לקמן מאמר ד\"ה אנכי אנכי על יד הערה 60."],["218","217","<b>שנים זיתים</b>: זכרי' ד, ג."],["219","218","<b>והר. . היותר גבוה</b>: ראה אוה\"ת שם. הנסמן בהערה 215."]]],[2000450078,"<b>וביאור</b> הענין דהנה נודע כי האותיות נק' בשם סוסים<sup data-n=\"220\">219</sup>, ע\"ש כמו שהסוס מוביל את האדם והאדם מנהיגו כרצונו לעלות בהר או לירד למטה, כן ע\"י האותיות מתגלה רצון המנהיגם, וזהו דכתיב כי תרכב על סוסיך שקאי על מ\"ת<sup data-n=\"221\">220</sup> כמ\"ש מזה במ\"א באריכות באר היטיב, ועד\"ז יובן ענין רגליו שהוא ג\"כ ע\"ד ואופן כזה שהרי הרגלי' מובילים את האדם עד\"מ למקום אשר יחפץ ללכת ע\"פ הנהגת הרצון בהם, ולכן מתאר אופן הגילוי דלע\"ל בענין אומרו ועמדו רגליו הם אותיות היותר נעלים על בחי' הר מקור הזיתים הם מזלות דא\"א, שע\"י אותיות אלו היותר עליונים יהיה נמשך בחי' גילוי אלקותו ית' לע\"ל.\n<b>ובכ\"ז</b> יובן שרש ההפרש בין ועלמות אין מספר, לבחי' המוציא במספר צבאם, שכל העולמות שנבראו מהאותיות הם בבחי' מספר וגבול, אבל בחי' האותיות שנשארו למעלה הם בלי מספר, ומ\"ש<sup data-n=\"222\">221</sup> בזהר תליסר אלפי ריבוא עלמין שהם בבחי' מספר, י\"ל בשני דרכים הא' שבאמת אין הכוונה כלל על האותיות שהם בלי מספר רק הכוונה שכמו שיש אותיות שנק' עולמות ואינם בחי' עולמות מוגבלים כ\"א רק אותיות שכשימשכו למטה יהי' מהם עולמות, כמו\"כ עד\"ז למעלה יותר יש בחי' אותיות שנק' ג\"כ עד\"ז עולמות והם בלי מספר ממש, וכמו בחי' אותיות דרגליו הנ\"ל, והדרך הב' שגם באותיות אלו דגלגלתא הם בלי מספר, והיינו שכאשר יומשכו למטה יתהוה מאות אחד עולמות בלי מספר, וכמו ביו\"ד נברא העוה\"ב<sup data-n=\"223\">222</sup>, ובה' נברא העוה\"ז שרק ע\"י ב' אותיות אלו נבראו כלליות עוה\"ב והעוה\"ז הגם שיש בהם מספר עצום, כמו\"כ י\"ל שמאותיות דגלגלתא שהם אותיות היותר גבוהים אם הי' מתהוה מהם עולמות היו בלי מספר ממש, וע' בספר יהושע ישעי'<sup data-n=\"224\">223</sup> ע\"פ בטחו<sup data-n=\"225\">224</sup> כו' כי ביה הוי' צור עולמים, ומכ\"ש מבחי' האותיות דבחי' רגליו כו', וכ\"ז נכלל בשרש ההפרש בין ש' שדי לש' הוי' שבחי' המוציא במספר נמשך מש' שדי, ובחי' אין מספר הוא מש' הוי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שיש ב' בחי' באותיות יש מה שנמשכו להוות עולמות, ויש שנשארו למעלה, והם בלי מספר כמו אותיות דרגליו, או שגם מאותיות שבגלגלתא שכשהי' נמשך אות א' הי' מתהוה ממנו עולמות בלי מספר.</span>\nיג) <b>ועפ\"ז</b> יובן<sup data-n=\"226\">225</sup> ענין מ\"ש וארא כו' באל שדי, דהנה האבות הן הן המרכבה<sup data-n=\"227\">226</sup> שהיו בבחי' מרכבה תמיד ע\"ד והחיות נושאות את",[["220","219","<b>האותיות נק' בשם סוסים</b>: ראה ת\"ז בהקדמה ח, א. מאמרי אדה\"ז תקס\"ט ע' י ובנסמן במ\"מ לשם. תקע\"א ונביאים כאן. סה\"מ תרכ\"ז ותרכ\"ח כאן. תו\"ח בשלח ח\"א קמג, א ובהערה 69."],["221","220","<b>כי תרכב. . מ\"ת</b>: חבקוק ג, ח. ראה שערי אורה נד, א ובהערה 6. תו\"ח בשלח ח\"א קסט, סע\"א ובהערה 262. סה\"מ תרכ\"ז ע' רו. וש\"נ. תרכ\"ט ע' רטו."],["222","221","<b>ומ\"ש</b>: להבא לקמן ראה גם אוה\"ת כאן ע' רכא. סה\"מ תרכ\"ז ותרכ\"ח כאן."],["223","222","<b>ביו\"ד נברא העוה\"ב</b>: מנחות כט, ב."],["224","223","<b>בספר יהושע ישעי'</b>: נדפס באוה\"ת ישעי' ע' רז ואילך."],["225","224","<b>בטחו. . עולמים</b>: ישעי' כו, ד."],["226","225","<b>ועפ\"ז יובן</b>: מכאן ועד סיום המאמר ראה סה\"מ תרכ\"ז ותרכ\"ח."],["227","226","<b>האבות הן הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."]]],[2000450079,"הכסא<sup data-n=\"228\">227</sup> שהם תמיד בבחי' הביטול וזעים מחיל כסא<sup data-n=\"229\">228</sup> עד\"ז הי' האבות בבחי' ביטול תמיד כו', אמנם עכ\"ז היו נבראים ואהוי\"ר של הנברא מצד עצמו א\"י להגיע כ\"א לשרש ומקור הנבראים<sup data-n=\"230\">229</sup>, וזהו בחי' ש' שדי שאמר לעולמו די ולכן וארא כו' באל שדי כו' ומה שלא נתגלה עליהם בבחי' היותר גבוה זהו מחסד ה' עליהם שלא יתבטלו<sup data-n=\"231\">230</sup> ממהותם ע\"ד הושיט הקב\"ה אצבעו<sup data-n=\"232\">231</sup> כו' שמצד עוצם הגילוי נתבטלו המלאכים לכן נגלה עליהם באל שדי, אבל ושמי הוי' לא נודעתי פי' הגם כי ידעו מש' הוי' כמ\"ש אצלם כו\"כ פעמים<sup data-n=\"233\">232</sup> אבל זהו בדרך ידיעה בלבד אבל נודעתי הוא ל' יחוד<sup data-n=\"234\">233</sup> שלא נודעתי להם בבחי' יחוד וחיבור בש' הוי' מטעם הנ\"ל. ואמנם ע\"י מ\"ת נתגלה בחי' ש' הוי' כמ\"ש לכן אמור לבנ\"י<sup data-n=\"235\">234</sup> אני הוי', והוא ע\"י ולקחתי אתכם לי לעם<sup data-n=\"236\">235</sup> פי' לי קאי אדלעיל מיני' דקאמר וידבר כו' אני הוי'<sup data-n=\"237\">236</sup> והייתי לכם לאלקי'<sup data-n=\"238\">237</sup> שבחי' הוי' יהי' לכם לאלקים.\n<b>וביאור</b> הענין דהנה יש ג' בחי' הא' בחי' ש' אלקים בחי' עיר אלקינו<sup data-n=\"239\">238</sup> בחי' אותיות הדבור, ויש בחי' גדול הוי' שמאיר בבחי' עיר אלקינו<sup data-n=\"240\">239</sup> ע\"ד שמש ומגן ה' אלקים<sup data-n=\"241\">240</sup>, ויש בחי' ש' הוי עצמו, דהיינו שיומשך הגילוי מש' הוי' ע\"ד שנמשך מש' אלקי', וזה אינו כמ\"ש במ\"א בענין והי' הוי' לי לאלקים<sup data-n=\"242\">241</sup> שהוי' לגבי ע\"ק כאלקים יחשב, שאז ש' הוי' הוא במדריגת ש' אלקים רק שהוא בחי' היותר נעלה, רק הכוונה שיהי' הגילוי מבחי' ש' הוי' כמו מש' אלקים ועכ\"ז יהי' בחי' ש' הוי'. אך עדיין צ\"ל הלא נת' בלק\"ת בסוף ביאור כי כארץ תוציא צמחה בענין ש' אלקים שאומרים אלקינו<sup data-n=\"243\">242</sup> משא\"כ בכל השמות ותירץ שם שפי' אלקינו אלקי' שלנו שזה א\"א כ\"א בש' אלקים שהיא מדת הצמצום, ואיך ית' על ש' הוי' שלא נאמר בו",[["228","227","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["229","228","<b>וזעים מחיל כסא</b>: ראה פיוט והחיות ב(נוסח הקדושה אשכנז) מוסף לר\"ה."],["230","229","<b>הנברא. . לשרש ומקור הנבראים</b>: ראה גם סה\"מ תרכ\"ט ע' ריא וע' רכב. תרל\"ב ח\"א ע' קיז. וש\"נ. וראה גם תו\"ח בשלח ח\"א רכ, ג."],["231","230","<b>יתבטלו</b>: בסה\"מ תרכ\"ז־ תרכ\"ח כאן ניתוסף: ממציאותן לכן נגלה עליהם בשם שדי בחי' שרש ומקור הגבול שיוכלו לקבל ולא יתבטלו."],["232","231","<b>הושיט הקב\"ה אצבעו</b>: ראה סנהדרין לח, ב. לקמן מאמר ד\"ה אנכי אנכי על יד הערה 21 ואילך. ובהנחה שם על יד הערה 30 ואילך. לקו\"ת תצא לח, ד. מאמרי אדה\"א ויקרא ח\"א ע' קסא. וש\"נ. תו\"ח שמות ח\"א ל, ב ובהערה 127."],["233","232","<b>מש' הוי'. . כו\"כ פעמים</b>: ראה לעיל בהתחלת המאמר."],["234","233","<b>נודעתי הוא ל' יחוד</b>: ראה גם לקו\"ת במדבר א, ב. ב, ד. סידור שחרית לו, ד. סה\"מ תרכ\"ח ע' עד."],["235","234","<b>לכן אמור לבנ\"י</b>: וארא ו, ו."],["236","235","<b>ולקחתי אתכם לי לעם</b>: וארא ו, ז."],["237","236","<b>וידבר. . הוי'</b>: וארא ו, ב."],["238","237","<b>והייתי לכם לאלקי'</b>: וארא ו, ז."],["239","238","<b>ש' אלקים בחי' עיר אלקינו</b>: ראה בהערה הבאה."],["240","239","<b>גדול הוי'. . עיר אלקינו</b>: תהלים מח, ב. ראה זהר פקודי רלה, א. ויקרא ה, א. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ. סה\"מ תר\"ל ע' קעג. ע' רצה. תרל\"ו ח\"ב ע' רפה ואילך. ע' תקלד. לקמן המשך כי תשא על יד הערה 119."],["241","240","<b>שמש ומגן ה' אלקים</b>: תהלים פד, יב."],["242","241","<b>והי' הוי' לי לאלקים</b>: ויצא כח, כא. ראה גם תו\"ח שמות ח\"א מח, ג ובהנסמן שם."],["243","242","<b>בלק\"ת. . ש' אלקים שאומרים אלקינו</b>: נצבים נג, סע\"ג. וראה גם הנסמן במ\"מ לשם. בלק עג, ב. אוה\"ת דברים ע' ב'רסג."]]],[2000450080,"כמו בש' אלקים, אך הענין הוא ע\"פ משארז\"ל עתידים צדיקי' (ועמך כולם צדיקים<sup data-n=\"244\">244</sup> ) שיקראו על שמו של הקב\"ה פרש\"י<sup data-n=\"245\">243</sup> שיהי' שמם הוי', וע\"ד דכתיב ושם העיר מיום הוי' שמה<sup data-n=\"246\">245</sup> וכמארז\"ל טבא למדינתא דשמא כשם מלכא<sup data-n=\"247\">246</sup>, והיינו מה שעכשיו היא עיר אלקינו תהי' לע\"ל בחי' ש' הוי', וא\"כ יובן אומרו על ש' הוי' להיות לכם לאלקים ע\"י שתעלו לקרוא בשמו של הקב\"ה כו', וכ\"ז הוא ע\"י ולקחתי אתכם לי לעם שכ\"ז ע\"י היותינו עמו ע\"י קבלת תומ\"צ שנתלבשו בדברים גשמים, וכמשל החותם שאינו ניכר על האבן טוב כ\"א כשחותמים בשעוה דוקא, כן ע\"י עשיית המצות בקעמ\"ש נמשך להיות גילוי ש' הוי', ואם כי הגילוי הוא מש' הוי' דלתתא מ\"מ הוא גבוה מאד נעלה דהנה עיקר ש' הוי' הוא בחי' היוד<sup data-n=\"248\">247</sup>, וארז\"ל שההפרש בין כינור דבהמק\"ד לימוה\"ש הוא בנימא א' לבד, ושל תחה\"מ יהי' של עשרה נימין<sup data-n=\"249\">248</sup> בחי' ע\"ס בחי' יו\"ד כו'.\n<b>ואמנם</b> בכדי שיהי' מ\"ת הי' צ\"ל תחילה יצי\"מ וזהו והוצאתי אתכם מתחת סבלות מצרים<sup data-n=\"250\">249</sup>, פי' מצרים שכמו שיש מצרים בלעו\"ז כן יש בחי' מצרים בקדושה<sup data-n=\"251\">250</sup> והיינו כל המצרים וגבולים שנמשכים מבחי' ש' שדי שאמר לעולמו די, וזהו להוציא את בנ\"י מאמ\"צ שיצאו מהמצרים וגבולים המגבילי' ומעלימי' ומסתירים, ואל פרעה מלך מצרים הוא בחי' הרצון הזר דנה\"ב<sup data-n=\"252\">251</sup> כו', ולזה הי' טענת משה הן בנ\"י הוא בחי' הנה\"א<sup data-n=\"253\">252</sup> שיש בנש\"י לא שמעו אלי מחמת הקוצר רוח והעבודה קשה שנש\"י מושקעי' במצרים, ואיך ישמעני פרעה הוא בחי' הרצון הזר דנה\"ב כו', ולזה השיבו הקב\"ה במה שדבר אל משה ואל אהרן ויצוום מל' צותא וחיבור<sup data-n=\"254\">253</sup> שחיבר את אהרן אתו, כי אהרן הוא בחי' שושבינא דמטרוניתא<sup data-n=\"255\">254</sup> המעלה",[["244","244","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["245","243","<b>עתידים צדיקי'. . פרש\"י</b>: כ\"ה בכ\"מ ראה ב\"ב עה, ב וברשב\"ם שם. אוה\"ת בראשית כרך ו ס\"ע תתרנה ואילך. דברים ע' י. סה\"מ תרכ\"ט ע' קטו. וש\"נ. תרל\"ב ח\"ב ע' שצב. וש\"נ. תרמ\"ו ע' יח. המשך תער\"ב ח\"ג ע' א'רעו. וראה ג\"כ לקו\"ת בהר מב רע\"ג. ברכה צז, ד. לקו\"ש אגה\"ת כרך יט ע' 410 הערה 19."],["246","245","<b>ושם העיר מיום הוי' שמה</b>: יחזקאל מח, לה."],["247","246","<b>טבא למדינתא דשמא כשם מלכא</b>: איכ\"ר פ\"א, נא. מדרש תהלים כא, ב."],["248","247","<b>עיקר ש' הוי'. . היוד</b>: ראה גם אוה\"ת תצוה כרך ח ע' ג'עט. לקו\"ש כרך כ ע' 270. לקמן המשך אם כסף תלוה על יד הערה 274."],["249","248","<b>כינור. . של עשרה נימין</b>: ערכין יג, ב. ראה גם סידור שחרית לשבת קפט, סע\"ב. פיה\"מ פב, ב."],["250","249","<b>והוצאתי אתכם מתחת סבלות מצרים</b>: וארא ו, ו."],["251","250","<b>מצרים בקדושה</b>: ראה (בנוסף להמצויין בריש המאמר) תו\"א שמות נ, א. וארא נז, ב. נח, ב. תו\"ח שם ח\"א סט, ב. עא, א. סה\"מ תרכ\"ז ע' צ, סע\"א ואילך ובהנסמן בריש המאמר שם."],["252","251","<b>ואל פרעה. . הרצון הזר דנה\"ב</b>: ראה גם אוה\"ת כאן (ע' רד). תצוה שבהערה 253. סה\"מ תרכ\"ז ותרכ\"ח כאן."],["253","252","<b>בנ\"י. . הנה\"א</b>: ראה לקו\"ת תצא לח, א."],["254","253","<b>ויצוום מל' צותא וחיבור</b>: ראה אור תורה עה\"פ (כח, א — בהוצאת קה\"ת). אוה\"ת כאן ע' רז. לעיל ע' קצב. בשלח ע' תסא: ”פי' המגיד נ\"ע\". תצוה כרך ח ע' ג'עז. פלח הרמון שמות (כאן) ע' נג וע' נז בשם המגיד. וראה גם לקמן המשך חייב אדם לברך הערה 63."],["255","254","<b>אהרן. . שושבינא דמטרוניתא</b>: ראה זהר רע\"מ ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. מאמרי אדה\"א שמות ח\"ב ע' שטו וע' שמ."]]],[2000450081,"נש\"י וכמ\"ש ובהעלות אהרן את הנרות<sup data-n=\"256\">255</sup> בחי' נר הוי' נשמת אדם<sup data-n=\"257\">256</sup>, ועי\"ז יוכלו בנ\"י לצאת מן המצרים וגבולי' כו'.\n<b>אך</b> הנה כדי שיתחברו משה ואהרן שהם רחוקים במדריגה שמשה הוא בחי' חכ', ואהרן בינה<sup data-n=\"258\">257</sup> שבחי' בינה היא בריאה שבאצי'<sup data-n=\"259\">258</sup>, א\"כ הם כערך הריחוק אצי' מבריאה, וכמשנ\"ת במ\"א שהגם שאימא עילאה מקננא בבריאה<sup data-n=\"260\">259</sup>, מ\"מ הם רחוקים מאד מבחי' האצי' שאבא<sup data-n=\"261\">260</sup> מקננא באצי'<sup data-n=\"262\">261</sup> כו', ולכן אמר וידבר הוי' כו' שזהו בחי' ש' הוי' דלעילא, וי\"ל גם על שם הוי' דלתתא וכמשנת' לעיל שש' הוי' מקור כל האורות<sup data-n=\"263\">262</sup> דע\"ס דאצי' לכן יכול לחברם כו' בכדי שעי\"ז יצאו ישראל ממצרים שאהרן שושבינא דמטרוניתא שיוכלו לעלות עד שגם הרצון הזר דנה\"ב יצא כו' ומשה הוא שושבינא דמלכא<sup data-n=\"264\">263</sup> הממשיך גילוי אלקותו ית' כו' ונמצא מתורץ כל הדקדוקים הנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> הגילוי להאבות רק בש' שדי בכדי שלא יתבטלו, אבל ש' הוי' לא נודע להם בבחי' יחוד וחיבור, ובמ\"ת גילוי ש' הוי' ע\"י ולקחתי אתכם לי לעם ע\"י תומ\"צ הגשמי' דוקא וצ\"ל יצי\"מ בחי' מצרים וגבולים ולזה<sup data-n=\"265\">264</sup> טען משה מאחר שבנ\"י בחי' נה\"א לא שמעו כ\"ש פרעה רצון הזר דנה\"ב, ולזאת חיבר את אהרן אתו כי אהרן הוא בחי' שושבינא דמטרוניתא המעלה אותם כו' ומשה שושבינא דמלכא הממשיך גילוי אלקות כו'.</span>",[["256","255","<b>ובהעלות אהרן את הנרות</b>: תצוה ל, ח."],["257","256","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["258","257","<b>שמשה. . חכ' ואהרן בינה</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' רמא. אוה\"ת תצוה ע' א'רדעת. סה\"מ תרכ\"ז ותרכ\"ח כאן."],["259","258","<b>בינה היא בריאה שבאצי'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, רפ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקי."],["260","259","<b>שאימא עילאה מקננא בבריאה</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["261","260","<b>שאימא. . רחוקים. . שאבא</b>: ראה גם המשך וככה תרל\"ז פכ\"ט ע' לט. פל\"ג ע' מה."],["262","261","<b>שאבא מקננא באצי'</b>: ראה ת\"ז שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' רלה."],["263","262","<b>שש' הוי' מקור כל האורות</b>: ראה גם לקמן המשך אם כסף תלוה על יד הערה 103. סה\"מ תרל\"ה ח\"א ע' קעג ושם: ”ועיין בד\"ה ואהבת (ך\"ט)\" ראה בהערה לשם. שער היחוה\"א פ\"ד ואילך. סידור נו, ג. תו\"א יתרו סט, ד."],["264","263","<b>ומשה הוא שושבינא דמלכא</b>: זהר רע\"מ ויקרא כ, א. מצורע נג, ב. רע\"מ שופטים ערה, ב. תו\"ח שמות ח\"א יא, ג הערה 510."],["265","264","<b>ולזה</b>: אולי כ\"ה בגוכתי\"ק. וכן הועתק בב."]]],[2000450082,"<h3>אם כסף תלוה כו'</h3>\n<b>בס\"ד</b>\n<b></b>טוב לשמים ולבריות אוכל פירות והקרן קיימת (פרק א-ג)\nאם כסף תלוה את עמי<sup data-n=\"266\">1</sup>, את העני עמך לא תהי' לו כנושה, לא תשימון עליו נשך<sup data-n=\"267\">2</sup>. ולכאורה צ\"ל ענין אומרו את עמי שלפי הענין נראה כמיותר, דהל\"ל אם כסף תלוה את העני עמך. אך הענין הוא דבמד\"ר במקומו משפטים ס\"פ ל\"א<sup data-n=\"268\">3</sup> פי' בפי' את עמי ר\"ל את עמי בחירק תחת העיין שאם תלוה ולא תיקח ממנו ריבית<sup data-n=\"269\">4</sup> את עמי, מה אני איני מוט לעולם, אף אתה אין אתה מוט לעולם, שנאמר כספו לא נתן בנשך כו' עושה אלה לא ימוט לעולם<sup data-n=\"270\">5</sup>. שהמכוון מפסוק זה שיעשה גמ\"ח ממש בלי שום פני' לגרמי', ולכן בפי' לא תהי' לו כנושה פי' במשנה יו\"ד פ\"ה דב\"מ יש ריבית דברים, וגם אמרו שלא יתנהג עמו כעבד לוה לאיש מלוה<sup data-n=\"271\">6</sup> רק שיהי' גמ\"ח ממש ועי\"ז את עמי כו'. וכמארז\"ל במד\"ר במקומו ר\"פ ל\"א ע\"פ אם כסף תלוה הה\"ד טוב איש חונן ומלוה יכלכל דבריו במשפט (תילי' סי' קי\"ב<sup data-n=\"272\">7</sup> ) אין ברי' שאינה חייבת לאלקי' אלא שהוא חנון ורחום מוחל על הראשונים, שנאמר אל תזכר לנו עוונות ראשונים<sup data-n=\"273\">8</sup> ופי' הידי משה דקאי על מ\"ש את עמי כלומר עשה כמו שאני עושה עמך שאני מוחל על חובתך עכ\"ל, וא\"כ ר\"ל שלא תמהר לדחוק פרעון החוב, וא\"כ למדנו שהגמ\"ח הוא דוגמת א\"א שמאריך אף, עד שב\"כ<sup data-n=\"274\">9</sup> יעשה תשובה, כן המלוה יאריך ולא ימהר לדחוק את חובו עד שבהמשך הזמן ישלם לו, ונמצא כי מארז\"ל במד\"ר הנ\"ל אלא מוחל על הראשונים אינו סותר למארז\"ל כל מאן דאמר הקב\"ה וותרן<sup data-n=\"275\">10</sup> יוותרו מיעוהי אלא מאריך אף וגבה דילי' שלבסוף הוא גובה אלא שמאריך אף אולי ישוב בתשובה, וא\"ל גבי דיליה, שפי' מוחל על הראשונים הוא ג\"כ כשעשה תשובה, ועכ\"פ זהו מדת החסד והטוב להלוות ולהמתין, ומה שלבסוף הוא גובה כשאינו שב, זהו לפי שההשפעה מבחי' א\"א נמשך ע\"י חו\"ב וכמ\"ש במ\"א בלק\"ת בד\"ה מי אל כמוך<sup data-n=\"276\">11</sup>,",[["266","1","<b>אם כסף תלוה את עמי</b>: מכאן מתחיל ההמשך הכולל ה מאמרים (י\"ד פרקים), והם: א) ד\"ה זה הכולל פרקים א — ג. ב) ד\"ה על ג\"ד העולם עומד פרקים ד-ח. ג) גומל נפשו איש חסד פרקים ט — יא. ד) טוב איש חונן ומלוה פרקים יב-יג. ה) מלוה ה' חונן דל פרק יד.\nלמאמר זה [פרקים א-ג] ראה אוה\"ת משפטים כרך ח ע' ג'יז. וראה (גם שם בכרך ד ע' א'קסא וע' א'קסו). מאמר ד\"ה זה בסה\"מ תרכ\"ז ע' קלג. וש\"נ־ תרכ\"ט ע' סט־ תרס\"ה ע' קלח. תשכ\"ז. ד\"ה כי תשא תשל\"א (קונט' כ\"ב שבט תנש\"א — סה\"מ מלוקט ח\"ה ע' קפא).\nההמשך נדפס מגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש שנמצא בבוך 1089 ע' טו. ונמצא גם בכת\"י מעתיק הר\"ש סופר בבוך 2083 ע' ז ונרשם לקמן: ב."],["267","2","<b>אם כסף תלוה. . כנושה. . נשך</b>: משפטים כב, כד. להבא להלן בפרק זה ראה אוה\"ת כאן כרך ח ע' ג'יז. כרך ד ס\"ע א'קסה ואילך. סה\"מ תרכ\"ז כאן ע' קלג. (תרכ\"ט ע' סט)."],["268","3","<b>דבמד\"ר. . ס\"פ ל\"א</b>: ראה גם אוה\"ת כאן ע' א'קסא."],["269","4","<b>ריבית</b>: תוקן ע\"פ ב."],["270","5","<b>כספו לא נתן בנשך. . לעולם</b>: תהלים טו, ה."],["271","6","<b>וגם אמרו. . כעבד לוה לאיש מלוה</b>: משלי כב, ז. רמב\"ן ובחיי משפטים כאן."],["272","7","<b>במד\"ר. . טוב איש חונן. . תילי' סי' קי\"ב</b>: ה. ראה גם אוה\"ת כאן ע' א'קנא."],["273","8","<b>אל תזכר לנו עוונות ראשונים</b>: תהלים עט, ח."],["274","9","<b>שב\"כ</b>: שבין כך."],["275","10","<b>כל מאן דאמר הקב\"ה וותרן</b>: ועד\"ז מובא באוה\"ת כאן ע' א'קסו. ע' ג'כה. ראה ב\"ר פס\"ז, ד. וש\"נ. יל\"ש תולדות פכ\"ז, לד (רמז קטו) — מהדורת ירושלים תשל\"ג ע' 561 הערה 14."],["276","11","<b>בלק\"ת בד\"ה מי אל כמוך</b>: ראה שם דרושים לר\"ה סב, א. באוה\"ת כאן ליתא."]]],[2000450083,"ובד\"ה מי אל כמוך שלא נדפס<sup data-n=\"277\">12</sup> בענין לשארית נחלתו, למי שמשים עצמו כשיריים, ועוד שזהו מתכלית הטוב והחסד כדי שלא ימלא לב בני האדם לעשות רע וכמ\"ש במד\"ר בראשית ס\"פ י\"ב<sup data-n=\"278\">13</sup> ע\"פ ביום עשות ה' אלקי' ארץ ושמים, וכן יתנהג האדם להדבק במדותיו ית' מה הוא רחום<sup data-n=\"279\">14</sup> אף אתה הי' רחום להיות איש חונן ומלוה, והיינו ע\"י שיכלכל דבריו במשפט, פי' שיכלכל דבריו בינו לבין עצמו בבחי' משפט כו' שהגם שארז\"ל חייך קודמין<sup data-n=\"280\">15</sup> כו' היינו דוקא חייך ממש אבל המותרות שלך אינן קודמים וכמ\"ש בת\"א פ' בשלח בד\"ה אשירה להוי'<sup data-n=\"281\">16</sup> בפי' ושמרו כו' לעשות צדקה ומשפט שע\"י משפט זה יומשך הצדקה ביתר שאת ועי\"ז מעורר כן למעלה בחי' צדקה וחסד עליון שיומשך במשפט היינו שלא יומשך רק בסטרא דקדושה, ועפ\"ז יתפרש הפסוק טוב איש חונן ומלוה והיינו ע\"י שיכלכל דבריו במשפט, שלא להקדים מותרות שלו לחיות העני והדל כו'. וזהו פי' אם כסף תלוה פי' אם היינו ע\"י שיכלכל דבריו במשפט, שלא יאמר שא\"א לו להלוות, כי נצרך לו הכל לעסקיו למו\"מ להרויח, אך ע\"ז יכלכל דבריו במשפט שההלואה לעני לכדי חייו הכרח יותר מהעסק שלו בשביל מותרות כו', ועי\"ז את עמי כנ\"ל מה אני איני מוט לעולם כך אתה אין אתה מוט לעולם כו'. והש\"ך על התורה<sup data-n=\"282\">17</sup> פי' את עמי עמי במחיצתי, ע\"ד שארז\"ל גבי שמואל ושאול<sup data-n=\"283\">18</sup> שזהו עוד נעלה יותר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> תי' את עמי לכאו' מיותר ופי' במד\"ר את עמי בחיריק, מה אני איני מוט לעולם אף אתה אין אתה מוט לעולם, והמכוון שילווה בלי פני' ולא ידחוק לו את השעה כמו שלמעלה אין כל ברי', ועכ\"ז מאריך אף, ומה שגבה דילי' זהו תכלית החסד והטוב, וזהו טוב איש חונן ומלוה והיינו ע\"י שיכלכל דבריו במשפט לשפוט א\"ע שחיי העני מוכרח יותר מהמותרות שלו כו', ועי\"ז את עמי כפי ב' הפי' כו'.</span>\nב) <b>ולהבין</b> מהו גודל מעלת הגמ\"ח כ\"כ שעי\"ז את עמי כמוני, ועמי במחיצתי, שלכאורה אינו בערך כלל שהנברא יוכל לעלות במעלות כ\"כ להיות כביכול עמו במחיצתו כו'. אך הענין הוא דהנה ארז\"ל במשנה ריש פיאה<sup data-n=\"284\">19</sup> אלו דברים שאדם אוכל פירותיהם בעוה\"ז והקרן קיימת לעוה\"ב כיבוד או\"א וגמ\"ח והבאת שלום כו', ומבואר פ\"ק דקדושין דף מם ע\"א מפני שהוא טוב לשמים וטוב לבריות וי\"ל ענין ב' בחי' טוב אלו זהו ע\"ד יום שלישי שהוכפל בו כי טוב, וטעם",[["277","12","<b>מי אל כמוך שלא נדפס</b>: באוה\"ת כאן ע' א'קסו: וכמ\"ש במ\"א ע\"פ מי אל כמוך נושא עון לשארית נחלתו. ראה גם אוה\"ת מיכה כרך א ע' תצ. סה\"מ תרכ\"ז ע' תמד. תר\"ל ע' רד. תרל\"ד ע' שלו."],["278","13","<b>במד\"ר בראשית ס\"פ י\"ב</b>: טו."],["279","14","<b>מה הוא רחום</b>: ראה לקו\"ת פינחס פ, ג. שבת קלג, ב. ספרי עקב יא, כב."],["280","15","<b>חייך קודמין</b>: ב\"מ סב, א. ראה גם אגה\"ק סט\"ז. מאמרי אדה\"א שמות ח\"א ס\"ע קטו ואילך. תו\"ח בשלח ח\"א קעג, ד ואילך."],["281","16","<b>בת\"א. . אשירה להוי'</b>: סג, סע\"ב. ראה גם אוה\"ת כאן ע' א'קנב."],["282","17","<b>והש\"ך על התורה</b>: עה\"פ. ראה גם אוה\"ת כאן ע' א'קנא."],["283","18","<b>גבי שמואל ושאול</b>: ברכות יב, ב."],["284","19","<b>במשנה ריש פיאה</b>: להבא לקמן ראה אוה\"ת כאן ע' א'קסא."]]],[2000450084,"הכפילות י\"ל לכאו' מפני שכולל חו\"ג שזהו שלימות גדולה ע\"ד יעקב בחיר שבאבות<sup data-n=\"285\">20</sup>, ונק' נחלה בלי מצרים<sup data-n=\"286\">21</sup> כו' ת\"ת שעולה עד הכתר<sup data-n=\"287\">22</sup>, ולכן בכוחו לחבר חו\"ג, ולכן הוכפל בו כי טוב, וכ\"ה בזח\"א פ' בראשית דמ\"ו ע\"א, ונמצא כי ב' פעמים כי טוב זהו ע\"ד טובים השנים מן האחד<sup data-n=\"288\">23</sup> כו' וכשהגבורה נהפך לטוב וחסד ה\"ז טוב יותר, וזהו ע\"י הרחמים, כי חו\"ג הם הפכים זל\"ז שע\"פ מדת החסד אינו מדקדק כלל אם ראוי א\"ל, וע\"פ מדת הגבורה הוא להיפך כמ\"ש הן שמים לא זכו בעיניו, ובקדושיו לא יאמין<sup data-n=\"289\">24</sup> ובמלאכיו ישים<sup data-n=\"290\">25</sup> כו'. ואמנם ע\"י הת\"ת שהוא בחי' הרחמים<sup data-n=\"291\">26</sup> נותן מקום למדת הגבורה פי' לא כמו מדת החסד שטוב לכל ואינו נותן מקום כלל למדת הגבורה, אלא שנותן מקום למדת הגבורה לומר הן אמת כי ע\"פ שרש הדין אינו מגיע לו, מ\"מ צריכים לרחם עליו, ומטה כלפי חסד כו' ועי\"ז נהפכים הגבורות לחסדים ג\"כ כו'.\n<b>ועוי\"ל</b> ענין כפילות ב\"פ כי טוב זהו בחי' יעקב ויוסף וכמ\"ש אלה תולדות יעקב יוסף<sup data-n=\"292\">27</sup> ולכאורה הצ\"ל<sup data-n=\"293\">28</sup> אלה תולדות יעקב ראובן אלא שיעקב ויוסף כחדא חשיבין שיוסף הוא בחי' הגילוים מיעקב, ולכן כל מה שאירע ליעקב אירע ליוסף, והיינו כי יעקב הי' מרכבה למדת הת\"ת<sup data-n=\"294\">29</sup> וכנ\"ל, וכמ\"ש ויקח לו יעקב מקל לבנה<sup data-n=\"295\">30</sup> כו' וערמון שכולל ב' המראות דחו\"ג להיותו בחי' ת\"ת המחבר חו\"ג, ויוסף הוא בחי' צדיק יסוד עולם<sup data-n=\"296\">31</sup> וחשיבין כחדא, ובמ\"א נת' שז\"ע וא\"ו ומילוי וא\"ו<sup data-n=\"297\">32</sup>, וז\"ס קרן ופירות, כי קרן זהו ת\"ת, והפירות מלשון בן פורת יוסף<sup data-n=\"298\">33</sup>, ובזהר ס\"פ בהעלותך דקנ\"ו ע\"א משמע לכאורה כן, אמנם במק\"מ שם פי' קרן יסוד והפירות הם ממל'. וענין יום השלישי י\"ל שזהו כמו ביום השלישי יקימנו ונחי' לפניו שקאי על יוהכ\"פ, כי יחיינו מיומיים<sup data-n=\"299\">34</sup> ז\"ע ב' ימים דר\"ה וביום השלישי זהו יוהכ\"פ שבו ניתנו לוחות",[["285","20","<b>יעקב בחיר שבאבות</b>: ראה ע\"ח שער לאה ורחל של\"ב, פ\"ב. לקו\"ת להאריז\"ל תולדות כז, כה. לקו\"ש ויחי כרך ג ע' 832 הערה 11."],["286","21","<b>נחלה בלי מצרים</b>: שבת קיח, סע\"א."],["287","22","<b>ת\"ת שעולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב). מאמרי אדה\"ז הקצרים ע' תקעט."],["288","23","<b>טובים השנים מן האחד</b>: קהלת ד, ט."],["289","24","<b>הן שמים. . ובקדושיו לא יאמין</b>: איוב טו, טו [ ושם: א) בהיפך הסדר. ב) ושמים — ראה תו\"ח וירא קד, ב הערה 18. לקמן (בחלק ההנחות) הנחה ד\"ה ישמח משה ובהערה 15]."],["290","25","<b>ובמלאכיו ישים</b>: איוב ד, יח."],["291","26","<b>הת\"ת. . הרחמים</b>: ראה זח\"א בהשמטות רנא, רע\"ב. פרדס שעה\"כ שכ\"ג, פ\"כ מערכת רחמים."],["292","27","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב. ראה ב\"ר פפ\"ד, ו. אוה\"ת וישב כרך ה ע' תתק ואילך. סה\"מ תרכ\"ז ע' ריט. וש\"נ."],["293","28","<b>הצ\"ל</b>: הי' צ\"ל."],["294","29","<b>יעקב. . הת\"ת</b>: בנוסף להנ\"ל. ראה זהר סתרי תורה ויצא קנז, ב. ח\"ג תוספות שב, א."],["295","30","<b>ויקח לו יעקב מקל לבנה</b>: ויצא ל, לז. ראה זהר ויצא קסא, ב. אוה\"ת ויצא רכא, ב. ביאוה\"ז להצ\"צ כרך ב ס\"ע תשב."],["296","31","<b>ויוסף. . צדיק יסוד עולם</b>: ראה גם אוה\"ת בראשית כרך ג ע' 1110. לקמן המשך חייב אדם לברך על יד הערה 329."],["297","32","<b>וא\"ו ומילוי וא\"ו</b>: ראה לקו\"ת חוקת ס, ד. אוה\"ת בהעלותך ע' שפז. ראה ע' תשעו. סה\"מ תרכ\"ט ע' כז. וש\"נ. ע' שפו."],["298","33","<b>בן פורת יוסף</b>: ויחי מט, כב."],["299","34","<b>ביום השלישי יקימנו. . יחיינו מיומים</b>: הושע ו, ב. ראה לקו\"ת ר\"ה סג, סע\"ב. אוה\"ת בשלח ע' תקעו. ראה ע' תרסא. ואתחנן ע' רלז. ר\"ה ע' א'תיג."]]],[2000450085,"האחרונות<sup data-n=\"300\">35</sup> דכתיב בהם למען יטב לך<sup data-n=\"301\">36</sup>, וגם התו' נק' טוב כמ\"ש כי לקח טוב נתתי לכם<sup data-n=\"302\">37</sup>, ולוחות הראשונות ניתנו ג\"כ בג' דהיינו בחדש השלישי<sup data-n=\"303\">38</sup>, ולוחות האחרונות ניתנו ביוהכ\"פ שנק' ג\"כ שלישי כמ\"ש ביום השלישי יקימנו, וזהו שביום השלישי הוכפל בו כי טוב ע\"ש ב' בחי' טוב דלוחות ראשונות ולוחות אחרונות כו'.\n<b>ושרש</b> ענין ביום השלישי, דהנה יחיינו מיומיים זהו ב' בחי' סוכ\"ע וממכ\"ע והם המאירים בב' ימים דר\"ה וע' מ\"ש במ\"א בביאור ואהי' אצלו אמון<sup data-n=\"304\">39</sup> בענין שעשועים יום יום, אבל ביום השלישי זהו בחי' שלמעלה מסוכ\"ע וממכ\"ע והוא המאיר ביוהכ\"פ, ומאחר שבכל שנה כן הוא כ\"ש בתחילת הבריאה שהוא ראש לכל השנים, ולכן בו נאמר ג\"כ ב\"פ כי טוב, שבחי' טוב לשמים וטוב לבריות דגמ\"ח הוא נגד ב\"פ כי טוב אלו שנאמר ביום השלישי, דהנה טוב לשמים לכאורה י\"ל שזהו בחי' צ\"ע בחי' יסוד אבא שהוא טוב<sup data-n=\"305\">40</sup> ומשפיע לז\"א שנק' שמים<sup data-n=\"306\">41</sup>, וכנודע שהמדות עליונות נק' שמים<sup data-n=\"307\">42</sup>, טוב לבריות יסוד ז\"א המאיר לבחי' מל' מקור דבי\"ע, ועוי\"ל שמים הוא ר\"ת שם מים<sup data-n=\"308\">43</sup> שקאי על החכ' דאצי' שנק' מים<sup data-n=\"309\">44</sup> וא\"כ טוב לשמים היינו ההמשכה מלמעלה מאצי' באצי', וטוב לבריות היינו ההמשכה מאצי' לבי\"ע כו'.\n<span data-k=\"ks\"><b>קיצור.</b> מעלת גמ\"ח לפי שהוא טוב לשמים וטוב לבריות ע\"ד יום ג' שהוכפל בו כי טוב, ת\"ת שעולה כו' וכולל חו\"ג, וב\"פ כי טוב יעקב ויוסף (ולכן יעקב נולד מהול<sup data-n=\"310\">45</sup> ע\"ד דכתי' במשה כי טוב הוא שנולד מהול<sup data-n=\"311\">46</sup>, ונודע כי משה מלגאו<sup data-n=\"312\">47</sup> יעקב מלבר), וענין יום השלישי ע\"ד ביום השלישי יקימנו דיוהכ\"פ וב' פעמים טוב זהו טוב דתורה לוחות הראשונות והאחרונות, והוא למעלה מסוכ\"ע וממכ\"ע ולכן בו נאמר ב\"פ טוב שהוא ההשפעה מיס\"א לז\"א ומז\"א למל', או מלמעלה מאצי' לאצי' ומאצי' לבי\"ע כו'.</span>",[["300","35","<b>יוהכ\"פ. . לוחות האחרונות</b>: ראה תענית ל, ב. רש\"י תשא לד, כט. הוספות לשו\"ע אדה\"ז חאו\"ח רסתקפ\"א (ע' תרפב)."],["301","36","<b>למען יטב לך</b>: ואתחנן ה, טז (ושם: ולמען ייטב)."],["302","37","<b>כי לקח טוב נתתי לכם</b>: משלי, ד, ב."],["303","38","<b>ולוחות הראשונות. . בחדש השלישי</b>: יתרו יט, א ואילך."],["304","39","<b>בביאור ואהי' אצלו אמון</b>: ראה לקו\"ת במדבר יט, סע\"ג ואילך."],["305","40","<b>יסוד. . טוב</b>: ראה זהר נח ס, א. מאמרי אדה\"א קונטרסים ע' רכד. וש\"נ."],["306","41","<b>לז\"א שנק' שמים</b>: ראה זהר בשלח סב, ב. אד\"ז האזינו רפח, א. סה\"מ תרכ\"ז ע' קעא. תרכ\"ט ע' לב. לקמן המשך חייב אדם לברך רפ\"ה."],["307","42","<b>שהמדות. . שמים</b>: ראה גם שער היחוד קי, ב ובהערה 24."],["308","43","<b>שמים. . שם מים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח. לקמן מאמר ד\"ה ואשא אתכם על יד הערות 40-41."],["309","44","<b>החכ'. . מים</b>: ראה תניא פ\"ג ובמ\"מ הגהות והע\"ק שם. תו\"ח בשלח ח\"א קמג, ב ובהערה 91."],["310","45","<b>יעקב נולד מהול</b>: אבות דר\"נ פ\"ב, ה. ב\"ר פפ\"ד, ו. תנחומא נח ה. מקץ ג."],["311","46","<b>כי טוב הוא שנולד מהול</b>: שמות ב, ב. סוטה יב, א."],["312","47","<b>משה מלגאו</b>: ת\"ז תי\"ג כט, א."]]],[2000450086,"ג) <b>ועפ\"ז</b> יובן שרש ענין מה שהקרן קיימת לעוה\"ב, ורק פירותיהם אדם אוכל בעוה\"ז, דהנה שכר מצוה בהאי עלמא ליכא<sup data-n=\"313\">48</sup>, והענין יובן ע\"פ מארז\"ל שית שני<sup data-n=\"314\">49</sup> הוה עלמא וחד חרוב<sup data-n=\"315\">50</sup>, ולכאורה צ\"ל הלא אלף השביעי הוא יום שכולו שבת<sup data-n=\"316\">51</sup> ומנוחה לחיי העולמים, כמארז\"ל במשנה בשבת מה הי' אומרים<sup data-n=\"317\">52</sup> מזמור שיר ליום השבת<sup data-n=\"318\">53</sup> ליום שכולו שבת ומנוחה לחיי העולמים, וא\"כ איך אמר עליו וחד חרוב כו', אלא שפי' וחד חרוב<sup data-n=\"319\">54</sup> הוא מבחי' ההנהגה הגשמיית דעכשיו הנמשך ע\"י בחי' ק\"נ, וע\"ד אמלאה החריבה לא נתמלאה צור<sup data-n=\"320\">55</sup> כו', לכן לע\"ל בחי' יום שכולו שבת יהי' בחי' חד חרוב מהנהגה השפעת גשמיית העוה\"ז, וע\"ד רחב\"ד שכל העולם כולו ניזון בשביל חנינא בני, וחנינא בני די לו בקב חרובין<sup data-n=\"321\">56</sup> מע\"ש לע\"ש, שהענין הוא שלפי רוב צדקתו לא הי' יכול להיות נמשך שכרו בעוה\"ז ע\"ד הגילוי דלע\"ל בחי' חד חרוב כנ\"ל עד\"ז הי' רחב\"ד מסתפק בקב חרובין שלשון נופל על לשון מעין ודוגמא דלע\"ל, והגם שכל העולם הי' ניזון בשבילו בעושר והשפעה הרבה, אמנם דעת לנבון נקל שאינו דומה בחי' ההשפעה שבזכותו לזולתו לבחי' הזכות לו בעצמו, ולפי עוצם מעלת זכותו לא הי' באפשר להתלבש בגשמיות בהשפעת שתחת ק\"נ כו', וע\"ד כמו המן שהי' רוחני לחם אבירים שנבלע באיברים<sup data-n=\"322\">57</sup> מפני כי שרשו הי' מבחי' טל כמ\"ש וברדת הטל כו' ירד המן<sup data-n=\"323\">58</sup>, ולכן הי' רוחני כמ\"ש מן הוא כי לא ידעו מה הוא<sup data-n=\"324\">59</sup> שהי' מבחי' מ\"ה, ועד\"ז בדקות יותר בחי' ההשפעה דלע\"ל בבחי' הגשמיות יהי' חד חרוב, כ\"א שכל העולם יהי' ניזון מרוחניות המדריגות היותר נעלים וכמארז\"ל עוה\"ב אין בו לא אכילה ולא שתי' אלא כו' מזיו השכינה<sup data-n=\"325\">60</sup>, וכמשנ\"ת מזה במ\"א באריכות, ע' בד\"ה אלה תולדות נח<sup data-n=\"326\">61</sup>, וז\"ע חד חרוב דלע\"ל, ועד\"ז יובן בדברים שאדם אוכל פירותיהם בעוה\"ז והקרן קיימת, להיות כי מעלתם גבוה מאד לכן הקרן א\"א שיומשך בהשפעת גשמיית בעוה\"ז שעוברים דרך ק\"נ, וכנודע שיש מסך המבדיל בין קדש לחול<sup data-n=\"327\">62</sup>, רק מהפירות נמשך בעוה\"ז.",[["313","48","<b>שכר מצוה בהאי עלמא ליכא</b>: קדושין לט, ב. ראה מאמרי אדה\"א שמות ח\"ב ע' שטז. וש\"נ. קונטרסים ע' שיא ואילך."],["314","49","<b>שית שני</b>: ב: שית אלפי שני, ותיבת אלפי ניתוסף בין השיטין."],["315","50","<b>שית. . וחד חרוב</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["316","51","<b>אלף השביעי. . שכולו שבת</b>: ראה גם תו\"ח בשלח ח\"א רכא, ב ובהערה 557."],["317","52","<b>בשבת מה הי' אומרים</b>: ראה סוף תמיד."],["318","53","<b>מזמור שיר ליום השבת</b>: תהלים צב, א."],["319","54","<b>שפי' וחד חרוב</b>: ראה גם בענין וחד חרוב אוה\"ת (יהל אור) תהלים ע' תשכ ואילך במהדורת קה\"ת תשד\"מ. המשך מים רבים תרל\"ו פק\"ס. ח\"ב ע' רמג. סה\"מ תרנ\"א ע' סב. תו\"ח שמות ח\"א כג, א הערה 950."],["320","55","<b>אמלאה החריבה לא נתמלאה צור</b>: יחזקאל כו, ב (ושם: החרבה). רש\"י תולדות כה, כג."],["321","56","<b>שכל העולם. . בקב חרובין</b>: תענית כד, סע\"ב."],["322","57","<b>המן. . לחם אבירים שנבלע באיברים</b>: תהלים עח, כה. ראה יומא עה, ב."],["323","58","<b>וברדת. . ירד המן</b>: בהעלותך יא, ט. ראה גם תו\"ח בשלח ח\"א רי, ב."],["324","59","<b>מן הוא כי לא ידעו מה הוא</b>: בשלח טז, טו."],["325","60","<b>עוה\"ב. . מזיו השכינה</b>: ברכות יז, א."],["326","61","<b>אלה תולדות נח</b>: בסה\"מ תרנ\"א ע' סג: רל\"ז. קרוב לסוף ההמשך פ' ח\"ש (נמצא בבוך 486 ל, א ואילך)."],["327","62","<b>מסך המבדיל בין קדש לחול</b>: ראה תו\"א לך יב, ב."]]],[2000450087,"<b>ועפ\"ז</b> יובן ענין אמרם שכר מצוה בהאי עלמא ליכא, כי מאחר שכל השפעות עוה\"ז נמשכים ע\"י ק\"נ א\"א שיומשך לשם שכר מצוה שהוא מבחי' כתר הכללי א\"ק, כ\"א הקרן קיימת לעוה\"ב שאז יתברר ק\"נ לגמרי כמ\"ש בסש\"ב פל\"ז, ומה שיש מצות שאוכלים פירותיהם בעוה\"ז, זה אינו שכר המצוה עצמה שמבחי' כתר וא\"ק, כ\"א מבחי' אצי' וחכמה, שמבחי' זו יוכל להתלבש ההשפעה גם ע\"י ק\"נ, וכמו באברהם שהי' נביא גם קודם המילה, שמבחי' אצי' מתלבש בעשייה ג\"כ גם במקום שיש זלעו\"ז, משא\"כ שיהי' גילוי בחי' א\"ק זהו ע\"י כריתות הערלה שמק\"נ אזי דוקא יוכל להיות גילוי זה כמ\"ש מזה בסידור ובלק\"ת בד\"ה למנצח על השמינית<sup data-n=\"328\">63</sup>.\n<b>ואמנם</b> בחי' פירותיהם בעוה\"ז נמשך דוקא מדברים שהם טוב לשמים וטוב לבריות ע\"ד ב\"פ כי טוב כנ\"ל, ולכאורה הרי לפמ\"ש שפירותיהם בעוה\"ז נמשך רק מאצי', ולפי הנראה מפשט המצוה<sup data-n=\"329\">64</sup> מצות אלו גבהו מעלתן<sup data-n=\"330\">65</sup> משאר כל המצות ששכר מצוה בהאי עלמא ליכא, והענין הוא כי ב' עולמות העוה\"ז והעוה\"ב שרשם מב' שמות הוי' כמ\"ש בזח\"א ויצא דקנח\"ב, והיינו שההשפעה בעוה\"ז נמשך מש' הוי' שבאצי', ולע\"ל יתגלה ש' הוי' דלעילא שבעת\"י, וזהו שכר מצוה בהאי עלמא ליכא, פי' שכר מצוה היינו ההמשכה מש' הוי' דלעילא בהאי עלמא ליכא, כי הוי' הוי' ופסיק טעמא בנייהו<sup data-n=\"331\">66</sup>, והיינו מטעם הנ\"ל דש' הוי' דלעילא שהוא בכתר וא\"ק א\"א כלל שיתלבש בעוה\"ז משום שק\"נ היא מסך מבדיל וא\"א להיות בה גילוי מבחי' זו, ועסד\"ה וידעת היום דרוש הראשון שבלק\"ת וסוף ביאור כי על כל כבוד חופה<sup data-n=\"332\">67</sup>, אך ע\"י המצות שהם טוב לשמים וטוב לבריות עי\"ז מחברים ב' ההויות כמ\"ש בת\"א בד\"ה כי אתה נרי<sup data-n=\"333\">68</sup> גבי והוי' יגיה חשכי, ובהביאור שם, לכן עי\"ז נמשך פירותיהם בעוה\"ז, ומ\"ש אם בחוקתי תלכו כו' ונתתי גשמיכם בעתם<sup data-n=\"334\">69</sup> משמע ששכר המצות נמשך בעוה\"ז, הנה באמת במד\"ר פ' עקב משמע שמכל המצות<sup data-n=\"335\">70</sup> אוכלין הפירות בעוה\"ז, אמנם לפי מארז\"ל ששכר מצה בהאי עלמא ליכא ואלו דברים דוקא כו' פירותיהם כו' י\"ל כמ\"ש רש\"י ע\"פ אם בחקתי תלכו אם תהיו עמלים בתורה שזהו מדברים שאדם אוכל פירותיהם שהרי ות\"ת כנגד כולם, ומכ\"ז יובן ענין את עמי ע\"י גמ\"ח שהרי מאחר שעי\"ז מחברים ב' ההויות א\"כ מובן ענין את עמי כו'.",[["328","63","<b>באברהם שהי' נביא גם קודם המילה. . על השמינית</b>: ראה לך יב, א. ועוד. סידור שער המילה קמ סע\"ב ואילך. לקו\"ת תזריע כא, א."],["329","64","<b>המצוה</b>: אוצ\"ל: המשנה."],["330","65","<b>מצות אלו גבהו מעלתן</b>: ראה גם אוה\"ת כאן ע' א'קסג. מאמרי אדה\"א קונטרסים ע' שכה — שכז."],["331","66","<b>מב' שמות הוי'. . ופסיק טעמא בנייהו</b>: ראה (זהר ויצא שנסמן לעיל בפנים) לקמן הערות 320-319."],["332","67","<b>וידעת היום. . שבלק\"ת וסוף. . כבוד חופה</b>: ואתחנן ד, ד. שה\"ש מח, א."],["333","68","<b>בת\"א בד\"ה כי אתה נרי</b>: מקץ מא, א. ג. סידור שער המילה קמ סע\"ב ואילך. לקו\"ת תזריע כא, א."],["334","69","<b>אם בחוקתי. . ונתתי גשמיכם בעתם</b>: בחוקותי כו, ג. ד."],["335","70","<b>במד\"ר פ' עקב. . שמכל המצות</b>: בתחילתו."]]],[2000450088,"<span data-k=\"ks\"><b>קיצור.</b> קרן קיימת שכר מצוה בהאי עלמא ליכא ע\"ד חד חרוב דלע\"ל, קב חרובין, מן, עוה\"ב אין לא אכילה כו' כי מאחר שבעוה\"ז עובר דרך ק\"נ מסך מבדיל א\"א להיות ההמשכה מבחי' ש' הוי' דלעילא, רק ע\"י המצות שאוכלים פירותיהם בעוה\"ז מחברים ב' ההויות כו' ועי\"ז מובן איך שע\"י גמ\"ח את עמי כו'.</span>"],[2000450089,"<h3>על ג\"ד העולם עומד כו' אופן היתר עיסקא כו'</h3>\n<b></b>ענין הקרבן כו' אש כו' ג' עטרות (ד-ה)\nד) <b>ואמנם</b><sup data-n=\"336\">71</sup> עדיין צ\"ל למה לא הרחיקו רז\"ל מאיסור הריבית לגמרי והתירו היתר עיסקא<sup data-n=\"337\">72</sup> פלגא באגרא ופלגא בהפסד, ושיקבל הלוה מהמלוה שכר עמלו, או שיקבל המלוה תילתא באגרא ופלגא בהפסד, או תילתא באגרא ותרי תילתא בהפסד, כפי האופן שיתפשרו בניהם, ולמה לא הרחיקו לגמרי מאיסור ריבות, אך הענין הוא דהנה בעה\"כ של הסה\"ד הביא בשם שמ\"ל<sup data-n=\"338\">73</sup> שירידת הנשמה בגוף נק' בשם עיסקא שהיא פלגא מלוה ופלגא פקדון, וכן בירידת הנשמה בגוף יש ב' בחי' היינו מה שהירידה צורך עליה<sup data-n=\"339\">74</sup> זהו השכר להנשמה, ויש מזה ריוח גם להנותן כמ\"ש הבו גודל לאלקינו<sup data-n=\"340\">75</sup> וארז\"ל במד\"ר איכה בזמן שישראל<sup data-n=\"341\">76</sup> עושי' רצוש\"מ מוסיפי' כח בגבורה של מעלה כמד\"א באלקים נעשה חיל<sup data-n=\"342\">77</sup>, ולהבין זה צ\"ל מארז\"ל על שלשה דברים<sup data-n=\"343\">78</sup> העולם עומד על התורה ועל העבודה ועל גמ\"ח, עבודה הוא בחי' עבודת הקרבנות<sup data-n=\"344\">79</sup>, וצ\"ל מ\"ש בהושע ס\"ו פ\"ו כי חסד חפצתי ולא זבח שזהו לכאורה היפך האמור בכל התורה מענין הקרבנות וספר ויקרא מתחיל בקרבנות אדם כי יקריב<sup data-n=\"345\">80</sup> ורוב ס' ויקרא הוא פרשיות הקרבנות והרבה בס' במדבר",[["336","71","<b>ואמנם</b>: ברשימת המאמרים שמופיע בריש הבוך נרשם כאן מאמר ד\"ה: על ג' דברים העולם עומד (לפרקים ד — ח), היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם פתיחה זו נרשמה בפ\"ע גם ע\"י כ\"ק אדמו\"ר מהר\"ש.\nלמאמר זה ראה אוה\"ת משפטים כרך ח ע' ג'ל וע' ג'יח. סה\"מ תרכ\"ו ס\"ע פ ואילך. תרכ\"ז ע' קלג ואילך. תרכ\"ט ע' סט ואילך. תרס\"ה ע' קלט. תרח\"ץ ע' רכז. תרצ\"ט ע' 238. תש\"ט ע' 28. מאמר ד\"ה ויאמר לו יהונתן מחר חודש ש\"פ משפטים תשכ\"ב. ד\"ה אם כסף תלוה תשכ\"ז. ד\"ה כי תשא תשל\"א (קונט' כ\"ב שבט תנש\"א — סה\"מ מלוקט ח\"ה ע' קפא)."],["337","72","<b>היתר עיסקא</b>: ראה ב\"מ סח, סע\"ב ואילך. שו\"ע אדה\"ז הל' רבית סל\"ח. אוה\"ת כאן ר\"ע א'קנו. ע' א'קע. (כרך ח) ע' ג'ל. תרכ\"ט ע' קפו. סה\"מ תש\"ט ע' 28. וש\"נ."],["338","73","<b>בעה\"כ של הסה\"ד.. שמ\"ל</b>: בס' ערכי הכנויים של בעל המחבר ס' סדר הדורות מערכת הלואה אות נשמה ומערכת עסקי הביא בשם ספר שמנה לחמו — לר' אשר אנשיל מפרמישלא דעסא תס\"א — ח\"ב הספד י\"ב (כד, א). אוה\"ת כאן ע' א'קע. תרכ\"ז ס\"ע קלג ואילך. תרכ\"ו ס\"ע פ ”בערה\"כ. . בשם התיקונים\". תרכ\"ט ע' קפה ”בשם ספר [שמ\"ל] שהביא בשם תיקונים\". אבל כנראה הכוונה לספר קרבן שבת הובא בעה\"כ שם [אבל שם הובא ”הלוואה\"]."],["339","74","<b>שהירידה צורך עליה</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["340","75","<b>הבו גודל לאלקינו</b>: האזינו לג, ב."],["341","76","<b>במד\"ר איכה בזמן שישראל</b>: פ\"א, לג (הובא לקמן פי\"ב בפנים על יד הערות 238-9). ראה אוה\"ת איוב כרך א ע' תרעט ואילך."],["342","77","<b>באלקים נעשה חיל</b>: תהלים ס, יד."],["343","78","<b>על שלשה דברים</b>: אבות פ\"א, מ\"ב. ראה גם מאמר ד\"ה אם כסף תלוה תשכ\"ז."],["344","79","<b>עבודה. . הקרבנות</b>: ראה מפרשי המשנה שם. בסה\"מ תרס\"ה כאן: ”וכמ\"ש [שמות ג, יב] בהוציאך כו' תעבדון את האלקי' על ההר הזה שנק' קרבנות עבודה\". ובהמשך תער\"ב ח\"ג ס\"ע א'ריח מציין ע\"ז: ”ובמדרש\". ראה ב\"ר פט\"ז, ד [ה] בסופו."],["345","80","<b>אדם כי יקריב</b>: ויקרא א, ב."]]],[2000450090,"ובמקומות רבים בתורה, וכל עיקר בהמק\"ד הי' בשביל הקרבת הקרבנות, ואיך אומר כי חסד חפצתי ולא זבח. אך הענין הוא דהנה שרש ענין הקרבנות<sup data-n=\"346\">81</sup> שמקריבין בהמה ע\"ג המזבח, ועי\"ז שמקריבין אותה עי\"ז מתעלית לשרשה ומקורה, כי הנה שרש חיות כל הבהמות נמשכים מבחי' פני שור<sup data-n=\"347\">82</sup> שבמרכבה, כי ד' חיות המרכבה הם שרש כל הנבראים שלמטה, פני ארי' הוא שרש חיות של כל החיות, ופני שור הוא שרש ומקור חיות כל הבהמות, פני נשר הוא שרש מקור חיות כל העופות<sup data-n=\"348\">83</sup>, פני אדם שרש ומקור נפש השכליות<sup data-n=\"349\">84</sup>, והגם שבחי' נפש הבהמה מרוחק מאד מבחי' פני שור שהוא מרכבה, וצ\"ל ריבוי רבבות מדריגות בניהם, מ\"מ הנה הוא שרש ומקור לבחי' נפש הבהמה רק שנמשכה ע\"י ריבוי רבבות השתלשלות עד שנעשה חיות לבהמה שהוא בחי' נפש הבהמה הגשמיות, וכמארז\"ל אין לך עשב<sup data-n=\"350\">85</sup> מלמטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל, וכ\"ש אילנות, שבודאי אין ערוך העשב והאילן הגשמי למזלו ברקיע המכה בו ואומר לו גדל, ומ\"מ הנה הוא שרש ומקור להעשב הגשמי שיצמח מקטנות לגדלות, והאילן הגשמי יוציא פירות, ועד\"ז יובן בענין בחי' פני שור שבמרכבה שהגם שנפש הבהמה רחוקה מאד בתכלית הריחוק מבחי' פני שור כו' עכ\"ז הנה הוא שרש ומקור לנפש הבהמה, והנה ע\"י שמקריבין את הבהמה ע\"ג המזבח עי\"ז מתעלית לשרשה<sup data-n=\"351\">86</sup>, היינו בחי' שרש שרשה בחי' פני שור שבמרכבה, ולהיות כי ד' פנים לאחת<sup data-n=\"352\">87</sup> עי\"ז מתכללת אח\"כ בבחי' פני ארי' שז\"ע ארי' דאכיל קרבנין<sup data-n=\"353\">88</sup> כו' שהיא בחי' לאכללא שמאלא בימינא<sup data-n=\"354\">89</sup> שמתכלל הקרבן שעולה לשרש שרשו בבחי' פני שור שמהשמאל בבחי' פני ארי' שאל הימין, כמ\"ש בלק\"ת<sup data-n=\"355\">90</sup> בד\"ה וארי' כבקר יאכל תבן די\"א א', וע' בזהר בהקדמה דף וא\"ו ע\"ב ובמק\"מ שם מענין ארי' דאכיל קרבנין, ואינו נכלל בבחי' פני אדם הגם כי ד' פנים לא' מפני כי ארי' ושור שניהם הם שרש הבע\"ח, משא\"כ פני אדם שרש נפש השכלית שבמדבר כו'.",[["346","81","<b>שרש ענין הקרבנות</b>: בהבא לקמן ראה (בנוסף להמצויין בהערה 71) לקו\"ת שה\"ש כח, ג. סה\"מ תרכ\"ט ע' קי."],["347","82","<b>חיות כל הבהמות. . פני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. טעמי המצות להרח\"ו ר\"פ ויקרא וציין לזהר פ' פינחס [רמ, ב. ומ\"ש באור החמה שם — ראה אגרות קודש כ\"ק אדמו\"ר מהר\"ש ע' צב ואילך]. לעיל המשך וידבר וגו' ויצוום על יד הערה 156 וש\"נ."],["348","83","<b>פני ארי'. . החיות. . פני נשר. . העופות</b>: ראה טעמי המצות שם. אור החיים אחרי יז, יד. לעיל המשך וידבר וגו' ויצוום ובהערות 157־ 154."],["349","84","<b>פני אדם. . נפש השכליות</b>: ראה טעמי המצות ואוה\"ח שם. מאמרי אדה\"א דברים ח\"ד ס\"ע א'רו ואילך. לקו\"ת נשא כח, סע\"ג."],["350","85","<b>אין לך עשב</b>: ראה אוה\"ת וארא כרך ח ע' ב'תתפג שמציין: הובא בר\"ח פ\"ה משער האהבה והוא במ\"ר בראשי' פ\"י[, ו]. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג."],["351","86","<b>שמקריבין את הבהמה. . לשרשה</b>: ראה זהר פינחס רמ, ב. סה\"מ תרכ\"ז ע' קמה ואילך ובהנסמן שם."],["352","87","<b>ד' פנים לאחת</b>: יחזקאל א, י."],["353","88","<b>ארי' דאכיל קרבנין</b>: ראה (בנוסף להמצויין בסמוך בפנים) מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שער האמונה עט, ב הערה 13."],["354","89","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["355","90","<b>בלק\"ת</b>: במדבר."]]],[2000450091,"<span data-k=\"ks\"><b>קיצור.</b> למה התירו היתר עיסקא ולא הרחיקו לגמרי מריבית, ירידת הנשמה בגוף זהו עסקא, ויובן בהקדם מארז\"ל על ג' דברים העולם עומד כו' עבודה עבודת הקרבנות, וצ\"ל מ\"ש חסד חפצתי, הלא כל התורה מלא מקרבנות, ענין הקרבן שע\"י הקרבנות מתעלית הבהמה לשרש שרשה בחי' פני שור ואח\"כ נכללת בבחי' ארי' שז\"ע ארי' דאכיל קרבנין.</span>\nה) <b>והנה</b> ע\"י העלאת הקרבן לבחי' פני שור שבמרכבה מתעלה אח\"כ עוד יותר, דהנה כתיב והחיות נושאות את הכסא<sup data-n=\"356\">91</sup>, שנושאים את הכסא עם בחי' כמראה אדם שעל דמות הכסא, כמ\"ש ועל דמות הכסא דמות כמראה אדם עליו מלמעלה<sup data-n=\"357\">92</sup>, ונושאים ומגביהים את בחי' אדם לבחי' אוא\"ס שכי לא אדם<sup data-n=\"358\">93</sup> הוא<sup data-n=\"359\">94</sup>, וזהו ע\"י קבלתם את הקרבן שרזא דקורבנא עולה עד רזא דא\"ס<sup data-n=\"360\">95</sup>, ולכן ע\"י העלאת הקרבן מנשאים החיות את הכסא עם דמות כמראה אדם שעל הכסא לבחי' אוא\"ס ב\"ה שכי לא אדם הוא, ולכאורה צ\"ל הלא אין לו דמות הגוף<sup data-n=\"361\">96</sup> ולא גוף ומה\"ע דמות כמראה אדם, אך הענין הוא דפי' אדם הוא בחי' ג' קווין שהוא בחי' חסד דרועא ימינא, גבורה דרועא שמאלא ת\"ת גופא כמ\"ש בת\"ז<sup data-n=\"362\">97</sup>, ובכלליות הע\"ס בד\"כ ג' קווין הם חח\"ן מימין בג\"ה משמאל דת\"י<sup data-n=\"363\">98</sup> באמצע שהם ע\"ס שז\"ע בחי' כמראה אדם כו', אמנם הנה כ\"ז הוא רק לאחזאה איך מתנהג עלמא, אבל לאו דאית לך צדק ידיעא כו', ולאו מכל אלין מדות כלל<sup data-n=\"364\">99</sup>, כי אין ערוך אליו כלל, וע\"י העלאת הקרבן מעלים ומנשאים החיות את בחי' כמראה אדם זה לבחי' אא\"ס דלאו מכל אלין מדות כלל, וע\"י העלאה זו נמשך תוס' אור בע\"ס שהוא בחי' כמראה אדם, וזהו דכתיב ריח ניחוח להוי'<sup data-n=\"365\">100</sup>, ריח הוא בחי' העלאה, ועי\"ז נמשך ניחוח הוא ל' המשכה<sup data-n=\"366\">101</sup> מל'",[["356","91","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["357","92","<b>ועל דמות. . מלמעלה</b>: יחזקאל א, כו."],["358","93","<b>ומגביהים. . אדם. . לא אדם</b>: ראה תו\"א יתרו עא, סע\"א ואילך. עב, ד ואילך. סה\"מ תרל\"ב ח\"א ע' יב ואילך וע' טו ואילך."],["359","94","<b>שכי לא אדם הוא</b>: שמו\"א טו, כט."],["360","95","<b>שרזא דקורבנא. . דא\"ס</b>: ראה סהמ\"צ להצ\"צ קנח, ב: ”ע' בפ' נח [סה, א] ובפקודי דרס\"ח ע\"ב ורס\"ט א'\". אוה\"ת ויקהל ע' ב'קלז: ”בזהר ח\"ג פ' צו דכ\"ו ב'. . וכ\"כ בזח\"א דס\"ה א'. . וכ\"כ בזח\"ב דרס\"ט ע\"א\". סה\"מ תרס\"ג ע' נג. תער\"ב ח\"ג ע' א'תלד. תש\"ט כאן ע' 31 בהערה: ”ראה זח\"ב רלט, א. זח\"ג כו, ב\". מאמר ד\"ה באתי לגני תשי\"ב פ\"ב (סה\"מ מלוקט א ע' כא). ד\"ה כי תבואו אל ארץ מושבותיכם תשי\"ב (סה\"מ תשי\"ב ע' 240). ד\"ה באתי לגני תשל\"ב פ\"ט (קונטרס יו\"ד שבט תשנ\"ב — סה\"מ מלוקט ו ע' צו)."],["361","96","<b>אין לו דמות הגוף</b>: ע\"פ פיוט יגדל. פיה\"מ להרמב\"ם מס' סנהדרין פ\"י היסוד הג'. ראה גם לקמן המשך חייב אדם לברך פ\"ג."],["362","97","<b>חסד. . גבורה. . ת\"ת. . בת\"ז</b>: בהקדמה יז, א."],["363","98","<b>חח\"ן. . בג\"ה. . דת\"י</b>: ראה זהר רע\"מ בהעלותך קנג, ב. פרדס שער סדר עמידתן ש\"ו, פ\"א. בד קודש פ\"ב (נדפס גם באגרות קודש כ\"ק אדמו\"ר האמצעי ח\"א ע' רצ ואילך). מאמרי אדה\"א בראשית ע' שיז. וש\"נ."],["364","99","<b>לאחזאה. . מדות כלל</b>: ת\"ז שם, ב."],["365","100","<b>ריח ניחוח להוי'</b>: ויקרא א, ט."],["366","101","<b>ריח. . העלאה. . ניחוח. . המשכה</b>: ראה סידור שחרית לג, ג. לו, ג. מאמרי אדה\"א שמות ח\"ב ע' שמג. וש\"נ. קונטרסים ע' תקעד. סה\"מ תרכ\"ט שבהערה הבאה."]]],[2000450092,"נחות דרגא<sup data-n=\"367\">102</sup> להוי' הוא בחי' כלליות הע\"ס שהאורות שבהם הם מבחי' ש' הוי'<sup data-n=\"368\">103</sup> כו'.\n<b>וזהו</b> דכתיב את קרבני לחמי לאשי<sup data-n=\"369\">104</sup>, שהקרבנות הם בחי' לחם לאשי הם בחי' אש שלי דהיינו השרפי' שנקראו שרפים ע\"ש שכבר נשרפו<sup data-n=\"370\">105</sup> ברשפי אש התשוקה ועומדים תמיד בבחי' רשפי אש תשוקה זו כמ\"ש שרפים עומדים ממעל לו<sup data-n=\"371\">106</sup> שעומדים בתמידות בבחי' רצוא, ונק' עומדים ג\"כ ע\"ש שעומדים תמיד במדריגה אחת<sup data-n=\"372\">107</sup>, הוא בחי' רצוא הנ\"ל, וזהו שאומרים קדוש<sup data-n=\"373\">108</sup>, פי' קדוש הוא לשון מובדל<sup data-n=\"374\">109</sup> והיינו שמשיגים איך שאוא\"ס הוא קדוש ומובדל בערך על כל העולמות, ואינו כמו בחי' הנשמה המחי' את הגוף שמתלבשת בגוף ומתפעלת ממקרי הגוף, אבל למעלה אינו כן שהרי אני הוי' לא שניתי<sup data-n=\"375\">110</sup> כתיב לפי שקדוש ומובדל מגדר עולמות ואינו מתלבש כלל בהם כ\"א זיו והארתו שאינו נוגע לעצמותו כלל וכלל זהו שנמשך בעולמות כו'. וזהו שאומרים ג\"פ קדוש ואח\"כ הוי' צבאות פי' שכדי שיהי' בבחי' צבאות אות הוא בצבא שלו<sup data-n=\"376\">111</sup>, ע' מזה בת\"א פ' בא בד\"ה בעצם היום<sup data-n=\"377\">112</sup> כו' צבאות ה', צ\"ל ג' בחי' צמצומים וזהו ג\"פ קדוש<sup data-n=\"378\">113</sup>, שקדוש הוא קדש וא\"ו שהוא\"ו מורה על ההמשכה<sup data-n=\"379\">114</sup> רק בדרך קו וצמצום מבחי' קדש, וע\"י ג' בחי' צמצומים אלו יכול להיות אח\"כ בחי' צבאות אות הוא כו'. ומפני כי השרפים משיגים זאת איך שהוא ית' קדוש ומובדל מגדר עולמות לגמרי עי\"ז נעשה אצלם הרצוא והתשוקה לצאת מנרתק הגבלתם וליכלל וליבטל בבחי' אוא\"ס ממש, ועומדים תמיד בבחי' רצוא זה, וכנודע שיש שרפים שאומרים פעם הג' קדוש<sup data-n=\"380\">115</sup> משי\"ב, שאחר אמירת פ\"א קדוש עמדו",[["367","102","<b>ניחוח. . מל' נחות דרגא</b>: יבמות סג, א. ראה (בנוסף לדרושים שבהערה 71] סידור שם. מאמרי אדה\"ז הקצרים ע' צה [נדפס בלקו\"ת שמ\"ע צב, ד]. תו\"ח תרומה ח\"ב שה, ד ובהערה 57. סה\"מ תרכ\"ט ע' קיב־ ע' קכו. וש\"נ. ד\"ה באתי לגני תשכ\"ח פ\"ב (קונטרס י' שבט תשמ\"ח — סה\"מ מלוקט ב ע' רמ]."],["368","103","<b>שהאורות. . ש' הוי'</b>: ראה גם לעיל המשך וידבר וגו' ויצוום ספי\"ג ובהערה 262."],["369","104","<b>את קרבני לחמי לאשי</b>: פינחס כח, ב. ראה בהבא בסמוך [בנוסף להנסמן בהערה 71] לקו\"ת פינחס עז, ד. סה\"מ תרכ\"ט ע' קו."],["370","105","<b>שרפים ע\"ש שכבר נשרפו</b>: ראה לקו\"ת נשא כח, ד. סה\"מ תרכ\"ט שם. תר\"ל ע' צב. לעיל המשך וידבר וגו' ויצוום על יד הערה 138. מאמר ד\"ה כי תבואו אל ארץ מושבותיכם תשי\"ב (סה\"מ תשי\"ב ע' 240)."],["371","106","<b>שרפים עומדים ממעל לו</b>: ישעי' ו, ב. ראה גם לקו\"ת אמור לב, ב. לעיל המשך וידבר וגו' ויצוום על יד הערה 136."],["372","107","<b>עומדים. . במדריגה אחת</b>: ראה גם סה\"מ תרכ\"ז כאן ע' קלד. תרס\"ה ר\"ע קמ."],["373","108","<b>שאומרים קדוש</b>: ישעי' ו, ג. ראה חולין צא, סע\"ב ובתוד\"ה ברוך (שם צב, א)."],["374","109","<b>קדוש. . מובדל</b>: ראה תניא פמ\"ו (סו, א). תו\"ח וארא ח\"א נא, ד ובהערה 10."],["375","110","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["376","111","<b>אות הוא בצבא שלו</b>: ראה חגיגה טז, רע\"א. תו\"ח שבהערה הבאה וש\"נ."],["377","112","<b>בת\"א. . היום</b>: ראה שם ס, ב ואילך. תו\"ח בא ח\"א קיד, ד ואילך."],["378","113","<b>ג' בחי' צמצומים. . ג\"פ קדוש</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' קנד. תו\"ח וארא ח\"א נח, ב. וש\"נ. משפטים רפז, סע\"ג ואילך. אוה\"ת ישעי' כרך ב' ס\"ע תשע ואילך."],["379","114","<b>שקדוש הוא קדש וא\"ו. . ההמשכה</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רסג. וש\"נ. תו\"ח וארא שם. וש\"נ."],["380","115","<b>שרפים שאומרים פעם הג' קדוש</b>: ראה גם סה\"מ תרכ\"ו ס\"ע צה ואילך. תר\"ל ע' קמא. תרל\"ו ח\"ב ע' תעח. תרל\"ד ע' שפה. תרח\"ץ כאן ע' רלא. תש\"ח ע' 82 (ובהערה לשם)."]]],[2000450093,"בבחי' הביטול ב' אלפים שנה, וכן אחר אמירת פ\"ב קדוש עמדו ג\"כ בבחי' ביטול ב' אלפים שנה ועכשיו הם בבחי' הביטול מאמירת קדוש פעם הג' כו', ולכן נק' שרפים ע\"ש הרשפי אש<sup data-n=\"381\">116</sup> התשוקה לעלות למעלה כטבע האש שעולה למעלה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ע\"י העלאת הקרבן ע\"י החיות מנשאות את בחי' אדם הוא ג' קווין לאוא\"ס בחי' כי לא אדם הוא, לחמי לאשי אש שלי הם בחי' השרפים שעומדים ברשפי אש ואומרים שקדוש<sup data-n=\"382\">117</sup> שמשיגים איך שקדוש ומובדל לגמרי ועי\"ז הם בבחי' אש התשוקה להיבטל ולהיכלל כו'.</span>\nוא\"ו) <b>והנה</b> הקרבנות<sup data-n=\"383\">118</sup> הם ג\"כ בבחי' אש<sup data-n=\"384\">119</sup>, כי הנה ידוע שדצח\"ם הוא כנגד ארמ\"ע<sup data-n=\"385\">120</sup>, והיינו דומם הוא בחי' יסוד העפר וצומח הוא כנגד יסוד המים כי מים מצמיחים כל מיני צמחה כמ\"ש וכל שיח השדה כו' וכל עשב הארץ<sup data-n=\"386\">121</sup> טרם יצמח כי לא המטיר כו', וחי הוא כנגד בחי' יסוד האש<sup data-n=\"387\">122</sup>, כי החמימות הוא מיסוד האש, ומדבר הוא כנגד יסוד הרוח כמ\"ש ויהי האדם לנפש חי' ותרגומו לרוח ממללא<sup data-n=\"388\">123</sup>, ונמצא מובן כי הקרבת הבהמות ע\"ג המזבח בחילוק היסודות<sup data-n=\"389\">124</sup> ז\"ע הקרבת יסוד האש להיות עולה ונכלל בבחי' אש של השרפים, וזהו דכתיב לחמי לאשי, שכמו שהלחם הגשמי שהאדם שלמטה אוכל שבכח האכילה יוכל לילך ולעלות למקום חפצו כמ\"ש באלי' וילך בכח האכילה ארבעים יום<sup data-n=\"390\">125</sup>, כן הקרבות הקרבנות הם בחי' לחם לבחי' האישים הם השרפים<sup data-n=\"391\">126</sup> שבכח אכילה זו יתוסף בהם חיות להיות נושאות את הכסא עם בחי' אדם שעל הכסא לבחי' אוא\"ס שכי לא אדם הוא כו'.\n<b>ועכשיו</b> תפילה במקום קרבנות תקנו<sup data-n=\"392\">127</sup>, כי שרש ענין התפילה הוא להקריב נפשו הבהמית שתוכלל למעלה בשרש שרשה, שהוא ג\"כ מבחי' פני שור",[["381","116","<b>שרפים ע\"ש הרשפי אש</b>: ראה גם בהמצויין בהערה 71."],["382","117","<b>שקדוש</b>: כ\"ה גם בב."],["383","118","<b>והנה הקרבנות</b>: להבא להלן ראה לקו\"ת פינחס עה, ד."],["384","119","<b>הקרבנות. . אש</b>: ראה בסמוך בפנים. מאמר ד\"ה כי תבואו אל ארץ מושבותיכם תשי\"ב (סה\"מ תשי\"ב ע' 239)."],["385","120","<b>שדצח\"ם הוא כנגד ארמ\"ע</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"י. וראה גם (בנוסף להערה 71) מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קנא. מאמרי אדה\"א הנחות תקע\"ז ע' רז. וש\"נ. ביאוה\"ז סידור ומאמרי אדה\"ז שבהערה 122."],["386","121","<b>וכל שיח. . וכל עשב הארץ</b>: בראשית ב, ה [ושם: עשב השדה — וכ\"ה בסה\"מ תרח\"ץ כאן]."],["387","122","<b>וחי. . יסוד האש</b>: ראה לקו\"ש יתרו כרך ו' ע' 112 הערה 42. ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"א. ביאוה\"ז בשלח מד, א. אמור קמב, ב. לקו\"ת שלח מ, ב. פינחס עה, סע\"ד. תצא לד, ג. סידור שחרית לג, סע\"א ואילך. מאמרי אדה\"ז תקס\"ה ח\"א ע' תפד ואילך."],["388","123","<b>ויהי האדם. . לרוח ממללא</b>: בראשית ב, ז ובתרגום אונקלוס שם."],["389","124","<b>היסודות</b>: תוקן ע\"פ ב."],["390","125","<b>וילך בכח האכילה ארבעים יום</b>: מל\"א יט, ח [ושם: האכילה ההיא]."],["391","126","<b>האישים הם השרפים</b>: ראה גם סה\"מ תרכ\"ט ע' קו וע' קיב. לעיל פ\"ה."],["392","127","<b>תפילה במקום קרבנות תקנו</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."]]],[2000450094,"שבמרכבה, רק שהוא מבחי' פני אדם שבפני שור<sup data-n=\"393\">128</sup> כי ד' פנים לאחת, ואמנם מפני כי נה\"ב שבאדם ירד מטה ונתלבש בגוף גשמי ומשוקע ברצונות זרות שרחוקה היא מאוד מה' אחד יחיד ומיוחד לזאת תקנו שתיים שלפני<sup data-n=\"394\">129</sup> ק\"ש שברכת יוצר היא אריכות הסיפור מענין ביטול והתפעלות המלאכים<sup data-n=\"395\">130</sup> באהוי\"ר איך שעומדים ברום עולם ומשמיעים ביראה כו', והשרפים אומרים קדוש, והאופנים וחיות הקדש מתנשאים לעומת השרפים ואומרים ברוך כו', וע\"י בחי' אריכות ההתבוננות שמתבונן איך שהשרפים וחיות הקדש אומרים קדוש וברוך ובטלים בתכלית לאלקות עי\"ז נקרב נפשו הבהמית ג\"כ ששרש שרשה גם משם ורוצה גם היא ליכלל ולבטל להיות ואהבת בכל לבבך בשני יצריך<sup data-n=\"396\">131</sup>, ועי\"ז נעשה עלי' לנה\"א<sup data-n=\"397\">132</sup> כמ\"ש במ\"א וז\"ע ק\"ש שהוא למסור נפשו באחד<sup data-n=\"398\">133</sup> שהוא בחי' ביטול של נה\"א שהוא העלי' לאוא\"ס ב\"ה כמו והחיות נושאות כו', כי התפעלות נה\"א<sup data-n=\"399\">134</sup> היא ג\"כ מהתבוננות אוא\"ס ממש דהיינו איך שאני הוי' לא שניתי וכולא קמי' כלא חשיב<sup data-n=\"400\">135</sup> ממש כמ\"ש במ\"א, וזהו ענין העבודה שהיא בחי' עבודת הקרבנות, ועכשיו תפילה במקום קרבנות לזבוח את יצרו<sup data-n=\"401\">136</sup> להיות ואהבת בכל לבבך בשני יצריך כו'.\n<span data-k=\"ks\"><b>קיצור.</b> בע\"ח הם כנגד יסוד האש, וא\"כ הקרבת הקרבנות זהו העלאת יסוד האש להיות עולה ונכלל באש השרפים, וזהו לחמי לאשי שבכח אכילת לחם זה ינשאו את הכסא כו', ועכשיו תפילה במקום קרבנות, ולכן הקדימו שתיים לפני' איך שהשרפים והאופנים אומרים קדוש וברוך ועי\"ז יתפעל הנה\"ב ששרשו משם להיות ואהבת בכל לבבך בשני יצריך שז\"ע לזבוח את יצרו כו'.</span>\nז) <b>אך</b> עדיין צ\"ל מ\"ש כי חסד חפצתי ולא זבח שלכאורה כל עיקר ענין ירידת הנשמה בגוף הוא להעלות הנה\"ב שז\"ע זבח, אך הענין הוא דפי' חסד חפצתי שחפץ הוא בחי' פנימיות הרצון<sup data-n=\"402\">137</sup> וכנודע ממ\"ש במ\"א בענין רצון וחפץ, שרצון הוא בחי' חיצוני' הרצון, וחפץ הוא בחי' פנימיות, ועיקר בחי' פנימיות הרצון זהו בחי' החסד היינו שיהי' נמשך המשכת אלקותו ית' למטה, כי נתאוה הקב\"ה",[["393","128","<b>נפשו הבהמית. . פני אדם שבפני שור</b>: ראה (בנוסף להערה 71) שערי אורה ח, א הערה 15. סה\"מ תרכ\"ט ס\"ע קכז."],["394","129","<b>שלפני</b>: אולי כצ\"ל."],["395","130","<b>שברכת יוצר. . ביטול והתפעלות המלאכים</b>: ראה גם סה\"מ תרכ\"ז כאן ע' קלו. וש\"נ."],["396","131","<b>ואהבת. . בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, ב במשנה. ראה (בנוסף להערה 71) שערי אורה ו, א הערה 9."],["397","132","<b>עלי' לנה\"א</b>: ראה תו\"א יתרו עא, ג. לקו\"ת ויקרא ב, ב."],["398","133","<b>למסור נפשו באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["399","134","<b>התפעלות נה\"א</b>: ראה גם סה\"מ תרכ\"ז כאן ע' קלו. וש\"נ."],["400","135","<b>וכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ, א (ז, רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["401","136","<b>לזבוח את יצרו</b>: ראה סנהדרין מג, ב."],["402","137","<b>שחפץ. . פנימיות הרצון</b>: ראה שו\"ת הצ\"צ אבה\"ע ח\"ב סרס\"ג (ח, ג). לקו\"ת שה\"ש כח, ד. וש\"נ. תו\"ח בא ח\"א קכה, ד ובהערה 597."]]],[2000450095,"להיות לו ית'<sup data-n=\"403\">139</sup> דירה בתחתונים<sup data-n=\"404\">138</sup>, רק שזה א\"א בלתי זבח שהוא בחי' ההעלאה, ולכן גם בזבח יש רצון אבל לא חפץ ולכן גבי בחי' חפץ אמר ולא זבח, אבל עכ\"ז כל התורה מליאה מקרבנות להיותם בחי' רצון העליון כו'. והמשל<sup data-n=\"405\">140</sup> בזה מאדם שנסע לקנות סחורה שיש לו רצון בנסיעה זו, אבל לא זהו עיקר המכוון, כ\"א עיקר כוונתו הוא שירויח כדי להחיות נפשו וב\"ב, וא\"ל הרויח לא הי' רוצה כלל בהנסיעה, ורק מפני רצונו בהרוחים רצונו בהנסיעה ג\"כ כי א\"א להרויח בלתי הנסיעה כו', ועד\"ז יובן ענין כי חסד חפצתי ולא זבח, שעיקר פנימיות רצונו הוא בבחי' חסד, אך מ\"מ יש לו רצון גם בבחי' הזבח רק שהוא בחי' חיצוני' הרצון לבד כי עיקר המכוון הוא להיות המשכת אלקות מלמעלמ\"ט כי נתאוה הקב\"ה להיות לו ית' דירה בתחתונים ועכשיו תפילה במקום קרבנות הגם כי יש לו רצון בבחי' הזבח שהוא לזבוח את יצרו עכ\"ז עיקר המכוון הוא שיהי' ע\"י העלאה זו המשכה אח\"כ וזהו ב' עמודים דתורה וגמ\"ח שהם המשכות מלמעלה למטה שהוא בחי' חסד שגמ\"ח הוא חסד וגם תורה נק' תורת חסד<sup data-n=\"406\">141</sup>. ועפ\"ז יובן מארז\"ל (ר\"ה די\"ח א' יבמות דק\"ה א') ע\"פ אם יתכפר<sup data-n=\"407\">142</sup> עון בית עלי בזבח ובמנחה בזבח ובמנחה אינו מתכפר, אבל מתכפר בתורה ובגמ\"ח רבה דעסיק בתורה חי מ' שנין<sup data-n=\"408\">143</sup> אביי דעסיק בתו' ובגמ\"ח חי שיתין שנין והיינו מפני כי חסד חפצתי המשכות אלקות מלמעלמ\"ט ולא זבח העלאות לבד, (וצ\"ל מ\"ש מנחה היינו קרבן מנחה, דאילו מנחה שבעולה דכתי' ועשירית האיפה (במדבר ך\"ח<sup data-n=\"409\">144</sup> ) יתבאר לקמן שזהו בחי' המשכה, ולכן גם בקרבנות הי' ג\"כ בחי' המשכה<sup data-n=\"410\">145</sup>, וזהו שארז\"ל כל הקורא ק\"ש בלא תפילין<sup data-n=\"411\">146</sup> כאילו הקריב עולה בלא מנחה וזבח בלא נסכים, ולכאו' מ\"ע דמיונם זל\"ז אך לפי הנ\"ל יתורץ היטיב דהנה הקרבנות הם בחי' זבח העלאה מלמטלמ\"ע שהוא אש כנ\"ל אבל נסכים ומנחה שהם יין ומנחת סולת שבעולה הם בחי' צומח שהם נגד יסוד המים כנ\"ל, ומים יורדין מגבוה לנמוך<sup data-n=\"412\">147</sup> שז\"ע המשכת אלקות מלמעלמ\"ט, ולכן דימו ק\"ש ותפילין להם שק\"ש היא בחי' העלאה רצוא בכל לבבך בשני יצריך לזבוח את יצרו, ותפילין הם המשכת מוחין לז\"א שה\"ע המשכת אלקות מלמעלמ\"ט, והוקשה כל התורה",[["403","139","<b>ית'</b>: ראה גם סה\"מ תרכ\"ט ע' רט. מכתב כ\"ק אדמו\"ר (מהוריי\"צ) נ\"ע לריזיק מח' אדר ב' תרפ\"ט (נדפס ברשימות חוב' קפד ע' 5). שיחת ליל ב' דחה\"פ תשי\"ב פסקא מה נשתנה (שיחות קודש תשי\"ב כרך ג ע' 253 ס\"ה). לקו\"ש דברים כרך יט ע' 27 ואילך."],["404","138","<b>נתאוה. . דירה בתחתונים</b>: ראה תניא רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. שערי אורה צז, ב. סה\"מ תרל\"ד ע' רמו ואילך. תרל\"ה ח\"א ע' קעא. וש\"נ. לקו\"ש שמות כרך ו' ע' 21 ואילך. אג\"ק שלו ח\"ה ס\"ע קצא ואילך."],["405","140","<b>בזבח יש רצון אבל לא חפץ. . והמשל</b>: ראה סה\"מ מלוקט שבהערה 71 ובהערות לשם."],["406","141","<b>תורה נק' תורת חסד</b>: ראה משלי לא, כו. תו\"א ויקהל פח, ב. ד. תו\"ח בשלח ח\"א רמד, ג ובהערה 197. סה\"מ תרל\"ו ח\"ב ע' רסא."],["407","142","<b>מארז\"ל. . אם יתכפר</b>: בשינוי קצת. וראה גם סה\"מ תרכ\"ז רפב בשולי היריעה. שמו\"א ג, יד."],["408","143","<b>רבה. . חי מ' שנין</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' פב בהערה."],["409","144","<b>ועשירית האיפה (במדבר ך\"ח)</b>: פסוק ה."],["410","145","<b>המשכה</b>: כ\"ה גם בב: ואולי צ\"ל: המשכה)."],["411","146","<b>כל הקורא ק\"ש בלא תפילין</b>: ברכות יד, סע\"ב. ראה לקו\"ת שלח מב, א. מאמרי אדה\"א במדבר ח\"ג ס\"ע א'רא ואילך. אוה\"ת על מארז\"ל ע' יא."],["412","147","<b>ומים יורדין מגבוה לנמוך</b>: ראה תענית ז, א."]]],[2000450096,"לתפילין<sup data-n=\"413\">148</sup>, שכמו התפילין הם המשכת אלקות למטה שכותבים ה' אחד על קלף גשמי כמו\"כ כל המצות הם המשכת אלקותו ית' למטה, ולכן אמרו כל הקורא ק\"ש רצוא בלא תפילין בחי' שוב כאילו הקריב עולה העלאה בלא מנחה המשכה, והעיקר הוא בחי' חסד כמ\"ש כי חסד חפצתי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שיש ב' בחי' חפץ ורצון, וחפץ הוא פנימיות הרצון וזהו בחסד דוקא בחי' המשכת אלקות למטה, כי נתאוה הקב\"ה להיות לו ית' דירה בתחתונים, ולכן גם בקרבנות הי' מנחה ונסכים, וגם עכשיו הקורא ק\"ש רצוא בלא תפילין שוב כאילו הקריב עולה העלאה בלא מנחה המשכה והעיקר ההמשכה כי חסד חפצתי כו'.</span>\nח) <b>ועפ\"ז</b> יובן מה שלא הרחיקו רז\"ל מאיסור ריבית לגמרי והתירו ה\"ע<sup data-n=\"414\">149</sup>, דהנה נת\"ל שירידת הנשמה בגוף היא בחי' עיסקא ולכן שניהם נוטלים השכר הנותן והמקבל, והיינו השכר להנשמה מה שעי\"ז מתעלית למעלה מעלה ומעלה הנה\"ב לשרשה, והנה\"ב גדלה ורב כוחה להעלות הנה\"א שיעלה בעילוי אחר עילוי כמ\"ש מזה בת\"א בד\"ה בך\"ה בכסליו<sup data-n=\"415\">150</sup>, אמנם לא זהו עיקר המכון כ\"א מה שע\"י העלאה זו נמשך המשכת אלקותו מלמעלמ\"ט כי חסד חפצתי שז\"ע כל ההמשכות שנמשך עכשיו להוסיף אורות באצי' לע\"ל יתגלה זה למטה וזהו עיקר המכוון כי נתאוה הקב\"ה להיות לו ית' דירה בתחתונים כו', ואמנם בענין חילוק השכר בין הנותן והמקבל א\"א להיות בשוה שזהו ריבית ולכן אי פלגא באגרא תילתא בהפסד, וממילא מובן שאם המקבל מקבל פלגא בהפסד צריך לקבל תרי תילתא באגרא, ומצינו בדרז\"ל בפ\"ט דשבת דפ\"ט ע\"ב<sup data-n=\"416\">151</sup> שהנותן שהוא הקב\"ה מקבל פלגא בהפסד, שאמרו שם שלע\"ל יאמרו ליצחק כי אתה אבינו, שהשיב דל ך' שני דלא ענשת, דל פלגא דלילותא דל פלגא דצלוי ומיכלא כו' פשו י\"ב וחצי, אם סובל אתה כולם מוטב, וא\"ל פלגא עלך ופלגא עלי נמצא שא\"ל יצחק שיקבל פלגא בהפסד, ולכן ע\"פ הע\"ס אינו מגיע להנותן כ\"א תילתא באגרא, ולכן מצינו בדרז\"ל במד\"ר בענין מ\"ש קדושים תהיו<sup data-n=\"417\">152</sup> משל למלך שעשו לו בני המדינה ג' עטרות נטל אחד ונתן בראשו ושניים בראש בניו, וזהו קדושים תהיו, והייתם קדושים, כי קדוש אני<sup data-n=\"418\">153</sup>, שנטל לעצמו רק חלק שליש עטרה אחת ושניים נתן בראש בניו שהם המקבלים כו', ולכן התירו היתר עסקא להיות כי בכלליות ירידת הנשמה בגוף כן הוא כו'.",[["413","148","<b>והוקשה כל התורה לתפילין</b>: ראה קדושין לה, א. סידור ערב שבת קסד, ב. תו\"ח וארא ח\"א סט, ב הערה 423. סה\"מ תרכ\"ט ע' רכה. לקו\"ש חנוכה כרך ה ע' 226."],["414","149","<b>ה\"ע</b>: היתר עיסקא."],["415","150","<b>בת\"א בד\"ה בך\"ה בכסליו</b>: כט, ב ואילך."],["416","151","<b>בפ\"ט דשבת דפ\"ט ע\"ב</b>: בשינויים."],["417","152","<b>במד\"ר. . קדושים תהיו</b>: ראה ויק\"ר פכ\"ד, ח. קדושים יט, ב. וראה גם בהבא לקמן סה\"מ תרכ\"ו ע' (פ) פא. תרכ\"ט ע' עה ור\"ע קפו."],["418","153","<b>והייתם קדושים כי קדוש אני</b>: שמיני יא, מד."]]],[2000450097,"<span data-k=\"ks\"><b>קיצור.</b> ירידת הנשמה בגוף זהו עיסקא, ויצחק אמר שיקבל הקב\"ה פלגא בהפסד, ולכן מקבל השכר רק שליש שנטל א' בראשו ושניים נתן בראש בניו, ולכן התירו חז\"ל היתר עיסקא.</span>"],[2000450098,"<h3>גומל נפשו איש חסד כו'</h3>\n<b></b>בתפילה ב' פי' כו' כנגד תמידין, קטורת - (ט-יא)\nט) <b>אך</b><sup data-n=\"419\">154</sup> עדיין צ\"ל משנת\"ל שעכשיו תפילה במקום קרבנות שהוא בחי' עמוד העבודה בחי' העלאה מלמטלמ\"ע, הלא ארז\"ל בשבת ר\"פ מפנין דקך\"ז סע\"א וע\"ב, ר' יוחנן דקחשיב התם עיון תפלה מן הששה דברים שאדם אוכל פירותיהן בעוה\"ז, ופריך התם והתנן ריש פיאה אלו דברים כו' ולא חשיב אלא ג' דברים<sup data-n=\"420\">155</sup>, ומשני הא<sup data-n=\"421\">*156</sup> דהני בהני שייכי ופי' רש\"י עיון תפילה הוא בכלל גמ\"ח דכתיב גומל נפשו איש חסד<sup data-n=\"422\">156</sup>, ור\"י לפרושי מתניתין כו' וא\"כ לפ\"ז ה\"ה היפוך ממה שנת\"ל דתפילה היא במקום הקרבנות כו'. אך הענין הוא דצ\"ל פי' הפסוק גומל נפשו איש חסד, דהנה בפי' גומל יש ב' פי' הא' לשון ויגמול שקדים (במדבר י\"ז ך\"ז<sup data-n=\"423\">157</sup> ) ומלשון ויגדל הילד ויגמל (בראשית ך\"א ח'), ובעבודה שצריך לגמול נפשו מבחי' מותרות שלא יומשך אחר תענוגי עוה\"ז שהם מותרות, וכ\"ש תאוות היתר שצריך להתרחק מהם מאד בתכלית הריחוק הרחק כמטחוי קשת<sup data-n=\"424\">158</sup>, ולגמול נפשו מהם לגמרי, והפי' הב' הוא מלשון אשירה להוי' כי גמל עלי (תילים י\"ג וא\"ו) גמל עלייכי (קי\"ו ז') שהוא לשון גמ\"ח שז\"ע המשכה לנפשו כמו מי שעושה גמ\"ח לחבירו שמשפיע לחבירו, ועד\"ז הוא פי' גומל נפשו כו' שמגמיל ומשפיע לנפשו כו'.\n<b>והנה</b> ב' פירושים אלו ישנם בתפילה דהנה ארז\"ל במשנה רפ\"ה דברכות אין עומדין להתפלל אלא מתוך כובד ראש ופי' רש\"י כובד הכנעה, שזהו כפי פי' הא' בתי' גומל לגמול נפשו מבחי' המותרות שזהו ע\"י היותו נכנע ושפל בעיני עצמו, משא\"כ מי שהוא בבחי' הגבהה ורוממות נצרך לו הכל ונדמה לו שמוכרח הוא שכ\"ז הוא ע\"י שט<sup data-n=\"425\">159</sup> נפשו ורוממות רוחו והגבהת לבו שפעל בעצמו, וההיפך מזה הוא ההכנעה ושפלות שעי\"ז יגמול נפשו מבחי' המותרות, ולפי פי' הב' גומל מל' גמ\"ח יובן עינינו בתפילה ע\"פ מה שנודע שהתפילה נק' בשם שפיכות הנפש<sup data-n=\"426\">160</sup>, כמ\"ש בחנה ואשפוך את נפשי<sup data-n=\"427\">161</sup> לפני הוי', פי' וענין נפשי הנה כתיב והר סיני עשן כולו<sup data-n=\"428\">162</sup>,",[["419","154","<b>אך</b>: במפתח הבוך נרשם כאן מאמר ד\"ה: גומל נפשו איש חסד (לפרקים ט — יא) היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם פתיחה זו נרשמה בפ\"ע גם ע\"י כ\"ק אדמו\"ר מהר\"ש.\nלמאמר זה ראה אוה\"ת משפטים ע' א'קנו וע' א'קסג ואילך. שם כרך ח ע' ג'כא ואילך. סה\"מ תרכ\"ז ע' קלז ואילך. תרכ\"ט ע' עא ואילך. תרס\"ה ע' קמב ואילך. מאמר ד\"ה ויאמר לו יהונתן ש\"פ משפטים תשכ\"ב. ד\"ה כי תשא תשכ\"ט. סה\"מ מלוקט שבהערה 71 ע' קפב ואילך."],["420","155","<b>ג' דברים</b>: כ\"ה גם בסה\"מ תרכ\"ז־ תרכ\"ט־ תרס\"ה־ מלוקט (ע' קפג) שבהערה שלפנ\"ז."],["421","*156","<b>הא</b>: כ\"ה גם בסה\"מ תרכ\"ז ותרס\"ה שם."],["422","156","<b>גומל נפשו איש חסד</b>: משלי יא, יז."],["423","157","<b>ויגמול שקדים (במדבר יז ך\"ז)</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן ע' קלז. ראה שם פסוק כג."],["424","158","<b>הרחק כמטחוי קשת</b>: וירא כא, טז."],["425","159","<b>שט</b>: ב: שאט."],["426","160","<b>שהתפילה. . שפיכות הנפש</b>: ראה פע\"ח בתחלתו. מאמרי אדה\"א דברים ח\"ב ע' תרסט. וש\"נ."],["427","161","<b>ואשפוך את נפשי</b>: שמו\"א א, טו."],["428","162","<b>והר סיני עשן כולו</b>: יתרו יט, יח."]]],[2000450099,"עש\"ן ר\"ת עולם שנה נפש<sup data-n=\"429\">163</sup>, עולם הוא בחי' מקום<sup data-n=\"430\">164</sup> ז' רקיעים וארץ וד' רוחות, ושנה הוא בחי' זמן, ונפש הוא בחי' חיות העולם, והיינו החיות שמחי' את כל העולם כולו, וכמ\"ש מזה בד\"ה ויצוום באריכות<sup data-n=\"431\">165</sup>, וז\"ע מלכותך מ' כל עולמים<sup data-n=\"432\">166</sup> שהוא בחי' מקור חיות כל העולמות, אמנם מאחר שנק' בשם נפש ה\"ה בחי' אחרונה כמו למשל בנפש האדם שיש ה' מדריגות נרנח\"י<sup data-n=\"433\">167</sup>, הנפש הוא בחי' אחרונה כי הדם הוא הנפש<sup data-n=\"434\">168</sup>, והוא בחי' החיות המתלבש בדם להחיות את הגוף, אבל רוח הוא מדריגה היותר גבוה, כי רוח הוא בחי' רוח החיים שבחלל הימני שבלב כו', ונשמה היא במוח שהוא בחי' שכל וכמ\"ש נשמת שדי תבינם<sup data-n=\"435\">169</sup>, וכמ\"ש בזהר זכה יתיר יהבין לי' מסטרא דנשמתא<sup data-n=\"436\">170</sup>, וחי' יחידה הם בחי' מקיפים<sup data-n=\"437\">171</sup>, נמצא שהנפש הוא בחי' אחרונה, כמו\"כ למעלה מה שנק' נפש היא בחי' אחרונה שהוא רק בחי' מל' כו', ונק' התפילה בשם שפיכות הנפש כי מל' נק' תפילה כמ\"ש ואני תפילה<sup data-n=\"438\">172</sup> ועמ\"ש מזה בד\"ה נפתלי אילה שלוחה<sup data-n=\"439\">173</sup>, והיינו שהתפילה היא להמשיך תוס' אור מבחי' ומדריגה יותר בבחי' נפש וכמ\"ש למען יזמרך כבוד<sup data-n=\"440\">174</sup> ולא ידום שפי' בזהר נהורא תתאה קארי תדיר<sup data-n=\"441\">175</sup> לנהורא עילאה ולא שכיך, והיינו שיומשך מבחי' יחיד בבחי' מלך וכמו שאנו אומרים יחיד חי העולמים מלך<sup data-n=\"442\">176</sup> שמבחי' יחיד נמשך ריבוי ותוס' אור בבחי' מלך, וע' בת\"א בד\"ה כי אתה נרי ובהביאור<sup data-n=\"443\">177</sup>, ובהגהות לשם<sup data-n=\"444\">178</sup>, ובד\"ה ואולם חי אני<sup data-n=\"445\">179</sup>, וזהו ע\"י התפילה כי",[["429","163","<b>עש\"ן ר\"ת עולם שנה נפש</b>: ראה הקדמת הראב\"ד לס\"י (ב, ג). פרדס שער הנתיבות שי\"ב ספ\"ה נתיב כג. שיעור קומה להרמ\"ק מערכת אדם סט\"ו (כח, ב). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שז. מאמרי אדה\"א במדבר ח\"ב ע' שלב ואילך וע' שלז ואילך. אוה\"ת יתרו ע' תתטז. ע' תתכג."],["430","164","<b>עולם הוא בחי' מקום</b>: ראה גם לקמן רפי\"ב. שער היחוה\"א פ\"ז ובמ\"מ הגהות והע\"ק שם. אוה\"ת חוקת ע' תתפד."],["431","165","<b>בד\"ה ויצוום באריכות</b>: נדפס לעיל — ראה שם פ\"י ובהערה 177."],["432","166","<b>מלכותך מ' כל עולמים</b>: תהלים קמה, יג."],["433","167","<b>נרנח\"י</b>: לקמן בהמשך חייב אדם לברך פכ\"ג על יד הערה 858 מציין כמ\"ש במד\"ר. ראה ב\"ר פי\"ד, ט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["434","168","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג. ראה שערי אורה צד, ב."],["435","169","<b>נשמת שדי תבינם</b>: איוב לב, ח [ושם: ונשמת וכ\"ה באוה\"ת כאן ס\"ע ג'כא. אבל ראה סה\"מ תרכ\"ז כאן ע' קלח. תרס\"ה ע' קמג. תו\"ח וארא ח\"א עט, ב ובהערה 463]. ראה תו\"ח ויקהל ח\"ב שצד, א."],["436","170","<b>זכה יתיר יהבין לי' מסטרא דנשמתא</b>: ראה זהר סבא משפטים צד, ב."],["437","171","<b>וחי' יחידה הם בחי' מקיפים</b>: ראה שעה\"י קכח, ב ובהערה 51. מאמרי אדה\"א קונטרסים ע' רנג. וש\"נ. לקמן מאמר ד\"ה זה עני על יד הערה 57."],["438","172","<b>מל'. . ואני תפילה</b>: תהלים קט, ד. ראה זהר תזריע מט, ב. פע\"ח שער התפלה בתחלתו. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצב. בהערה הבאה."],["439","173","<b>בד\"ה נפתלי אילה שלוחה</b>: סה\"מ תרכ\"ז ע' עב."],["440","174","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["441","175","<b>נהורא תתאה קארי תדיר</b>: ראה זהר היכלות פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["442","176","<b>שאנו אומרים. . מלך</b>: בברכת ברוך שאמר."],["443","177","<b>בת\"א בד\"ה כי אתה נרי ובהביאור</b>: מקץ מ, ג. מא, ב."],["444","178","<b>ובהגהות לשם</b>: אוה\"ת חנוכה שכא, א ואילך."],["445","179","<b>ובד\"ה ואולם חי אני</b>: ראה מאמרי אדה\"ז תקס\"ט ס\"ע קפה ואילך. סהמ\"צ להצ\"צ קעח, סע\"ב ואילך וע' רא. סה\"מ תרל\"ד ע' רמג."]]],[2000450100,"תפילה היא בחי' ח\"י ברכאן דצלותא<sup data-n=\"446\">180</sup> שהוא בחי' המשכה מלמעלמ\"ט בא\"ה<sup data-n=\"447\">181</sup> בבחי' מלך העולם, וז\"ע מאה ברכות<sup data-n=\"448\">182</sup> שהוא הכל להמשיך תוס' אור במל' בחי' נפש, וזהו יחיד חי העולמים מלך דהיינו שההמשכה מבחי' יחיד בבחי' מלך הוא ע\"י חי העולמים, היינו ח\"י ברכאן דצלותא שהם נגד ח\"י חוליות שבשדרה<sup data-n=\"449\">183</sup> שדרך בם נמשך ההמשכה מהמוח כידוע, וז\"ע גומל נפשו איש חסד שע\"י התפילה נמשך גמילות חסד בבחי' נפש שהוא בחי' מל' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> למשנ\"ת שתפילה במקום קרבנות, איך ארז\"ל עיון תפילה בכלל גמ\"ח, גומל ב' פי' מל' ויגמל לגמול מהמותרות ע\"י הכנעה בכובד ראש ב' גמל עלי ל' השפעה, ובתפילה ז\"ע שפיכות הנפש, נהורא תתאה קארי תדיר שעי\"ז יומשך מבחי' יחיד בבחי' מלך וזהו גמ\"ח עם נפשו בחי' מל' כו'.</span>\nיו\"ד) <b>ועדיין</b> צ\"ל מה שנת\"ל שהתפילה היא במקום קרבנות שהם בחי' העלאה ולא המשכה, אך הענין הוא דריב\"ל סובר שהתפילות במקום תמידין תקנו<sup data-n=\"450\">184</sup> (ברכות דך\"ו ע\"ב), דהנה ע\"י תמידין נקראו ישראל רעייתי, ופי' רז\"ל במד\"ר שה\"ש בפסוק לסוסתי דף י\"א ע\"א<sup data-n=\"451\">185</sup> מהו רעייתי א\"ר יונתן מפרנסתי הן שירעו אותי בשני תמידין בכל יום הה\"ד את הכבש האחד<sup data-n=\"452\">186</sup> תעשה בבקר כו', והיינו שעי\"ז הם בחי' רעייתי פרנסתי ישראל מפרנסי' לאביהם שבשמים<sup data-n=\"453\">187</sup>, והענין הוא שכמו למטה אנו רואים פעולת המאכל שהוא מחבר את הנפש עם הגוף, ובלתי המאכל הי' הנפש נפרד מן הגוף, ולא הי' לו אחיזה בגוף, כמו\"כ ישראל מפרנסין לאביהם שבשמים שהם ממשיכים המשכות אור א\"ס דלאו מכל אינון מידות איהו כלל, ואינו בערך המדות כלל שיומשך בע\"ס, והיינו ע\"י הקרבת התמידין נמשך התחברות אוא\"ס עם ע\"ס, וזהו ישראל מפרנסין לאביהם שבשמים, שמים הוא בחי' אש ומים<sup data-n=\"454\">188</sup> שהם בחי' מדות דאצי', ואביהם שבשמים הוא בחי' חכ', ואמנם המשכה זו הוא ע\"י העלאת הקרבן וכנ\"ל באריכות שעולה לשרשו עד שעי\"ז והחיות נושאות את הכסא עם כמראה אדם לבחי' אוא\"ס כי לא אדם הוא בחי' לאו מכל אינון מידות איהו כלל, ועי\"ז נמשך מבחי' אוא\"ס דלאו מכל אינון מדות בבחי' ע\"ס, וזהו ריח נחוח להוי' ריח הוא בחי' העלאה נחוח הוא בחי' המשכה להוי' מקור האורות דע\"ס",[["446","180","<b>ח\"י ברכאן דצלותא</b>: זהר בראשית כו, א."],["447","181","<b>בא\"ה</b>: ברוך אתה ה'."],["448","182","<b>מאה ברכות</b>: מנחות מג, ב. ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קכז."],["449","183","<b>ח\"י ברכאן. . ח\"י חוליות שבשדרה</b>: ראה זהר רע\"מ פינחס רנה, סע\"ב."],["450","184","<b>במקום תמידין תקנו</b>: ראה אוה\"ת משפטים כאן ע' א'קנו."],["451","185","<b>במד\"ר שה\"ש. . לסוסתי דף י\"א ע\"א</b>: בדפוס אמשטרדם ת\"א. בסה\"מ תרכ\"ז כאן ע' קלט ניתוסף: ובדפוס שקלאוו [תקע\"ד] ד\"ט ע\"ג. שהש\"ר פ\"א, ט (ו)."],["452","186","<b>את הכבש האחד</b>: תצוה כט, לט. וכ\"ה באוה\"ת כאן ע' ג'כב־ סה\"מ תרכ\"ט ותרס\"ה שבהערה 154. אבל במדרש שם: אחד — פינחס כח, ד."],["453","187","<b>ישראל מפרנסי' לאביהם שבשמים</b>: זהר ויקרא ז, ב. ראה גם תו\"ח משפטים ח\"ב רצג, ד הערה 52. סה\"מ תרכ\"ט ע' קיב."],["454","188","<b>שמים. . אש ומים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח. לקמן מאמר ד\"ה ואשא אתכם הערה 19."]]],[2000450101,"דאצי', וזהו ג\"כ כענין אכלו רעים לעילא שהם בחי' או\"א<sup data-n=\"455\">189</sup> שנק' רעים, והיינו שהוא בחי' המשכת אוא\"ס בבחי' חו\"ב, ותפילה כנגד תמידין תקנו שהיא ג\"כ העלאה והמשכה, שע\"י ההעלאה נעשה ההמשכה הוא בחי' המשכת אלקות מלמעלה למטה מבחי' יחיד<sup data-n=\"456\">190</sup> בבחי' ע\"ס כנ\"ל, ועש\"ז נק' התפילה סולם<sup data-n=\"457\">191</sup> ע' בלק\"ת בד\"ה כנשר יעיר, ובד\"ה יונתי בשה\"ש<sup data-n=\"458\">192</sup>, ובמ\"א בד\"ה ויחלום<sup data-n=\"459\">193</sup> והנה סולם, וכמ\"ש והנה סולם מוצב ארצה<sup data-n=\"460\">194</sup> וראשו מגיע השמימה שמחבר שמים בחי' מקיפים עליונים עם בחי' ארץ, ומלאכי<sup data-n=\"461\">195</sup> אלקים עולים ויורדים בו ענין העלי' והירידה זהו בחי' ההעלאה וההמשכה, ק\"ש הוא בחי' העלאה למסור נפשו באחד, ותפילה היא בחי' המשכה<sup data-n=\"462\">196</sup> כו', וזהו עולים ויורדים, וגם בתפילה עצמו גם לפי מה שנק' בשם שפיכות הנפש יש בה ג\"כ העלאה כענין הקרבנות, שהוא מה שנהורא תתאה קארי תדיר ולא שכיך זהו העלאה אלא שעי\"ז נמשך ההמשכה כנ\"ל שזהו כמו זבח ונסכים. וגם יובן ענין מה שהתפילה היא העלאה דוגמת הקרבנות, ע\"פ מה שנודע שלא כל הנשמה מלובשת בגוף<sup data-n=\"463\">197</sup>, שמה שמלובשת בגוף זהו רק הארה מקצת הנשמה לבד, ובכדי שיתחבר הארת הנשמה המלובשת בגוף לשרש ומקור הנשמה זהו ע\"י בחי' התפילה שע\"י התפילה עולה הארת נפשו המלובש בגוף להתקשר בשרש שרשה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> מה שתפילה היא במקום קרבנות זהו כריב\"ל שתפילה כנגד תמידין, רעייתי מפרנסתי, שממשיכים מאוא\"ס דלאו מכל אינון מידות בע\"ס, ישראל מפרנסין ע\"י העלאת הקרבן וכן בתפילה ע\"י העלאה ק\"ש, או גם בתפילה קארי תדיר עי\"ז נמשך מבחי' יחיד בבחי' מלך, שזהו כענין זבח ונסכים, וגם לפי שע\"י התפילה מתחבר הנשמה המלובש בגוף עם שרש הנשמה מלמעלמ\"ט.</span>\nיא) <b>ואמנם</b> יש עוד מעלה יתי'<sup data-n=\"464\">198</sup> בתפילה שהיא כנגד קטורת ג\"כ, וכמ\"ש תכון תפילתי קטרת לפניך<sup data-n=\"465\">199</sup>, ונודע כי הקטרת היו מקריבים על מזבח הפנימי<sup data-n=\"466\">200</sup>, והקרבת התמידין הי' על מזבח החיצון<sup data-n=\"467\">201</sup>, וכמו\"כ בתפילה יש ג\"כ שני",[["455","189","<b>אכלו רעים. . או\"א</b>: שה\"ש ה, א. זהר ויקרא ד, א."],["456","190","<b>יחיד</b>: תוקן ע\"פ ב."],["457","191","<b>התפילה סולם</b>: ראה זח\"א בהשמטות רסו, ב. ח\"ג תוספת שו, ב. ת\"ז תמ\"ה פג, א."],["458","192","<b>התפילה סולם.. בשה\"ש</b>: לקו\"ת האזינו עז, ד. שה\"ש טז, סע\"ד."],["459","193","<b>בד\"ה ויחלום</b>: אוה\"ת ויצא כרך ה תתלח, ב. תתמא, ב ואילך."],["460","194","<b>והנה סולם מוצב ארצה</b>: ויצא כח, יב."],["461","195","<b>ומלאכי</b>: שם: והנה מלאכי."],["462","196","<b>ק\"ש. . העלאה. . ותפילה. . המשכה</b>: ראה תו\"א בראשית א, ד. ז, ד ואילך. לקו\"ת מסעי פט, ב. ברכה צז, א. מאמרי אדה\"ז תקס\"ז ע' כח. ע' פה. ע' שצג. ענינים ע' שעז. שם ע' שפא ואילך."],["463","197","<b>שלא כל הנשמה מלובשת בגוף</b>: ראה לקו\"ת שה\"ש טז, ד. מאמרי אדה\"א דברים ח\"ב ע' תצח ואילך ובהנסמן בריש המאמר שם."],["464","198","<b>יתי'</b>: יתירה."],["465","199","<b>תכון תפילתי קטורת לפניך</b>: תהלים קמא, ב. ראה גם לקמן המשך חייב אדם לברך רפמ\"ב."],["466","200","<b>הקטרת. . מזבח הפנימי</b>: ראה תצוה ל, א. ז. ח. סה\"מ מ\"ע כח. רמב\"ם הל' כלי המקדש פ\"א, הי\"א. הל' תמידין ומוספין רפ\"ג."],["467","201","<b>התמידין. . מזבח החיצון</b>: ראה יתרו כ, כא. סה\"מ מ\"ע פד. רמב\"ם הל' ביהב\"ח פ\"א, ה\"ו. מעשי הקרבנות רפי\"ח."]]],[2000450102,"בחי' מזבח הפנימי ומזבח החיצון, והוא בחי' חיצוני' הלב ופנימיות הלב<sup data-n=\"468\">202</sup>, והיינו כי חיצוני' הוא בחי' הביטול של נה\"ב, כמו שעל מזבח החיצון היו מקריבים פרים ואילים וכבשים כן הקרבת נה\"ב ששרשו ג\"כ מבחי' פני אדם שבפני שור הוא ג\"כ ע\"י בחי' חיצוני' הלב שזהו בחי' מזבח החיצון והוא ע\"י ההתבוננות שבברכת יוצ\"א, איך שהשרפים אומרים קדוש והאופנים וחיוה\"ק ברעש גדול מתנשאים לעומת השרפים ואומרים ברוך כו', ועי\"ז מתפעל גם הנה\"ב כנ\"ל, ונכלל ובטל לנה\"א עד שפועל להיות ואהבת בכל לבבך בשני יצריך, אבל מ\"מ זהו רק חיצוני' הלב לבד, לפי שנמשך מהתבוננות שהיא ע\"פ הטעם ודעת שכ\"ז הוא מהארה בעלמא, אבל בעצמיות אוא\"ס ב\"ה לית מחשבה תפיסא בי' כלל, אבל נתפס הוא ברעד\"ל<sup data-n=\"469\">203</sup> היא בחי' עומק הלב שהוא ההתקשרות עצמיות של הנה\"א, וז\"ע קטרת כי קטרת היא לשון התקשרות<sup data-n=\"470\">204</sup>, וכמו שאמר רשב\"י בחד קטירא אתקטרנא, בי' אחידא בי' להיטא<sup data-n=\"471\">205</sup>, והוא בחי' רצון פשוט לאלקות עד שאינו רוצה בשום דבר זולתו ית', וכמ\"ש מי לי בשמים<sup data-n=\"472\">206</sup> ועמך לא חפצתי בארץ, שו\"א הם געה\"ת והעליון<sup data-n=\"473\">207</sup>, שלא יחפוץ בשו\"ד לא בג\"ע ולא בעוה\"ב שכ\"ז בכלל עמך, כי עמך מקו\"ח<sup data-n=\"474\">208</sup> כו' כ\"א לעצמותו ומהותו כו', וע\"ז כתיב שמן וקטרת ישמח לב<sup data-n=\"475\">209</sup>, שע\"י הקטורת נמשך בחי' שמן כי שמן שייך לקטורת כמ\"ש ובהעלות אהרן את הנרות<sup data-n=\"476\">210</sup> בה\"ע יקטירנה, ובשמן כתיב שמן ימינו יקרא<sup data-n=\"477\">211</sup> שהוא מלביש חסד דא\"א ע' בלק\"ת בד\"ה בהעלותך דרוש הראשון<sup data-n=\"478\">212</sup> ובד\"ה ואברהם זקן<sup data-n=\"479\">213</sup> מענין חסד של אמת חסד דקשוט, והוא בחי'",[["468","202","<b>מזבח הפנימי ומזבח החיצון. . הלב</b>: ראה [בנוסף להנסמן בהערה 154] לקו\"ת סוכות עח, ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז אתהלך לאזניא ע' קלב."],["469","203","<b>נתפס הוא ברעד\"ל</b>: ברעותא דליבא. ראה זהר אד\"ז האזינו רפט, ב. תו\"ח וישב קצט, ג ובהערה 56. שע\"ת קכה, א. סה\"מ תרכ\"ז ע' תלא ואילך. וש\"נ. תרכ\"ט ע' שפ. וש\"נ [ושם נדפס: תקס\"ג. וצ\"ל: תקס\"ז]."],["470","204","<b>קטרת היא לשון התקשרות</b>: ראה [בנוסף להנסמן בהערה 154] לקו\"ת נשא כב, ד. מאמרי אדה\"ז תקס\"ד ע' סז. תו\"ח תרומה ח\"ב שו, א ובהערה 71. אוה\"ת תולדות ס\"ע קנב ואילך. ויקהל ע' ב'רו. ישעי' ע' קעח. לקמן המשך חייב אדם לברך פל\"ט על יד הערה 1727. המשך יונתי תר\"ם ע' נז."],["471","205","<b>בחד קטירא. . להיטא</b>: ראה זהר אד\"ז האזינו רפח, א. רצב, א. מאמרי אדה\"א שמות ח\"ב ע' שכט. וש\"נ. תו\"ח לך צו, א ובהערה 3. שער האמונה צח, ב. ד\"ה פתח ר\"ש תשל\"ד (קונט' ל\"ג בעומר תשמ\"ט — סה\"מ מלוקט ח\"ג ע' קנא ואילך)."],["472","206","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה ישמח משה על יד הערה 56. סה\"מ תרמ\"ו ע' כ. תרע\"ח ע' תלג (במהדורת תשד\"מ). מאמר ד\"ה ביום עשתי עשר יום י\"א ניסן תש\"ל פ\"ח-ט (קונט' י\"א ניסן תשמ\"ט — סה\"מ מלוקט ג ע' קו-ז). מגדל עז ע' קעג. בהערה הבאה."],["473","207","<b>שו\"א הם געה\"ת והעליון</b>: ראה גם לקמן הנחה ד\"ה ישמח משה שם על יד הערה 57. תו\"ח תצוה ח\"ב שנו, ב ובהערה 24. סה\"מ תרכ\"ט ע' עב. ע' רו. ע' רכג. תרס\"ה ע' קמד."],["474","208","<b>כי עמך מקו\"ח</b>: תהלים לו, י."],["475","209","<b>שמן וקטרת ישמח לב</b>: משלי כז, ט."],["476","210","<b>ובהעלות אהרן את הנרות</b>: תצוה ל, ח."],["477","211","<b>שמן ימינו יקרא</b>: משלי כז, טז [ושם: ושמן — אבל כ\"ה גם במאמרי אדה\"ז תקס\"ב ח\"ב ע' תנז. אוה\"ת כאן ע' ג'כג־ סה\"מ תרכ\"ז ע' קמ־ תרכ\"ט ע' עב־ תרס\"ה ע' קמד (ושם: ימיני)]."],["478","212","<b>בלק\"ת בד\"ה בהעלותך דרוש הראשון</b>: ל, ד. ראה גם סה\"מ תרכ\"ז ע' כד."],["479","213","<b>ובד\"ה ואברהם זקן</b>: בסה\"מ תרכ\"ז כאן ע' קמ: (ך\"ז) — ראה שם ע' כט."]]],[2000450103,"כשמן הטוב היורד על הראש<sup data-n=\"480\">214</sup> ועל הזקן שהוא בחי' רב חסד שנמשך על הראש בחי' מוחין, כי אבא מלביש חסד דא\"א, וענין יורד על הזקן היינו בבחי' יגת\"ד בבחי' פנימיות השערות ועמ\"ש מזה במ\"א בשם הרמ\"ז בד\"ה בהעלותך שלא נדפס<sup data-n=\"481\">215</sup>, וזה ישנו גם בתפילה, ועפ\"ז יובן מה שנק' התפילה בשם גומל נפשו שעיון תפילה היא בכלל גמ\"ח שעיקר גמ\"ח הוא המשכת בחי' חסד עליון הנ\"ל ולכן אחר גמר התפילה יש בחי' נפ\"א שהוא בחי' מס\"נ<sup data-n=\"482\">216</sup> ממש כמ\"ש בזהר במדבר דק\"ך ע\"ב ודקך\"ג ע\"א<sup data-n=\"483\">217</sup> שכ\"ז הוא בחי' קטרת הנ\"ל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שיש עוד מעלה בתפילה דוגמת הקטרת שע\"ג מזבח הפנימי, שני מזבחות בעבודה הם בחי' חיצוני' הלב ופנימיות, הקרבת נה\"ב היא ע\"י בחי' חיצוני' הלב, אבל קטרת התקשרות נה\"א בחד קטירא כו' זהו ע\"י בחי' פנימיות עומק נקודת הלב, שמן וקטרת, שמן ימינו יקרא המשכת רב חסד חסד דקשוט שזהו עיקר גמ\"ח כו' ולכן תפילה גומל נפשו כו'.</span>",[["480","214","<b>כשמן הטוב היורד על הראש</b>: ע\"פ תהלים קלג, ב."],["481","215","<b>הרמ\"ז בד\"ה בהעלותך שלא נדפס</b>: לע\"ע לא נתברר לאיזה דרוש כוונתו. הרמ\"ז — ראה גם אוה\"ת נצבים ע' א'רעח ס\"ה."],["482","216","<b>נפ\"א. . מס\"נ</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' עו ואילך (נו\"א) ומסיים: כמ\"ש במ\"א ע\"ש. סידור שער התפלה כו, א-ב. שער נפ\"א צב, ד. שע\"ת שער התפלה פל\"ד — לט. מאמרי אדה\"א בראשית ע' תקכ. קונטרסים ר\"ע תקצח. תו\"ח וישלח קפו, סע\"ב ואילך. לקמן המשך חייב אדם לברך פכ\"ה על יד הערה 967. סה\"מ תרכ\"ז ע' קמ. וש\"נ תרכ\"ט ס\"ע עב ואילך. תרל\"ו ח\"ב ס\"ע שמא ואילך. ע' שנב ואילך. ע' שעד. תרס\"ה ס\"ע קמד."],["483","217","<b>ודקך\"ג ע\"א</b>: בסה\"מ תרכ\"ט ר\"ע עג: בזהר פ' במדבר. תרכ\"ז כאן ע' קמ: בזהר ס\"פ במדבר דק\"ך ע\"ב ודקך\"ג א' — הסיום דפ' במדבר הוא בדף קכא ועפ\"ז אוצ\"ל: דקך\"א א'."]]],[2000450104,"<h3>טוב איש חונן כו'</h3>\n<b></b>כי אמרתי עולם ב' פי' כו' קנין משיכה, כסף (יב-יג)\nיב) <b>והנה</b><sup data-n=\"484\">218</sup> על בחי' חסד זה יתפרש פי' הפסוק כי אמרתי עולם חסד יבנה<sup data-n=\"485\">219</sup> לפי פי' הא' בפסוק זה, כי בפי' פסוק זה יש ב' פי'<sup data-n=\"486\">220</sup> הא' שעיקר בריאות<sup data-n=\"487\">221</sup> העולם הי' מצד בחי' כי חפץ חסד<sup data-n=\"488\">222</sup> הוא<sup data-n=\"489\">223</sup>, שזהו בחי' חסד הנ\"ל, שכך",[["484","218","<b>והנה</b>: במפתח הבוך נרשם כאן מאמר ד\"ה: טוב איש חונן ומלוה (לפרקים יב-יג), היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם פתיחה זו נרשמה בפ\"ע גם ע\"י כ\"ק אדמו\"ר מהר\"ש.\nלמאמר זה ראה אוה\"ת משפטים ס\"ע א'קסד וע' א'קסו ואילך. שם כרך ח ע' ג'כה. סה\"מ תרכ\"ז ע' קמ. תרכ\"ט ע' עג. תרס\"ה ע' קמה. מאמר ד\"ה ויאמר לו יהונתן ש\"פ משפטים תשכ\"ב."],["485","219","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["486","220","<b>ב' פי'</b>: בסה\"מ תרכ\"ט ע' ט ועד\"ז ע' תו מציין: ע' מזה בד\"ה ולקחתם אגודת אזוב (ך\"ח). לא נדפס לע\"ע וראה בהערת המו\"ל שם. סה\"מ תרכ\"ז ע' קמ. וש\"נ."],["487","221","<b>בריאות</b>: וכ\"ה לקמן פי\"ג. המשך חייב אדם לברך פל\"א על יד הערה 1219 (ובהקיצור שם). ו(בחלק ההנחות) בהנחה ד\"ה לה\"ע אכילת מצה על יד הערה 42 (ב\"פ). ראה גם סה\"מ תרל\"ב ח\"ב ע' תמט. תרל\"ה ח\"א ע' רלו. לקו\"ש תצא כרך כט ע' 142 בשולי הגליון. לקלו\"י הערות לתניא פכ\"א (כז, א) ע' ה."],["488","222","<b>בריאות העולם. . חפץ חסד</b>: באוה\"ת כאן ע' א'קסד: כן משמע הפירוש בת\"י [ראה אוה\"ת (יהל אור) תהלים ע' שיד] וכן פי' הרמב\"ם בסוף ספרו מ\"נ [ח\"ג פנ\"ג ראה אוה\"ת שם ע' שטז]."],["489","223","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."]]]]});
